/* PeTTa named state belongs to an executing worker, independently of spaces
 * and transaction registry views. Its scope spans all jobs in one invocation. */
typedef struct {
    Registry local;
    Registry *previous;
    bool active;
} PettaWorkerStateScope;
static __thread Registry *g_petta_worker_named_state = NULL;

static void petta_worker_state_scope_enter(PettaWorkerStateScope *scope) {
    *scope = (PettaWorkerStateScope){.previous = g_petta_worker_named_state,
                                    .active = true};
    /* Only the state namespace is used; storage is allocated lazily. */
    g_petta_worker_named_state = &scope->local;
}

/* The saved TLS owner is separate from the mutable registry exposed to a
 * child. Restore it before releasing that registry's storage. */
static inline __attribute__((always_inline)) void petta_worker_state_scope_restore(
    PettaWorkerStateScope *scope, Registry *previous) {
    assert(scope && scope->active);
    assert(g_petta_worker_named_state == &scope->local);
    g_petta_worker_named_state = previous;
    registry_free(&scope->local);
    scope->active = false;
}

static void petta_worker_state_scope_leave(PettaWorkerStateScope *scope) {
    if (scope && scope->active)
        petta_worker_state_scope_restore(scope, scope->previous);
}

/*
 * The compiled occurrence plan belongs to exactly one top-level PeTTa
 * evaluation.  It is private metadata, scoped and restored by the public
 * planned entry point; nested machine-owned goals carry their plans
 * explicitly rather than consulting this slot.
 */
static __thread const PettaPlanNode *g_petta_source_plan = NULL;
/* The plan is positional metadata for exactly one source expression.  The
 * generic evaluator may descend into constructor children before the machine
 * is consulted, so the machine must ignore the slot unless the expression it
 * receives is the very atom the plan was compiled for; a stale root plan
 * would misassign roles (e.g. mark a known call as inert data). */
static __thread const Atom *g_petta_source_plan_atom = NULL;

/* Whether the top-level PeTTa directive now being evaluated raised an Error
 * it did not catch, when that is known; eval_top_with_registry_core keeps
 * it per outcome. */
typedef struct {
    bool known;
    bool raised;
} PettaDirectiveReport;
static __thread PettaDirectiveReport g_petta_directive_report;
/* Whether the machine run in progress answered with an uncaught Error. */
static __thread bool g_petta_machine_run_raised;

/* The directive's root was answered: by the relational machine, which tells
 * a raised Error from an Error value, or by a path that never raises, whose
 * Errors are values (the prepared pure program declines on any error). */
static void petta_directive_note_answer(const Atom *atom, bool raised) {
    if (!atom || atom != g_petta_source_plan_atom)
        return;
    g_petta_directive_report.known = true;
    g_petta_directive_report.raised = raised;
}

typedef struct {
    const PettaPlanNode *previous_plan;
    const Atom *previous_atom;
    bool active;
} PettaSourcePlanScope;

static void petta_source_plan_scope_leave(
        PettaSourcePlanScope *scope) {
    if (!scope || !scope->active)
        return;
    g_petta_source_plan = scope->previous_plan;
    g_petta_source_plan_atom = scope->previous_atom;
    scope->active = false;
}

/* The goals delayed by the machine whose host is evaluating, NULL when it
 * delays none: every machine created meanwhile starts from a copy of them
 * (petta_machine_inherit_delayed_goals). */
static __thread const CettaDelayService *g_petta_eval_delay_service = NULL;

typedef struct {
    const CettaDelayService *previous;
    bool active;
} PettaEvalDelayScope;

static void petta_eval_delay_scope_leave(PettaEvalDelayScope *scope) {
    if (!scope || !scope->active)
        return;
    g_petta_eval_delay_service = scope->previous;
    scope->active = false;
}

static void petta_eval_delay_scope_enter(PettaEvalDelayScope *scope,
                                         const CettaDelayService *service) {
    if (!scope)
        return;
    *scope = (PettaEvalDelayScope){
        .previous = g_petta_eval_delay_service,
        .active = true,
    };
    g_petta_eval_delay_service = service;
}

/* The variables the caller of one expression's evaluation reads from every
 * answer (PettaMachineHost.export_variables), for that expression only. */
static __thread Atom *g_petta_export_variables = NULL;
static __thread const Atom *g_petta_export_variables_atom = NULL;

typedef struct {
    Atom *previous_variables;
    const Atom *previous_atom;
    bool active;
} PettaExportVariablesScope;

static void petta_export_variables_scope_leave(
        PettaExportVariablesScope *scope) {
    if (!scope || !scope->active)
        return;
    g_petta_export_variables = scope->previous_variables;
    g_petta_export_variables_atom = scope->previous_atom;
    scope->active = false;
}

static void petta_export_variables_scope_enter(
        PettaExportVariablesScope *scope,
        Atom *variables, const Atom *atom) {
    if (!scope)
        return;
    *scope = (PettaExportVariablesScope){
        .previous_variables = g_petta_export_variables,
        .previous_atom = g_petta_export_variables_atom,
        .active = true,
    };
    g_petta_export_variables = variables;
    g_petta_export_variables_atom = variables ? atom : NULL;
}

static void petta_source_plan_scope_enter(
        PettaSourcePlanScope *scope,
        const PettaPlanNode *plan, const Atom *atom) {
    if (!scope)
        return;
    *scope = (PettaSourcePlanScope){
        .previous_plan = g_petta_source_plan,
        .previous_atom = g_petta_source_plan_atom,
        .active = true,
    };
    g_petta_source_plan = plan;
    g_petta_source_plan_atom = plan ? atom : NULL;
}

