/* Diagnostic configuration is process-constant and initialized once per
 * evaluator thread. Scope entry shares it with preparation admission; the
 * prepared call path never polls the request. */
static __thread uint64_t g_match_chain_progress = 0u;
static __thread bool g_match_chain_observer_configured = false;
static __thread bool g_match_chain_observer_diagnostic = false;
static __thread uint64_t g_match_chain_observer_interval = 100000u;

static bool match_chain_observation_env_enabled(const char *value) {
    return value && *value && strcmp(value, "0") != 0 &&
           strcmp(value, "false") != 0 && strcmp(value, "off") != 0 &&
           strcmp(value, "no") != 0;
}

static void match_chain_configure_observer(void) {
    const char *interval_text;
    char *end = NULL;
    unsigned long long parsed;

    if (g_match_chain_observer_configured)
        return;
    g_match_chain_observer_configured = true;
    g_match_chain_observer_diagnostic = match_chain_observation_env_enabled(
        getenv(CETTA_GSLT_MATCH_CHAIN_TRACE_ENV));
    interval_text = getenv(CETTA_GSLT_MATCH_CHAIN_TRACE_INTERVAL_ENV);
    if (!interval_text || !*interval_text)
        return;
    parsed = strtoull(interval_text, &end, 10);
    if (end && *end == '\0' && parsed > 0u)
        g_match_chain_observer_interval = (uint64_t)parsed;
}

static bool gslt_match_chain_trace_active(void) {
    match_chain_configure_observer();
    return g_match_chain_observer_diagnostic;
}

static bool eval_environment_flag_enabled(
    const char *name, bool default_value) {
    const char *value = getenv(name);
    if (!value || value[0] == '\0')
        return default_value;
    return strcmp(value, "0") != 0 &&
           strcmp(value, "false") != 0 &&
           strcmp(value, "off") != 0;
}

/* `Empty` is HE's no-result sentinel.  In Prime and in PeTTa `Empty` is
 * data (in PeTTa except as a `case` default), so their sentinel is the
 * internal atom no program can write.  Prime's choice zero has no occurrence
 * at all; a sentinel that reaches Prime, such as a native call's failure, is
 * dropped where results are collected, so the failure is zero answers and
 * never the datum `Empty`.  Route every evaluator-level sentinel test through
 * this predicate, and every sentinel through `legacy_empty_sentinel`, so a
 * value cannot acquire control authority by spelling itself `Empty`. */
static bool atom_is_legacy_empty_sentinel(Atom *atom) {
    CettaLanguageId language = eval_current_language_id();
    return language == CETTA_LANGUAGE_PETTA || language == CETTA_LANGUAGE_PRIME
        ? atom_is_petta_no_result(atom) : atom_is_empty(atom);
}

static Atom *legacy_empty_sentinel(Arena *a) {
    CettaLanguageId language = eval_current_language_id();
    return language == CETTA_LANGUAGE_PETTA || language == CETTA_LANGUAGE_PRIME
        ? atom_petta_no_result(a) : atom_empty(a);
}

static bool atom_is_legacy_empty_or_error(Atom *atom) {
    return atom_is_error(atom) || atom_is_legacy_empty_sentinel(atom);
}

/* The explicit choice-zero form is computation, not the datum `Empty`.
 * Keep its structural recognition shared by the canonical evaluator and
 * every accelerator admission boundary.  Each language adapter still owns
 * whether the form is visible to a particular realization. */
static bool atom_is_computation_zero_form(const Atom *atom) {
    CettaControlOperationPlan plan;
    return atom && atom->kind == ATOM_EXPR && atom->expr.len &&
        atom->expr.elems[0] && atom->expr.elems[0]->kind == ATOM_SYMBOL &&
        cetta_control_operation_decode(atom_symbol_current_id(atom->expr.elems[0]),
            atom->expr.len - 1u, &plan, &g_builtin_syms) &&
        plan.operation == CETTA_CONTROL_FAILURE;
}

CettaLibraryContext *eval_swap_library_context(
    CettaLibraryContext *next) {
    CettaLibraryContext *previous = g_library_context;
    g_library_context = next;
    g_active_language_id = next
        ? next->session.language_id : CETTA_LANGUAGE_HE;
    g_active_he_grounded_extensions = !next ||
        !cetta_language_uses_rust_he_compat_semantics(
            next->session.language_id, next->session.profile);
    g_active_dependent_telescope =
        next && next->session.profile &&
        next->session.profile->enable_dependent_telescope;
    g_context_self_policy = next && next->session.profile
        ? (int)next->session.profile->context_self : 0;
    cetta_prime_identity_policy_set(
        next && next->session.profile
            ? (int)next->session.profile->identity_policy
            : CETTA_PRIME_IDENTITY_J);
    /* Prime seals quotations against every binder, unless the session's
     * profile is the quote-as-written bubble. */
    prime_quote_seal_set(
        next && next->session.language_id == CETTA_LANGUAGE_PRIME &&
        !(next->session.profile && next->session.profile->quote_as_written));
    /* Prime's binding structure in the substitution every route shares:
     * a head the substitution fills forms its construct, and a variable
     * inside code reads as code (prime_semantics_binding_hooks). */
    bindings_structure_hooks_set(
        next && next->session.language_id == CETTA_LANGUAGE_PRIME
            ? prime_semantics_binding_hooks() : NULL);
    g_active_search_controller_requested = false;
    g_active_petta_search_machine = next
        ? eval_environment_flag_enabled(
              "CETTA_PETTA_SEARCH_MACHINE", true)
        : true;
    g_active_petta_machine_stats = next
        ? eval_environment_flag_enabled(
              "CETTA_PETTA_MACHINE_STATS", false)
        : false;
    g_active_petta_table_safety_trace = next &&
        getenv("CETTA_PETTA_TABLE_SAFETY_TRACE") != NULL;
    const char *controller = next
        ? getenv("CETTA_SEARCH_CONTROLLER") : NULL;
    g_active_search_controller_auto = false;
    g_active_selection_automaton_ready = false;
    if (controller) {
        CettaSearchControllerPolicy parsed;
        if (strcmp(controller, "auto") == 0) {
            g_active_search_controller_auto = true;
        } else if (cetta_search_controller_policy_parse(
                       controller, &parsed)) {
            g_active_search_controller = parsed;
            g_active_search_controller_requested = true;
            g_active_selection_automaton_ready =
                cetta_selection_automaton_parse(
                    controller, &g_active_selection_automaton);
        }
    }
    if (!g_prepared_thread_policy_ready) {
        prime_native_parallel_operations_select();
        prime_need_operation_boundaries_changed();
    }
    return previous;
}
