static __thread uint32_t g_metta_eval_depth = 0u;
/* A shared host leaf may re-enter the evaluator, but it cannot recursively
 * install a second PeTTa search machine around the same leaf. */
static __thread uint32_t g_petta_machine_host_depth = 0u;

typedef struct {
    bool reopened;
} PettaHostBranchGuard;

/* Once a host aggregate is dispatched, its independent branch may use the
 * ordinary owned evaluator. Keep the ban on recursively wrapping the host
 * leaf itself; restore it even when the branch ends in interruption. */
static PettaHostBranchGuard petta_host_branch_enter(void) {
    PettaHostBranchGuard guard = {
        .reopened = eval_current_language_id() == CETTA_LANGUAGE_PETTA &&
                    g_petta_machine_host_depth > 0u,
    };
    if (guard.reopened)
        g_petta_machine_host_depth--;
    return guard;
}

static void petta_host_branch_leave(PettaHostBranchGuard *guard) {
    if (guard->reopened) {
        g_petta_machine_host_depth++;
        guard->reopened = false;
    }
}
/* Stream consumers establish their observation demand over the dynamic
 * extent of producing the stream.  A nested evaluator can then derive its
 * control plan from the actual consumer without a language check or a
 * process-global mode. */
static __thread bool g_eval_observation_demand_present = false;
static __thread CettaObservationDemand g_eval_observation_demand;
/* The expression the demand observes.  A bound on its outcomes (a first
 * answer, a finite prefix) is not a bound on what it evaluates in turn: a
 * nested relation's outcomes are consumed by the expression around it,
 * which may need more of them than the bound. */
static __thread Atom *g_eval_observation_root = NULL;
/* The Prime expression of which an observation is about to demand only the
 * first `limit` outcomes; the evaluation stack that evaluates exactly this
 * expression stops once its root holds that many. */
typedef struct {
    Atom *root;
    uint64_t limit;
} PrimePrefixDemand;
static __thread PrimePrefixDemand g_prime_prefix_demand = {0};

typedef struct {
    bool entered;
    bool previous_present;
    CettaObservationDemand previous;
    Atom *previous_root;
} EvalObservationDemandGuard;

static EvalObservationDemandGuard eval_observation_demand_enter(
        CettaObservationDemand demand, Atom *root) {
    EvalObservationDemandGuard guard = {
        .entered = true,
        .previous_present = g_eval_observation_demand_present,
        .previous = g_eval_observation_demand,
        .previous_root = g_eval_observation_root,
    };
    g_eval_observation_demand = demand;
    g_eval_observation_demand_present = true;
    g_eval_observation_root = root;
    return guard;
}

static void eval_observation_demand_leave(
        EvalObservationDemandGuard *guard) {
    if (!guard || !guard->entered)
        return;
    g_eval_observation_demand_present = guard->previous_present;
    g_eval_observation_demand = guard->previous;
    g_eval_observation_root = guard->previous_root;
    guard->entered = false;
}

typedef struct {
    bool entered;
} MettaEvalDepthGuard;

static void metta_eval_depth_guard_leave(MettaEvalDepthGuard *guard) {
    if (!guard || !guard->entered)
        return;
    assert(g_metta_eval_depth > 0u);
    g_metta_eval_depth--;
    guard->entered = false;
}

static void prime_need_observe_top_answer(
    Atom *answer, const Bindings *env) {
    if (!answer || g_metta_eval_depth != 1u ||
        eval_current_language_id() != CETTA_LANGUAGE_PRIME ||
        !g_prime_need_answer_observer)
        return;
#if CETTA_BUILD_WITH_PRIME_CAUSAL_RECEIPTS
    const PrimeNeedReceipt *receipt = env
        ? bindings_receipt_view(env) : &g_prime_need_receipt_active;
    g_prime_need_answer_observer(
        answer, receipt, g_prime_need_answer_observer_context);
#else
    (void)env;
#endif
}

static inline __attribute__((always_inline)) void metta_observe_published_answer(
    PrimeTopResultCapture *capture,ResultSet *target,Atom *answer,const Bindings *environment) {
    if (capture && capture->target==target && capture->depth==g_metta_eval_depth &&
        !capture->append(capture->context,environment))
        eval_mark_interrupted(CETTA_EVAL_INCOMPLETE_CAPACITY);
    prime_need_observe_top_answer(answer,environment);
}

