StateCell *eval_resolve_state_read(StateCell *cell) {
    StateCell *redirect;
    if (!g_eval_payload_transactional || !cell)
        return petta_eval_private_state_image(cell);
    redirect = payload_state_redirect_for(cell);
    if (redirect)
        return redirect;
    cell=payload_outer_state_read(g_eval_payload_outer,cell);
    redirect=payload_state_redirect_for(cell);
    return redirect ? redirect : cell;
}

static Space *payload_resolve_space_write(Space *sp) {
    Space *redirect;
    sp = space_mutation_target(sp);
    if (g_library_context && g_library_context->import_space_alias_len)
        sp = cetta_library_import_execution_space(g_library_context, sp);
    if (!g_eval_payload_transactional || !sp)
        return petta_eval_private_space_image(sp);
    Space *original=sp;
    redirect=payload_space_redirect_for(sp);
    if (redirect) sp=redirect;
    else {
        sp=payload_outer_space_read(g_eval_payload_outer,sp);
        redirect=payload_space_redirect_for(sp);
        if (redirect) sp=redirect;
    }
    /* Being an overlay is not ownership: a parent frame's view must remain
     * unchanged when this child writes or retires. */
    if (payload_scratch_space_owned(sp))
        return sp;
    redirect = cetta_malloc(sizeof(Space));
    if (!redirect)
        return NULL;
    if (!space_init_overlay_local(redirect, sp)) {
        free(redirect);
        return NULL;
    }
    if (!eval_payload_track_scratch_space(redirect)) {
        space_free(redirect);
        free(redirect);
        return NULL;
    }
    if (!eval_payload_note_space_redirect(sp, redirect) ||
        (original!=sp && !eval_payload_note_space_redirect(original,redirect))) {
        /* Tracking already transferred cleanup to this payload frame. */
        return NULL;
    }
    return redirect;
}

static StateCell *payload_resolve_state_write(Arena *a, StateCell *cell) {
    Arena *owner;
    StateCell *redirect;
    if (!g_eval_payload_transactional || !cell)
        return petta_eval_private_state_image(cell);
    StateCell *original=cell;
    cell=eval_resolve_state_read(cell);
    if (payload_scratch_state_owned(cell)) return cell;
    owner = g_eval_payload_redirect_owner;
    if (!owner)
        owner = eval_current_persistent_arena();
    if (!owner)
        owner = eval_storage_arena(a);
    redirect = cetta_malloc(sizeof(StateCell));
    if (!redirect)
        return NULL;
    *redirect=(StateCell){.payload_owner_epoch=g_eval_payload_owner_epoch};
    if (!eval_payload_track_scratch_state(redirect)) {
        free(redirect);
        return NULL;
    }
    /* Reserve the private identity before traversing contents, so a cyclic
     * state points to this child image. On refusal, restore the old view. */
    CettaCount before=g_eval_payload_state_redirects.len;
    StateCell *old_original=payload_state_redirect_for(original);
    StateCell *old_visible=payload_state_redirect_for(cell);
    bool ready=eval_payload_note_state_redirect(cell,redirect) &&
        (original==cell || eval_payload_note_state_redirect(original,redirect));
    if (ready) {
        Atom *value=cell->value,*content_type=cell->content_type;
        if (g_eval_payload_frame)
            ready=eval_payload_frame_source_state(g_eval_payload_frame,owner,cell,&value,&content_type);
        if (ready) {
            redirect->value=value ? payload_rebind_resources(owner,value) : NULL;
            redirect->content_type=content_type ? payload_rebind_resources(owner,content_type) : NULL;
            ready=(!value || redirect->value) && (!content_type || redirect->content_type);
        }
    }
    if (!ready) {
        g_eval_payload_state_redirects.len=before;
        if (old_original) (void)eval_payload_note_state_redirect(original,old_original);
        if (cell!=original && old_visible) (void)eval_payload_note_state_redirect(cell,old_visible);
        return NULL;
    }
    return redirect;
}

static bool prime_need_effective_state(
    const Bindings *env, StateCell *cell,
    PrimeNeedBranchState *out_state, Atom **out_value) {
    if (!cell || !out_state || !out_value)
        return false;
    PrimeNeedBranchState state;
    prime_need_branch_state_init(&state);
    if (env)
        state = *bindings_branch_state_view(env);
    if (!prime_need_branch_state_merge(
            &state, &g_prime_need_branch_state_active))
        return false;
    Atom *value = NULL;
    if (!prime_need_branch_state_lookup(&state, cell, &value)) {
        eval_mark_interrupted(CETTA_EVAL_INCOMPLETE_CAPACITY);
        return false;
    }
    /* An unchanged borrowed cell can arrive through a stored Space row.
     * Its initial value belongs to the captured source, not this caller's
     * ambient world. A private cell instead has its own physical base. */
    if (!value && g_eval_payload_frame && !payload_scratch_state_owned(cell)) {
        Atom *content_type=NULL;
        if (!eval_payload_frame_source_state(g_eval_payload_frame,
                g_eval_payload_frame->owner,cell,&value,&content_type)) {
            eval_mark_interrupted(CETTA_EVAL_INCOMPLETE_CAPACITY);
            return false;
        }
    }
    if (!value) value = cell->value;
    if (!value)
        return false;
    *out_state = state;
    *out_value = value;
    return true;
}

#if CETTA_BUILD_WITH_PRIME_CAUSAL_RECEIPTS
static bool prime_need_record_state_receipt(
    Arena *a, Bindings *env,StateCell *cell,const PrimeNeedBranchState *base_state,
    const PrimeNeedBranchState *operation) {
    PrimeNeedReceipt base = *bindings_receipt_view(env);
    if (!prime_need_receipt_merge(&base, &g_prime_need_receipt_active))
        return false;
    const PrimeNeedReceipt *catalogue=prime_need_call_entrance_receipt();
    if (catalogue&&base_state) {
        Atom *selected=NULL;uint64_t write_event=0u;bool entrance=false;
        CettaMatchCompletion checked=prime_need_branch_state_lookup_version_checked(
            base_state,cell,&selected,&write_event);
        (void)selected;
        if (checked!=CETTA_MATCH_MATCHED) return false;
        if (write_event) {
            checked=prime_need_call_entrance_state_write(cell,write_event,&entrance);
            if (checked!=CETTA_MATCH_MATCHED) return false;
        }
        if (entrance) {
            bool found=false;
            checked=prime_need_receipt_join_state_anchor_qualified(
                prime_need_owner(a),&base,catalogue,write_event,&found);
            if (checked!=CETTA_MATCH_MATCHED) return false;
        }
    }
    PrimeNeedReceipt recorded;
    if (!prime_need_receipt_record_state(prime_need_owner(a),&base,operation,&recorded))
        return false;
    *bindings_receipt_mut(env) = recorded;
    return true;
}
#endif

static inline __attribute__((always_inline)) bool prime_need_read_state_kernel(
    Arena *a, Bindings *env, StateCell *cell, Atom *value, bool recorded) {
    if (!prime_need_call_state_admitted(cell,false)) return false;
    PrimeNeedBranchState base;
    if (!env || !prime_need_effective_state(
                    env, cell, &base, &value))
        return false;
    PrimeNeedBranchState observed;
    if (!prime_need_branch_state_read(
            prime_need_owner(a), &base, cell, value, &observed))
        return false;
    *bindings_branch_state_mut(env) = observed;
#if CETTA_BUILD_WITH_PRIME_CAUSAL_RECEIPTS
    if (recorded && !prime_need_record_state_receipt(
            a, env, cell, &base, &observed))
        return false;
#else
    (void)recorded;
#endif
    return true;
}

static inline __attribute__((always_inline)) bool prime_need_write_state_kernel(
    Arena *a, Bindings *env, StateCell *cell, Atom *after, bool recorded) {
    if (!prime_need_call_state_admitted(cell,false)) return false;
    PrimeNeedBranchState base;
    Atom *before = NULL;
    if (!env || !after ||
        !prime_need_effective_state(env, cell, &base, &before))
        return false;
    PrimeNeedBranchState written;
    if (!prime_need_branch_state_write(
            prime_need_owner(a), &base, cell, before, after, &written))
        return false;
    *bindings_branch_state_mut(env) = written;
#if CETTA_BUILD_WITH_PRIME_CAUSAL_RECEIPTS
    if (recorded && !prime_need_record_state_receipt(
            a, env, cell, &base, &written))
        return false;
#else
    (void)recorded;
#endif
    cetta_runtime_stats_inc(
        CETTA_RUNTIME_COUNTER_PRIME_NEED_BRANCH_STATE_WRITE);
    return true;
}

static bool prime_need_read_state_plain(
    Arena *arena, Bindings *environment, StateCell *cell, Atom *value) {
    return prime_need_read_state_kernel(arena, environment, cell, value, false);
}

static bool prime_need_write_state_plain(
    Arena *arena, Bindings *environment, StateCell *cell, Atom *value) {
    return prime_need_write_state_kernel(arena, environment, cell, value, false);
}

