static _Atomic bool *eval_set_cancel_token(_Atomic bool *cancel_requested) {
    _Atomic bool *prev = g_eval_cancel_requested;
    g_eval_cancel_requested = cancel_requested;
    g_eval_cancel_observed = false;
    return prev;
}

static _Atomic bool *eval_set_hyperpose_thread_unsafe_token(
    _Atomic bool *unsafe_requested) {
    _Atomic bool *prev = g_hyperpose_thread_unsafe_requested;
    g_hyperpose_thread_unsafe_requested = unsafe_requested;
    return prev;
}

static bool eval_mark_hyperpose_thread_unsafe(void) {
    if (!g_hyperpose_thread_unsafe_requested)
        return false;
    atomic_store_explicit(g_hyperpose_thread_unsafe_requested, true,
                          memory_order_release);
    if (g_eval_cancel_requested) {
        atomic_store_explicit(g_eval_cancel_requested, true,
                              memory_order_release);
    }
    return true;
}

static bool eval_cancel_check(void) {
    if (!g_eval_cancel_requested ||
        !atomic_load_explicit(g_eval_cancel_requested, memory_order_acquire)) {
        return false;
    }
    if (!g_eval_cancel_observed) {
        cetta_runtime_stats_inc(CETTA_RUNTIME_COUNTER_HYPERPOSE_CANCEL_OBSERVED);
        g_eval_cancel_observed = true;
    }
    eval_mark_incomplete(CETTA_EVAL_INCOMPLETE_CANCELLED);
    return true;
}

/* Whether an inline observation quantum (prime_inline_quantum_visit) is in
 * force and spent. */
static __attribute__((unused)) bool eval_inline_quantum_spent(void) {
    CettaEvalEpisode *tracker = g_eval_completion_tracker;
    if (!tracker || !tracker->budget_limited)
        return false;
    for (CettaEvalEpisode *t = tracker; t; t = t->parent)
        if (t->observation)
            return tracker->budget_remaining <= t->observation->renew_cushion;
    return false;
}

/* What one interrupt poll of the prepared machine costs an inline
 * observation quantum: the machine's steps between two polls are about one
 * evaluator step of work. */
#define EVAL_PREPARED_PURE_POLL_STEPS UINT64_C(1)

static bool eval_prepared_pure_interrupt_poll(void *context) {
    (void)context;
    if (eval_unwinding() || eval_cancel_check())
        return true;
    /* Inside an inline observation quantum the prepared machine's steps
     * count against the quantum, as the evaluator's do; when it runs out the
     * machine stops at its next boundary and the attempt is dropped. */
    CettaEvalEpisode *tracker = g_eval_completion_tracker;
    bool quantum = false;
    for (CettaEvalEpisode *t = tracker; t && !quantum; t = t->parent)
        quantum = t->observation != NULL;
    if (!quantum || !tracker->budget_limited)
        return false;
    uint64_t spent = tracker->budget_remaining < EVAL_PREPARED_PURE_POLL_STEPS
        ? tracker->budget_remaining : EVAL_PREPARED_PURE_POLL_STEPS;
    tracker->budget_remaining -= spent;
    if (tracker->steps_spent <= UINT64_MAX - spent)
        tracker->steps_spent += spent;
    if (tracker->budget_remaining != 0u)
        return false;
    eval_mark_incomplete(CETTA_EVAL_INCOMPLETE_FUEL);
    return true;
}

static bool prime_native_owner_active(void);
static bool prime_inline_quantum_alternative_waits(
    const CettaEvalEpisode *tracker,
    const CettaEvalEpisode *quantum);

/* The prepared register machine for one unbounded-fuel call.  Under the
 * native control's fair scheduler it takes one register step per scheduled
 * call edge.  Outside an inline observation quantum, or when the inline
 * observation's stack holds no waiting alternative (the register sublanguage
 * is deterministic, so it introduces none of its own), it runs a batch of
 * tail steps and then its recursion.  While an alternative waits on the
 * stack, it is bounded by what remains of the quantum and charged for the
 * steps it took, as the evaluator is (the evaluator charges the call edge
 * itself); its recursion, which cannot stop part way, is not entered there,
 * and the call is evaluated as written instead.  A waiting alternative thus
 * never waits on work the quantum does not see. */
static SpacePreparedRegisterStep eval_prepared_register_run(
    const SpacePreparedEquation *plan, Atom *call, Arena *arena,
    Atom **result) {
    enum { EVAL_PREPARED_REGISTER_BATCH = 4096u };
    if (prime_native_owner_active())
        return space_prepared_equation_execute_register_step(
            plan, call, arena, result);
    CettaEvalEpisode *tracker = g_eval_completion_tracker;
    CettaEvalEpisode *quantum = NULL;
    for (CettaEvalEpisode *t = tracker; t && !quantum; t = t->parent)
        if (t->observation)
            quantum = t;
    if (!quantum || !tracker->budget_limited ||
        !prime_inline_quantum_alternative_waits(tracker, quantum)) {
        SpacePreparedRegisterStep step =
            space_prepared_equation_run_register_loop(
                plan, call, arena, EVAL_PREPARED_REGISTER_BATCH, result);
        if (step == SPACE_PREPARED_REGISTER_NOT_APPLICABLE)
            step = space_prepared_equation_run_register_recursion(
                plan, call, arena, SIZE_MAX, result);
        return step;
    }
    uint64_t available = tracker->budget_remaining > quantum->observation->renew_cushion
        ? tracker->budget_remaining - quantum->observation->renew_cushion : 0u;
    size_t limit = available < EVAL_PREPARED_REGISTER_BATCH
        ? (size_t)available : EVAL_PREPARED_REGISTER_BATCH;
    if (limit == 0u)
        return SPACE_PREPARED_REGISTER_NOT_APPLICABLE;
    size_t completed = 0u;
    SpacePreparedRegisterStep step =
        space_prepared_equation_run_register_loop_counted(
            plan, call, arena, limit, result, &completed);
    uint64_t charged = completed > 1u ? (uint64_t)completed - 1u : 0u;
    if (charged > tracker->budget_remaining)
        charged = tracker->budget_remaining;
    tracker->budget_remaining -= charged;
    if (tracker->steps_spent <= UINT64_MAX - charged)
        tracker->steps_spent += charged;
    return step;
}

bool eval_native_interrupted(void) {
    if (eval_unwinding()) return true;
    if (!eval_cancel_check()) return false;
    eval_mark_interrupted(CETTA_EVAL_INCOMPLETE_CANCELLED);
    return true;
}

