#define CETTA_DEFAULT_EVAL_C_STACK_BUDGET_BYTES (1024u * 1024u)
#define CETTA_MIN_EVAL_C_STACK_BUDGET_BYTES (1024u * 1024u)
#define CETTA_MAX_EVAL_C_STACK_BUDGET_BYTES (16u * 1024u * 1024u)
#define CETTA_EVAL_C_STACK_SERVICE_RESERVE_BYTES (256u * 1024u)

static __thread uint32_t g_eval_c_stack_guard_depth = 0;
static __thread uintptr_t g_eval_c_stack_anchor = 0;
static __thread size_t g_eval_c_stack_budget_bytes = 0;
static __thread uint32_t g_eval_parallel_resource_share_count = 1u;

typedef struct {
    uintptr_t low;
    uintptr_t high;
    bool attempted;
    bool known;
    bool grows_down;
} EvalThreadStackBounds;

static __thread EvalThreadStackBounds g_eval_thread_stack_bounds;

typedef struct {
    bool active;
} EvalCStackGuard;

static size_t eval_c_stack_budget_bytes(void) {
    if (g_eval_c_stack_budget_bytes != 0)
        return g_eval_c_stack_budget_bytes;

    size_t budget = CETTA_DEFAULT_EVAL_C_STACK_BUDGET_BYTES;
#ifdef RLIMIT_STACK
    struct rlimit rl;
    if (getrlimit(RLIMIT_STACK, &rl) == 0 &&
        rl.rlim_cur != RLIM_INFINITY && rl.rlim_cur > 0) {
        size_t stack_soft_limit = (size_t)rl.rlim_cur;
        size_t reserve = stack_soft_limit / 4;
        if (reserve < (1024u * 1024u))
            reserve = (1024u * 1024u);
        if (stack_soft_limit > reserve)
            budget = stack_soft_limit - reserve;
    }
#endif
    if (budget < CETTA_MIN_EVAL_C_STACK_BUDGET_BYTES)
        budget = CETTA_MIN_EVAL_C_STACK_BUDGET_BYTES;
    if (budget > CETTA_MAX_EVAL_C_STACK_BUDGET_BYTES)
        budget = CETTA_MAX_EVAL_C_STACK_BUDGET_BYTES;
    g_eval_c_stack_budget_bytes = budget;
    cetta_runtime_stats_set(CETTA_RUNTIME_COUNTER_EVAL_C_STACK_GUARD_BUDGET_BYTES,
                            (uint64_t)budget);
    return budget;
}

uint64_t eval_current_c_stack_budget_bytes(void) {
    return (uint64_t)eval_c_stack_budget_bytes();
}

__attribute__((noinline))
static bool eval_c_stack_grows_down_from(uintptr_t caller_frame) {
    return (uintptr_t)__builtin_frame_address(0) < caller_frame;
}

static bool eval_thread_stack_remaining_bytes(
    uintptr_t here, uint64_t *remaining_out) {
    EvalThreadStackBounds *bounds = &g_eval_thread_stack_bounds;
    if (!bounds->attempted) {
        bounds->attempted = true;
#if defined(__linux__)
        bounds->grows_down = eval_c_stack_grows_down_from(here);
        /* Some libcs report only the currently mapped initial stack. Linux
         * can grow that stack; its mapping, limit and preceding VMA define
         * the available extent. Keep pthread attributes for fixed stacks. */
        if (bounds->grows_down && cetta_linux_initial_stack_bounds(here,
                CETTA_MAX_EVAL_C_STACK_BUDGET_BYTES, &bounds->low,
                &bounds->high))
            bounds->known = true;
        pthread_attr_t attributes;
        if (!bounds->known &&
            pthread_getattr_np(pthread_self(), &attributes) == 0) {
            void *address = NULL;
            size_t size = 0u;
            if (pthread_attr_getstack(&attributes, &address, &size) == 0 &&
                address && size > 0u &&
                (uintptr_t)address <= UINTPTR_MAX - size) {
                bounds->low = (uintptr_t)address;
                bounds->high = bounds->low + size;
                bounds->grows_down = eval_c_stack_grows_down_from(here);
                bounds->known = here >= bounds->low && here <= bounds->high;
            }
            (void)pthread_attr_destroy(&attributes);
        }
#endif
    }
    if (!bounds->known || here < bounds->low || here > bounds->high)
        return false;
    *remaining_out = bounds->grows_down
        ? (uint64_t)(here - bounds->low)
        : (uint64_t)(bounds->high - here);
    return true;
}

void eval_c_stack_boundary_capture(CettaEvalCStackBoundary *boundary) {
    if (!boundary)
        return;
    uintptr_t here = (uintptr_t)__builtin_frame_address(0);
    uint64_t budget = (uint64_t)eval_c_stack_budget_bytes();
    uint64_t remaining = 0u;
    if (eval_thread_stack_remaining_bytes(here, &remaining)) {
        budget = remaining > CETTA_EVAL_C_STACK_SERVICE_RESERVE_BYTES
            ? remaining - CETTA_EVAL_C_STACK_SERVICE_RESERVE_BYTES : 0u;
        uint64_t configured = (uint64_t)eval_c_stack_budget_bytes();
        if (budget > configured)
            budget = configured;
    } else if (budget > CETTA_DEFAULT_EVAL_C_STACK_BUDGET_BYTES) {
        /* Unknown stack mappings get the already-supported conservative
         * default rather than an RLIMIT-derived distance from an unknown
         * starting depth. */
        budget = CETTA_DEFAULT_EVAL_C_STACK_BUDGET_BYTES;
    }
    boundary->anchor = here;
    boundary->budget_bytes = budget;
}

static __thread uint64_t g_eval_c_stack_anchor_budget = 0u;

static bool eval_c_stack_guard_enter(int fuel, EvalCStackGuard *guard) {
    /* Address the physical frame: sanitizers may place local variables on a
     * separate fake stack, whose distance does not measure native recursion. */
    uintptr_t here = (uintptr_t)__builtin_frame_address(0);
    if (guard) guard->active = false;
    /* Fuel limits logical evaluation, but native recursion can still consume
       stack before fuel bottoms out, so guard both finite and infinite runs. */
    if (g_eval_c_stack_guard_depth++ == 0) {
        g_eval_c_stack_anchor = here;
        /* The budget is measured from the anchor, and the anchor need not
           sit near the top of the stack: what the frames above it already
           took is not available below it.  Where the stack's bounds are
           known, keep the service reserve below the anchor's remainder. */
        uint64_t budget = (uint64_t)eval_c_stack_budget_bytes();
        uint64_t remaining = 0u;
        if (eval_thread_stack_remaining_bytes(here, &remaining)) {
            uint64_t usable =
                remaining > CETTA_EVAL_C_STACK_SERVICE_RESERVE_BYTES
                    ? remaining - CETTA_EVAL_C_STACK_SERVICE_RESERVE_BYTES
                    : 0u;
            if (usable < budget)
                budget = usable;
        }
        g_eval_c_stack_anchor_budget = budget;
    }
    cetta_runtime_stats_update_max(
        CETTA_RUNTIME_COUNTER_EVAL_C_STACK_GUARD_DEPTH_PEAK,
        (uint64_t)g_eval_c_stack_guard_depth);
    uintptr_t delta = here > g_eval_c_stack_anchor
        ? (here - g_eval_c_stack_anchor)
        : (g_eval_c_stack_anchor - here);
    cetta_runtime_stats_update_max(
        CETTA_RUNTIME_COUNTER_EVAL_C_STACK_GUARD_DELTA_BYTES_PEAK,
        (uint64_t)delta);
    if (delta > g_eval_c_stack_anchor_budget) {
        if (g_eval_c_stack_guard_depth > 0)
            g_eval_c_stack_guard_depth--;
        if (g_eval_c_stack_guard_depth == 0)
            g_eval_c_stack_anchor = 0;
        eval_mark_incomplete(CETTA_EVAL_INCOMPLETE_STACK);
        return false;
    }
    if (guard) guard->active = true;
    return true;
}

static void eval_c_stack_guard_leave(EvalCStackGuard *guard) {
    if (!guard || !guard->active)
        return;
    guard->active = false;
    if (g_eval_c_stack_guard_depth > 0)
        g_eval_c_stack_guard_depth--;
    if (g_eval_c_stack_guard_depth == 0)
        g_eval_c_stack_anchor = 0;
}

