bool petta_libpl_cpu_count(uint32_t *count) __attribute__((weak));

/* SWI-PeTTa sizes hyperpose's pool by the embedded Prolog's cpu_count flag;
 * an explicit num-threads option stays authoritative. */
static bool eval_petta_cpu_count_flag(uint32_t *count) {
    return eval_current_language_id() == CETTA_LANGUAGE_PETTA &&
        !active_eval_option("num-threads") && petta_libpl_cpu_count &&
        petta_libpl_cpu_count(count);
}

uint32_t eval_current_num_threads(void) {
    int64_t default_threads = 1;
    uint32_t cpu_count = 0u;
    if (eval_petta_cpu_count_flag(&cpu_count)) {
        default_threads = cpu_count;
    } else if (eval_current_language_id() == CETTA_LANGUAGE_PETTA) {
        long online = sysconf(_SC_NPROCESSORS_ONLN);
        /*
         * PeTTa's hyperpose is a concurrent conjunction.  Preserve progress
         * fairness even on a single-core host, while using the online CPU
         * count as the default resource budget.  An explicit num-threads
         * option remains authoritative.
         */
        default_threads = online > 1 ? online : 2;
        if (default_threads > 1024)
            default_threads = 1024;
    }
    int64_t configured =
        eval_option_int_or_default("num-threads", default_threads);
    if (configured < 1)
        return 1u;
    if (configured > 1024)
        return 1024u;
    return (uint32_t)configured;
}

static int64_t eval_option_int_or_default(const char *key, int64_t default_value) {
    const CettaEvalOptionEntry *option = active_eval_option(key);
    if (!option)
        return default_value;
    if (option->kind == CETTA_EVAL_OPTION_VALUE_INT)
        return option->int_value;
    if (strcmp(option->repr, "off") == 0 ||
        strcmp(option->repr, "false") == 0 ||
        strcmp(option->repr, "disabled") == 0) {
        return 0;
    }
    if (strcmp(option->repr, "on") == 0 ||
        strcmp(option->repr, "true") == 0 ||
        strcmp(option->repr, "fair") == 0 ||
        strcmp(option->repr, "threaded") == 0 ||
        strcmp(option->repr, "parallel") == 0) {
        return 2;
    }
    return default_value;
}

static const char *validate_thread_count_pragma_value(Atom *value) {
    if (!value || value->kind != ATOM_GROUNDED || value->ground.gkind != GV_INT)
        return "UnsignedIntegerIsExpected";
    if (value->ground.ival < 0)
        return "UnsignedIntegerIsExpected";
    if (value->ground.ival > 1024)
        return "ThreadCountOutOfRange";
    return NULL;
}

/* PeTTa's space operations are generic, and the reference applies them to
 * its MORK space `&mork` (lib_mm2): there they reach a MORK space as its
 * explicit operations do. */
static bool generic_mork_space_sugar_allowed(void) {
    return g_active_language_id == CETTA_LANGUAGE_PETTA ||
           mork_space_sugar_option_allows(active_eval_option("mork-space-sugar"));
}

static bool atom_resolves_to_mork_handle(Space *s, Arena *a, Atom *space_expr,
                                         int fuel) {
    uint64_t id = 0;
    Atom *direct = resolve_registry_refs(a, space_expr);
    if (cetta_native_handle_arg(direct, "mork-space", &id)) {
        return true;
    }
    /* A grounded value, such as a space, evaluates to itself: no handle. */
    if (direct && direct->kind == ATOM_GROUNDED)
        return false;

    ResultSet rs;
    result_set_init(&rs);
    metta_eval(s, a, NULL, space_expr, fuel, &rs);
    for (CettaCount i = 0; i < rs.len; i++) {
        if (cetta_native_handle_arg(rs.items[i], "mork-space", &id)) {
            result_set_free(&rs);
            return true;
        }
    }
    result_set_free(&rs);
    return false;
}

static bool resolve_explicit_mork_bridge_arg(Space *s, Arena *a,
                                             Atom *space_expr, int fuel,
                                             CettaMorkSpaceHandle **out_bridge) {
    if (out_bridge)
        *out_bridge = NULL;
    if (!g_library_context)
        return false;

    Atom *direct = resolve_registry_refs(a, space_expr);
    if (cetta_library_lookup_explicit_mork_bridge(g_library_context, direct,
                                                  out_bridge) &&
        out_bridge && *out_bridge) {
        return true;
    }

    ResultSet rs;
    result_set_init(&rs);
    metta_eval(s, a, NULL, space_expr, fuel, &rs);
    for (CettaCount i = 0; i < rs.len; i++) {
        if (cetta_library_lookup_explicit_mork_bridge(g_library_context,
                                                      rs.items[i],
                                                      out_bridge) &&
            out_bridge && *out_bridge) {
            result_set_free(&rs);
            return true;
        }
    }
    result_set_free(&rs);
    if (out_bridge)
        *out_bridge = NULL;
    return false;
}

static bool generic_mork_handle_sugar_allowed(Space *s, Arena *a, Atom *space_expr,
                                              int fuel) {
    return generic_mork_space_sugar_allowed() &&
           atom_resolves_to_mork_handle(s, a, space_expr, fuel);
}

