static Atom *eval_llist_call_error(Arena *a, Atom *head, Atom **args,
                                   uint32_t nargs, Atom *reason) {
    return atom_error(a, make_call_expr(a, head, args, nargs), reason);
}

static Atom *eval_llist_bad_arg_type(Arena *a, Atom *head, Atom **args,
                                     uint32_t nargs, int bad_idx,
                                     Atom *expected_type, Atom *actual_atom) {
    Atom *actual_type =
        (actual_atom && actual_atom->kind == ATOM_GROUNDED)
            ? get_grounded_type(a, actual_atom)
            : get_meta_type(a, actual_atom);
    Atom *reason = atom_expr(a, (Atom *[]){
        atom_symbol(a, "BadArgType"),
        atom_int(a, bad_idx),
        expected_type,
        actual_type
    }, 4);
    return eval_llist_call_error(a, head, args, nargs, reason);
}

static CettaCallOutcome eval_minimal_foldl_llist(Arena *a, Atom *head, Atom **args,
                                                uint32_t nargs) {
    if (nargs != 6) {
        return cetta_call_value(eval_llist_call_error(
            a, head, args, nargs, atom_symbol(a, "IncorrectNumberOfArguments")));
    }
    if (args[2]->kind != ATOM_VAR) {
        return cetta_call_value(eval_llist_bad_arg_type(
            a, head, args, nargs, 3, atom_variable_type(a), args[2]));
    }
    if (args[3]->kind != ATOM_VAR) {
        return cetta_call_value(eval_llist_bad_arg_type(
            a, head, args, nargs, 4, atom_variable_type(a), args[3]));
    }
    if (!(args[5]->kind == ATOM_GROUNDED &&
          args[5]->ground.gkind == GV_SPACE)) {
        return cetta_call_value(eval_llist_bad_arg_type(
            a, head, args, nargs, 6, atom_symbol(a, "SpaceType"), args[5]));
    }

    Atom *cursor = args[0];
    Atom *acc = args[1];
    Atom *acc_var = args[2];
    Atom *item_var = args[3];
    Atom *op_expr = args[4];
    Space *target = (Space *)args[5]->ground.ptr;
    Arena scratch;
    arena_init(&scratch);
    arena_set_runtime_kind(&scratch, CETTA_ARENA_RUNTIME_KIND_SCRATCH);
    arena_set_hashcons(&scratch, NULL);
    ArenaMark scratch_mark = arena_mark(&scratch);

    for (;;) {
        if (atom_is_symbol_id(cursor, g_builtin_syms.llist_nil)) {
            arena_free(&scratch);
            return cetta_call_completed_value(acc);
        }
        if (cursor->kind != ATOM_EXPR || cursor->expr.len != 3 ||
            !atom_is_symbol_id(cursor->expr.elems[0],
                               g_builtin_syms.llist_cons)) {
            Atom *error = eval_llist_call_error(
                a, head, args, nargs,
                atom_symbol(a,
                    "_minimal-foldl-llist expects a proper LCons/LNil list"));
            arena_free(&scratch);
            return cetta_call_value(error);
        }

        Atom *step_op = cetta_fold_bind_step_atom(
            &scratch, op_expr,
            acc_var, acc,
            item_var, cursor->expr.elems[1]);
        ResultSet results;
        Atom *next = NULL;
        Atom *step_error = NULL;
        bool multiple = false;
        result_set_init(&results);
        {
            __attribute__((cleanup(petta_host_branch_leave)))
            PettaHostBranchGuard branch = petta_host_branch_enter();
            metta_eval(target, &scratch, NULL, step_op,
                       eval_get_default_fuel(), &results);
        }

        for (CettaCount i = 0; i < results.len; i++) {
            Atom *candidate = results.items[i];
            if (atom_is_legacy_empty_sentinel(candidate))
                continue;
            if (atom_is_error(candidate)) {
                step_error = candidate;
                break;
            }
            if (next) {
                multiple = true;
                break;
            }
            next = candidate;
        }

        Atom *persisted = NULL;
        if (step_error)
            persisted = atom_deep_copy(a, step_error);
        else if (!multiple && next)
            persisted = atom_deep_copy(a, next);
        result_set_free(&results);
        arena_reset(&scratch, scratch_mark);

        if (step_error) {
            arena_free(&scratch);
            return cetta_call_value(persisted);
        }
        if (multiple) {
            Atom *error = eval_llist_call_error(
                a, head, args, nargs,
                atom_symbol(a,
                    "_minimal-foldl-llist step produced multiple results"));
            arena_free(&scratch);
            return cetta_call_value(error);
        }
        if (!persisted) {
            Atom *error = eval_llist_call_error(
                a, head, args, nargs,
                atom_symbol(a,
                    "_minimal-foldl-llist step produced no result"));
            arena_free(&scratch);
            return cetta_call_value(error);
        }

        acc = persisted;
        cursor = cursor->expr.elems[2];
    }
}

/* HE's authored fold protocol exposes this delimiter to case and reflection.
 * Only producer completion authorizes constructing it; accumulator syntax has
 * no role in deciding whether the fold completed. */
static Atom *minimal_foldl_llist_expression(Arena *arena, CettaCallOutcome result) {
    if (result.kind == CETTA_CALL_VALUE &&
        result.result_form == CETTA_CALL_RESULT_COMPLETED_VALUE)
        return atom_expr2(arena, atom_symbol_id(arena, g_builtin_syms.return_text),
                          result.term);
    return eval_call_outcome_atom(arena, result);
}

static Atom *dispatch_named_native(Space *s, Arena *a, SymbolId head_id,
                                   Atom **args, uint32_t nargs) {
    if (eval_speculative_active() && !cetta_speculative_op_allowed(head_id))
        return cetta_effect_denied(a);
    __attribute__((cleanup(eval_gc_external_owner_guard_leave)))
    EvalGcExternalOwnerGuard borrowed_values = {0};
    eval_gc_external_owner_guard_enter(&borrowed_values);
    Atom *head = atom_symbol_id(a, head_id);
    if (head_id == g_builtin_syms.minimal_foldl_llist)
        return minimal_foldl_llist_expression(a,
            eval_minimal_foldl_llist(a, head, args, nargs));
    CettaCallOutcome outcome;
    if (grounded_call(a, head, args, nargs, &outcome) ||
        (g_library_context &&
         cetta_library_call_native(g_library_context, s, a, head, args,
                                   nargs, &outcome)))
        return eval_call_outcome_atom(a, outcome);
    return NULL;
}

static Atom *rewrite_error_call(Arena *a, Atom *syntax_atom, Atom *result) {
    if (!result || !atom_is_error(result) || result->kind != ATOM_EXPR ||
        result->expr.len < 3) {
        return result;
    }
    return atom_error(a, syntax_atom, result->expr.elems[2]);
}

static bool emit_generic_mork_handle_native_syntax(
    Space *s, Arena *a, Atom *syntax_atom, Atom **args, uint32_t nargs,
    int fuel, SymbolId explicit_head_id, OutcomeSet *os) {
    Bindings empty;
    bindings_init(&empty);
    if (!generic_mork_handle_sugar_allowed(s, a, args[0], fuel)) {
        return false;
    }
    Atom **resolved_args = arena_alloc(a, sizeof(Atom *) * nargs);
    for (uint32_t i = 0; i < nargs; i++) {
        resolved_args[i] = resolve_registry_refs(a, args[i]);
    }
    Atom *result = dispatch_named_native(s, a, explicit_head_id, resolved_args, nargs);
    if (!result) {
        return false;
    }
    outcome_set_add(os, rewrite_error_call(a, syntax_atom, result), &empty);
    return true;
}

static bool emit_generic_mork_handle_atoms_syntax(
    Space *s, Arena *a, Atom *syntax_atom, Atom *space_arg, int fuel,
    OutcomeSet *os) {
    Atom *args[] = { space_arg };
    if (!generic_mork_handle_sugar_allowed(s, a, space_arg, fuel)) {
        return false;
    }
    if (emit_direct_mork_atoms_rows(s, a, syntax_atom, args, fuel, os)) {
        return true;
    }
    return emit_unquoted_mork_rows(s, a, g_builtin_syms.lib_mork_space_atoms,
                                   1, args, false, fuel, os);
}

static bool emit_generic_mork_handle_match_syntax(
    Space *s, Arena *a, Atom *syntax_atom, Atom **args, int fuel,
    OutcomeSet *os) {
    if (!generic_mork_handle_sugar_allowed(s, a, args[0], fuel)) {
        return false;
    }
    if (emit_direct_mork_match_rows(s, a, syntax_atom, args, fuel, os)) {
        return true;
    }
    return emit_unquoted_mork_rows(s, a, g_builtin_syms.lib_mork_space_match,
                                   3, args, true, fuel, os);
}

static Atom *guard_mork_space_syntax(Arena *a, Atom *call, Space *space,
                                      const char *syntax,
                                      const char *explicit_syntax) {
    if (!space_requires_explicit_mork_namespace(space)) {
        return NULL;
    }
    return mork_space_syntax_error(a, call, syntax, explicit_syntax);
}

static Atom *guard_mork_handle_syntax(Space *s, Arena *a, Atom *call,
                                       Atom *space_expr, int fuel,
                                       const char *syntax,
                                       const char *explicit_syntax) {
    if (!g_registry) return NULL;

    if (atom_resolves_to_mork_handle(s, a, space_expr, fuel)) {
        return mork_handle_syntax_error(a, call, syntax, explicit_syntax);
    }
    return NULL;
}

static pthread_once_t g_table_mode_env_once = PTHREAD_ONCE_INIT;
static const char *g_table_mode_env_repr;

static void table_mode_env_init(void) {
    g_table_mode_env_repr = getenv("CETTA_TABLE_MODE");
}

static CettaTableMode active_search_table_mode(void) {
    const CettaEvalOptionEntry *table_mode = active_eval_option("search-table-mode");
    const char *repr = NULL;
    if (table_mode && table_mode->kind == CETTA_EVAL_OPTION_VALUE_SYMBOL)
        repr = table_mode->repr;
    if (!repr) {
        /* Env fallback (read once) so benchmarks can opt in without editing
         * the source under test.  A `pragma!` still takes precedence. */
        if (pthread_once(&g_table_mode_env_once, table_mode_env_init) != 0)
            abort();
        repr = g_table_mode_env_repr;
    }
    if (repr) {
        if (strcmp(repr, "variant") == 0)
            return CETTA_TABLE_MODE_VARIANT;
    }
    return CETTA_TABLE_MODE_NONE;
}

static AnswerBank *eval_active_episode_answer_bank(void) {
    EvalExecutionContext *context = eval_execution_context();
    if (!context->answers_ready) {
        answer_bank_init(&context->answers);
        context->answers_ready = true;
    }
    return &context->answers;
}

static void eval_release_episode_answer_bank(void) {
    EvalExecutionContext *context = g_eval_execution;
    if (!context)
        return;
    if (!context->answers_ready)
        return;
    answer_bank_free(&context->answers);
    context->answers_ready = false;
}

static TableStore *eval_active_episode_table(void) {
    CettaTableMode mode = active_search_table_mode();
    if (mode == CETTA_TABLE_MODE_NONE)
        return NULL;
    EvalExecutionContext *context = eval_execution_context();
    if (!context->table_ready) {
        table_store_init(&context->table, mode, eval_active_episode_answer_bank());
        context->table_ready = true;
    } else if (context->table.mode != mode) {
        eval_execution_invalidate_borrows(context);
        table_store_free(&context->table);
        eval_release_episode_answer_bank();
        table_store_init(&context->table, mode, eval_active_episode_answer_bank());
    }
    return &context->table;
}

static void eval_release_episode_table(void) {
    EvalExecutionContext *context = g_eval_execution;
    if (!context)
        return;
    if (!context->table_ready)
        return;
    table_store_free(&context->table);
    context->table_ready = false;
    eval_release_episode_answer_bank();
}

static bool outcome_variant_sharing_enabled(void) {
    const CettaEvalOptionEntry *option = active_eval_option("outcome-variant-sharing");
    if (option) {
        if (option->kind == CETTA_EVAL_OPTION_VALUE_INT)
            return option->int_value != 0;
        return strcmp(option->repr, "off") != 0 &&
               strcmp(option->repr, "false") != 0 &&
               strcmp(option->repr, "0") != 0;
    }
    /* High-confidence auto lane: variant-table mode already commits to
       canonicalized variant reuse at explicit memo boundaries. */
    return active_search_table_mode() == CETTA_TABLE_MODE_VARIANT;
}

static VariantBank *eval_active_outcome_variant_bank(void) {
    static const CettaVariantShapeOptions kOutcomeVariantOptions = {
        .slot_policy = CETTA_VARIANT_SLOT_FIXED_SPELLING,
        .slot_name = "$_slot",
        .share_immutable = true,
    };
    if (g_owned_outcome_variant_bank)
        return outcome_variant_sharing_enabled() ? g_owned_outcome_variant_bank : NULL;
    /* Disabling admission does not revoke existing outcome borrows. */
    if (!outcome_variant_sharing_enabled())
        return NULL;
    EvalExecutionContext *context = eval_execution_context();
    if (!context->variants_ready) {
        variant_bank_init(&context->variants, kOutcomeVariantOptions);
        context->variants_ready = true;
    }
    return &context->variants;
}

static void eval_release_outcome_variant_bank(void) {
    if (g_owned_outcome_variant_bank)
        return;
    EvalExecutionContext *context = g_eval_execution;
    if (!context)
        return;
    if (!context->variants_ready)
        return;
    variant_bank_free(&context->variants);
    context->variants_ready = false;
}

/* ── Result Set ─────────────────────────────────────────────────────────── */

static CettaCount eval_array_capacity_limit(size_t elem_size) {
    return elem_size == 0 ? (CettaCount)SIZE_MAX
                          : (CettaCount)(SIZE_MAX / elem_size);
}

static bool eval_next_capacity(CettaCount current, CettaCount needed,
                               size_t elem_size, CettaCount *out_next) {
    CettaCount limit;
    CettaCount next;
    if (!out_next)
        return false;
    limit = eval_array_capacity_limit(elem_size);
    if (needed > limit)
        return false;
    next = current ? current * 2u : 8u;
    if (next <= current || next < needed)
        next = needed;
    if (next > limit)
        next = limit;
    if (next < needed)
        return false;
    *out_next = next;
    return true;
}

static bool result_set_ensure_one(ResultSet *rs) {
    CettaCount next_cap;
    bool using_inline;
    if (!rs)
        return false;
    if (rs->len < rs->cap)
        return true;
    if (!eval_next_capacity(rs->cap, rs->len + 1u, sizeof(Atom *), &next_cap))
        return false;
    using_inline = rs->items == rs->inline_items;
    if (using_inline) {
        Atom **next = cetta_malloc(sizeof(Atom *) * (size_t)next_cap);
        if (rs->len > 0)
            memcpy(next, rs->items, sizeof(Atom *) * (size_t)rs->len);
        rs->items = next;
    } else {
        rs->items = cetta_realloc(rs->items, sizeof(Atom *) * (size_t)next_cap);
    }
    rs->cap = next_cap;
    return true;
}

void result_set_init(ResultSet *rs) {
    rs->items = rs->inline_items;
    rs->len = 0;
    rs->cap = 1;
}

void result_set_add(ResultSet *rs, Atom *atom) {
    if (!result_set_ensure_one(rs))
        return;
    rs->items[rs->len++] = atom;
}

static void result_set_filter_empty(ResultSet *rs) {
    CettaCount out = 0;
    if (!rs)
        return;
    if (eval_current_language_id() == CETTA_LANGUAGE_PRIME)
        return;
    for (CettaCount i = 0; i < rs->len; i++) {
        if (atom_is_legacy_empty_sentinel(rs->items[i]))
            continue;
        rs->items[out++] = rs->items[i];
    }
    rs->len = out;
}

void result_set_free(ResultSet *rs) {
    if (rs->items != rs->inline_items)
        free(rs->items);
    rs->items = rs->inline_items;
    rs->len = 0;
    rs->cap = 1;
}

/* ── Helpers ────────────────────────────────────────────────────────────── */

static bool expr_head_is_id(Atom *a, SymbolId id) {
    return a->kind == ATOM_EXPR && a->expr.len >= 1 &&
           atom_is_symbol_id(a->expr.elems[0], id);
}

static CettaExprLen expr_nargs(Atom *a) {
    return (a->kind == ATOM_EXPR && a->expr.len > 0) ? a->expr.len - 1 : 0;
}

static bool expr_nargs_u32(Atom *a, uint32_t *out) {
    CettaExprLen nargs = expr_nargs(a);
    if (!out)
        return false;
    if (!cetta_expr_len_fits_u32(nargs))
        return false;
    *out = (uint32_t)nargs;
    return true;
}

static Atom *expr_arg(Atom *a, CettaExprIndex i) {
    return a->expr.elems[i + 1];
}

static Atom *expr_arity_too_large_error(Arena *a, Atom *atom) {
    return atom_error(a, atom, atom_symbol(a, "ArityTooLarge"));
}

static bool is_true_atom(Atom *a) {
    if(eval_current_language_id()==CETTA_LANGUAGE_PRIME)
        a=atom_prime_held_payload(a);
    if(!a)return false;
    bool petta_value = false;
    if (eval_current_language_id() == CETTA_LANGUAGE_PETTA &&
        petta_semantics_truth_value(a, &petta_value)) {
        return petta_value;
    }
    return atom_is_symbol_id(a, g_builtin_syms.true_text) ||
           (a->kind == ATOM_GROUNDED && a->ground.gkind == GV_BOOL && a->ground.bval);
}

static bool is_false_atom(Atom *a) {
    if(eval_current_language_id()==CETTA_LANGUAGE_PRIME)
        a=atom_prime_held_payload(a);
    if(!a)return false;
    bool petta_value = true;
    if (eval_current_language_id() == CETTA_LANGUAGE_PETTA &&
        petta_semantics_truth_value(a, &petta_value)) {
        return !petta_value;
    }
    return atom_is_symbol_id(a, g_builtin_syms.false_text) ||
           (a->kind == ATOM_GROUNDED && a->ground.gkind == GV_BOOL && !a->ground.bval);
}

static bool atom_is_registry_token(Atom *atom) {
    if (!atom) return false;
    if (atom->kind == ATOM_SYMBOL)
        return atom_symbol_bytes(atom)[0] == '&';
    Atom *name_key = NULL;
    return registry_ref_name_key(atom, &name_key) && name_key;
}

/* HE substitutes bound words once, when their containing form is read.
 * A surviving ordinary symbol is data even if that spelling is bound later.
 * Explicit structural references and the existing context roles retain
 * their runtime interpretation. Other languages keep their name semantics. */
static bool registry_runtime_reference_allowed(Atom *atom) {
    if (!atom) return false;
    if (eval_current_language_id() != CETTA_LANGUAGE_HE ||
        atom->kind != ATOM_SYMBOL)
        return true;
    return atom_is_symbol_id(atom, g_builtin_syms.self) ||
           atom_is_symbol_id(atom, g_builtin_syms.amp_here) ||
           atom_is_symbol_id(atom, g_builtin_syms.amp_home);
}

static Atom *registry_lookup_atom(Atom *atom) {
    if (!g_registry || !atom_is_registry_token(atom) ||
        !registry_runtime_reference_allowed(atom))
        return NULL;
    return registry_lookup_ref(g_registry, atom);
}

static Space *resolve_runtime_space(Registry *registry, Atom *reference) {
    return registry_runtime_reference_allowed(reference)
        ? resolve_space(registry, reference) : NULL;
}

/* Version-specific evaluation laws are captured by each machine instance:
 * those of PeTTa's typed line hold in 1.1 and 1.1.c. */
static bool petta_eval_typed_line(void) {
    return cetta_language_version_petta_typed_line(cetta_language_version_of(
        CETTA_LANGUAGE_PETTA, active_eval_session()->profile));
}

bool eval_current_petta_typed_line(void) {
    return petta_eval_typed_line();
}

/* petta@1.1.c runs declarations as call contracts. */
static bool petta_eval_contracts(void) {
    return eval_current_language_id() == CETTA_LANGUAGE_PETTA &&
        cetta_profile_is_petta_1_1_c(active_eval_session()->profile);
}

/* Under call contracts no run-time dispatch recovers a contract's error:
 * a failed check raises the same error whatever route reached the call. */
static bool petta_eval_contract_raise(Atom *raised) {
    return raised && petta_eval_contracts() &&
        petta_semantics_contract_error(raised);
}

/* Source loading errors are independent of the optional type checker. */
static bool petta_import_parse_failure(Atom *error) {
    return error && error->kind == ATOM_EXPR &&
           error->expr.len > 0u &&
           atom_is_symbol_id(
               error->expr.elems[0], g_builtin_syms.module_parse_failed);
}

static TermUniverse *eval_current_term_universe(void) {
    if (g_eval_term_universe_override)
        return g_eval_term_universe_override;
    if (g_eval_root_space && g_eval_root_space->native.universe)
        return g_eval_root_space->native.universe;
    if (g_library_context && g_library_context->term_universe.persistent_arena)
        return &g_library_context->term_universe;
    if (g_eval_fallback_universe.persistent_arena)
        return &g_eval_fallback_universe;
    return NULL;
}

static Arena *eval_persistent_arena(void) {
    TermUniverse *universe = eval_current_term_universe();
    return universe ? universe->persistent_arena : NULL;
}

static Arena *eval_storage_arena(Arena *fallback) {
    Arena *persistent = eval_persistent_arena();
    return persistent ? persistent : fallback;
}

#if CETTA_BUILD_WITH_PETTA_TYPECHECK_V2
static PettaTypecheckPolicy eval_active_petta_typecheck_policy(void) {
    const CettaEvalOptionEntry *option =
        active_eval_option("petta-typecheck-policy");
    if (option && strcmp(option->repr, "strict-det") == 0)
        return PETTA_TYPECHECK_POLICY_STRICT_DET;
    if (option && strcmp(option->repr, "strict") == 0)
        return PETTA_TYPECHECK_POLICY_STRICT;
    return PETTA_TYPECHECK_POLICY_DEFAULT;
}

static uint32_t eval_active_petta_analysis_policy_id(void) {
    return (uint32_t)eval_active_petta_typecheck_policy();
}
#endif

static void eval_petta_typecheck_inferred_signatures_rebase(
    PettaProgram *program, Space *space) {
#if CETTA_BUILD_WITH_PETTA_TYPECHECK_V2
    petta_typecheck_inferred_signatures_rebase_selected(
        program, space, eval_active_petta_typecheck_policy());
#else
    (void)program;
    (void)space;
#endif
}

/* A typecheck-v2 program mutation is judged against the complete live
 * PettaProgram before any Space state or revision is published.  A failure
 * is a normal PeTTa Error value here, so catch can delimit it; only an
 * uncaught value becomes process exit 1/2 at the top-level boundary. */
static Atom *eval_petta_program_mutation_error(
    Arena *arena, Atom *source, Space *space, Atom *atom,
    PettaTypecheckMutation mutation) {
#if CETTA_BUILD_WITH_PETTA_TYPECHECK_V2
    CettaEvalSession *session = active_eval_session();
    if (!space || !atom || session->language_id != CETTA_LANGUAGE_PETTA ||
        !cetta_profile_uses_petta_typing(session->profile)) {
        return NULL;
    }
    CETTA_SCOPED_SHARED_TRANSITION(typecheck_mutation_read);
    PettaProgram *program = g_library_context
        ? g_library_context->petta_program : NULL;
    PettaTypecheckBlockResult checked;
    bool judged = petta_typecheck_program_mutation_selected(
        program, g_eval_root_space ? g_eval_root_space : space,
        g_registry, space, atom,
        mutation,
        eval_active_petta_typecheck_policy(), &checked);
    if (!judged) {
        return petta_typecheck_error_atom(
            arena, source, 1,
            checked.diagnostic[0]
                ? checked.diagnostic : "program mutation analysis failed");
    }
    if (checked.verdict == PETTA_TYPECHECK_REFUTED) {
        /* A data row that contradicts its typed space's schema meets PeTTa's
         * runtime row check: literal_type_mismatch(Row, RowType), raised at
         * the operation like any error. */
        Atom *row_type = mutation == PETTA_TYPECHECK_MUTATION_ADD
            ? petta_typecheck_refuted_row_type(
                  program, g_eval_root_space ? g_eval_root_space : space,
                  g_registry, space, atom, arena)
            : NULL;
        Atom *row_error = row_type
            ? petta_semantics_type_mismatch_error(arena, atom, row_type)
            : NULL;
        if (row_error) {
            petta_eval_raise(row_error);
            return row_error;
        }
        return petta_typecheck_error_atom(
            arena, source, 2,
            checked.diagnostic[0]
                ? checked.diagnostic : "program mutation rejected");
    }
    return NULL;
#else
    (void)arena;
    (void)source;
    (void)space;
    (void)atom;
    (void)mutation;
    return NULL;
#endif
}

static bool eval_admit_atom(Space *space, Arena *source_arena,
                            Arena *storage_arena, Atom *atom) {
    if (eval_unwinding()) return false;
    __attribute__((cleanup(cetta_shared_transition_guard_leave)))
    CettaSharedTransitionGuard shared_transition = {0};
    cetta_shared_transition_guard_enter(&shared_transition);
    return space_admit_atom_from_source_arena(
        space, storage_arena, source_arena, atom);
}

static bool eval_storage_is_persistent(const Arena *arena) {
    Arena *persistent = eval_persistent_arena();
    return persistent && persistent == arena;
}

static Arena *eval_active_episode_survivor_arena(void) {
    EvalExecutionContext *context = eval_execution_context();
    if (!context->survivor_ready) {
        arena_init(&context->survivor);
        arena_set_hashcons(&context->survivor, NULL);
        arena_set_runtime_kind(&context->survivor,
                               CETTA_ARENA_RUNTIME_KIND_SURVIVOR);
        context->survivor_ready = true;
    }
    return &context->survivor;
}

static void eval_release_episode_survivor_arena(void) {
    EvalExecutionContext *context = g_eval_execution;
    if (!context)
        return;
    if (!context->survivor_ready)
        return;
    arena_free(&context->survivor);
    context->survivor_ready = false;
}

static void eval_execution_clear_current(void) {
    if (!g_eval_execution)
        return;
    eval_execution_invalidate_borrows(g_eval_execution);
    eval_release_episode_table();
    eval_release_episode_answer_bank();
    eval_release_outcome_variant_bank();
    eval_release_episode_survivor_arena();
    prepared_pure_program_cache_destroy(g_eval_execution->prepared);
    g_eval_execution->prepared = NULL;
}

/* A captured payload retains a validity lease, never the invocation whose
 * banks may contain that payload frame. Destructive reset or final retirement
 * invalidates the lease before storage is released, without forming a cycle. */
static void eval_execution_context_destroy(EvalExecutionContext *context) {
    if (!context) return;
    EvalExecutionLease *lease=context->lease;
    assert(lease && lease->context==context);
    eval_execution_invalidate_borrows(context);
    lease->context=NULL;
    EvalExecutionContext *execution=g_eval_execution==context?NULL:g_eval_execution;
    VariantBank *variants=g_owned_outcome_variant_bank;
    g_eval_execution=context;g_owned_outcome_variant_bank=NULL;
    eval_execution_clear_current();
    g_eval_execution=execution;g_owned_outcome_variant_bank=variants;
    free(context);
    eval_execution_lease_release(lease);
}

static void eval_execution_scope_leave(EvalExecutionScope *scope) {
    if (!scope || !scope->owner)
        return;
    assert(g_eval_execution == scope->owner);
    EvalExecutionContext *owner=scope->owner;
    g_eval_execution = scope->previous;
    scope->owner = NULL;
    eval_execution_context_destroy(owner);
}

/* Public results leave the invocation before any of its banks are released.
 * A private variant bank uses hash-consed nodes whose arena_id is zero, so
 * its presence requires materialization even for an apparently closed root.
 * One copy session preserves aliases between distinct answer occurrences. */
static void eval_execution_publish_results(Arena *destination, ResultSet *results,
                                           CettaCount start, bool force) {
    EvalExecutionContext *context = g_eval_execution;
    force = force || (context && (context->answers_ready ||
        context->variants_ready || context->survivor_ready));
    AtomDeepCopySession *copy = NULL;
    for (CettaCount i = start; i < results->len; i++) {
        Atom *value = results->items[i];
        if (!value || (!force && atom_graph_is_closed_for_arena(destination, value)))
            continue;
        if (!copy) {
            copy = atom_deep_copy_session_new(destination);
            if (!copy)
                cetta_oom(sizeof(Atom));
        }
        Atom *published = atom_deep_copy_session_copy(copy, value);
        if (!published)
            cetta_oom(sizeof(Atom));
        results->items[i] = published;
    }
    atom_deep_copy_session_free(copy);
}

static void eval_query_episode_init(EvalQueryEpisode *episode) {
    Arena *persistent = eval_persistent_arena();
    if (!episode)
        return;
    arena_init(&episode->scratch);
    arena_set_hashcons(&episode->scratch, NULL);
    arena_set_runtime_kind(&episode->scratch, CETTA_ARENA_RUNTIME_KIND_SCRATCH);
    arena_init(&episode->generated);
    arena_set_hashcons(&episode->generated, NULL);
    arena_set_runtime_kind(&episode->generated, CETTA_ARENA_RUNTIME_KIND_SCRATCH);
    episode->survivor_arena = persistent ? persistent
                                         : eval_active_episode_survivor_arena();
    episode->active = true;
}

static void eval_query_episode_free(EvalQueryEpisode *episode) {
    if (!episode || !episode->active)
        return;
    arena_free(&episode->generated);
    arena_free(&episode->scratch);
    episode->survivor_arena = NULL;
    episode->active = false;
}

static void eval_query_episode_cleanup(EvalQueryEpisode *episode) {
    eval_query_episode_free(episode);
}

static Arena *eval_query_episode_scratch(EvalQueryEpisode *episode) {
    if (!episode || !episode->active)
        return NULL;
    return &episode->scratch;
}

static Arena *eval_query_episode_generated(EvalQueryEpisode *episode) {
    if (!episode || !episode->active)
        return NULL;
    return &episode->generated;
}

static Arena *eval_query_episode_result_arena(EvalQueryEpisode *episode,
                                              Arena *fallback) {
    if (!episode || !episode->active)
        return fallback;
    if (fallback) {
        episode->survivor_arena = fallback;
        return fallback;
    }
    if (!episode->survivor_arena)
        return fallback;
    return episode->survivor_arena;
}

static void eval_query_episode_note_answer_promotion(Arena *arena,
                                                     size_t before_bytes) {
    size_t after_bytes = arena ? arena->live_bytes : before_bytes;
    cetta_runtime_stats_inc(CETTA_RUNTIME_COUNTER_QUERY_EPISODE_PROMOTED_ANSWER_COUNT);
    if (after_bytes > before_bytes) {
        cetta_runtime_stats_add(
            CETTA_RUNTIME_COUNTER_QUERY_EPISODE_PROMOTED_ANSWER_BYTES,
            (uint64_t)(after_bytes - before_bytes));
    }
}

static bool eval_query_episode_promote_bindings(EvalQueryEpisode *episode,
                                                Bindings *bindings) {
    if (!episode || !episode->active || !episode->survivor_arena || !bindings)
        return true;
    /* Binding atoms follow the query answer into its survivor arena.  The
       immutable Prime Need snapshot is an episode-owned store handle: copying
       its frame path here would duplicate the store into an arena with a
       different lifetime and destroy the identity shared by sibling outcomes. */
    return bindings_promote_logical_atoms_to_arena(
        bindings, episode->survivor_arena);
}

static Atom *eval_store_atom(Arena *dst, Atom *src) {
    if (!eval_storage_is_persistent(dst))
        return atom_deep_copy(dst, src);
    return term_universe_store_atom(eval_current_term_universe(), dst, src);
}

/* State cells hold values. Syntax interning identifies an evaluated value
 * with its unmarked code, so a marked value (including marked fields) needs
 * an ordinary owned copy instead. Unmarked data keeps the existing path. */
static Atom *eval_store_value(Arena *dst, Atom *src) {
    if ((eval_current_language_id() == CETTA_LANGUAGE_HE ||
         eval_current_language_id() == CETTA_LANGUAGE_PRIME) &&
        atom_may_hold_he_mark(src))
        return atom_deep_copy(dst, src);
    return eval_store_atom(dst, src);
}

static Atom *space_compare_atom(const Space *space, Arena *dst, Atom *src) {
    if (space && space->native.universe &&
        space->native.universe->persistent_arena)
        return term_universe_canonicalize_atom(dst, src);
    return atom_deep_copy(dst, src);
}

/* Match standardization epochs are query-local tags, not stored identity.
   Removal must recover the stored base VarId instead of alpha-canonicalizing
   distinct variable-bearing rows into the same structural shape. */
static Atom *space_remove_compare_rewrite_var(Arena *dst, Atom *src_var,
                                              void *ctx) {
    (void)ctx;
    if (!src_var || src_var->kind != ATOM_VAR)
        return NULL;
    if (cetta_frame_identity_is_none(var_epoch_suffix(src_var->var_id)))
        return atom_deep_copy(dst, src_var);
    VarId base_id = var_source_id(src_var->var_id);
    if (var_id_is_none(base_id))
        return atom_deep_copy(dst, src_var);
    return atom_var_like(dst, src_var, base_id);
}

static Atom *space_remove_compare_atom(const Space *space, Arena *dst,
                                       Atom *src) {
    if (src && !atom_has_vars(src))
        return src;
    if (space && space->native.universe &&
        space->native.universe->persistent_arena) {
        return cetta_atom_rewrite_vars(dst, src,
                                       space_remove_compare_rewrite_var,
                                       NULL, true);
    }
    return atom_deep_copy(dst, src);
}

static bool space_comparison_uses_read_view(Atom *atom) {
    return atom && !space_atom_is_exact_indexable(atom) &&
        (g_eval_payload_transactional ||
         (g_library_context && g_library_context->import_space_alias_len));
}

static CettaMatchCompletion space_read_view_equal(Atom *left, Atom *right) {
    return atom_eq_with_resolved_spaces(left, right)
        ? CETTA_MATCH_MATCHED : CETTA_MATCH_REFUTED;
}

/* Stored primitive values and empty expressions have the same removal
 * interpretation as nonempty rows. Root variables are handled by the caller. */
static Atom *petta_space_remove_request_pattern(Arena *arena, Atom *value) {
    if (!arena || !value)
        return NULL;
    return value->kind != ATOM_VAR ? value : NULL;
}

/* One stable contraction by an occurrence mask, then every derived execution
 * view (specializer, program) told of each removed row.  Takes the mask and
 * the receipt. */
static bool petta_space_remove_masked(
        Space *space, uint8_t *remove_mask, CettaCount logical_len,
        Atom **removed_atoms, CettaCount receipt_len, PettaProgram *program,
        CettaCount *removed_out) {
    CettaCount removed = 0u;
    bool ok = space_remove_occurrence_mask_stable(
        space, remove_mask, logical_len, &removed);

    for (CettaCount index = 0u; ok && index < removed; index++) {
        Atom *removed_atom = removed_atoms[index];
        petta_specializer_note_mutation(space, removed_atom);
        if (program)
            petta_program_note_remove_all(program, space, removed_atom);
    }

    free(removed_atoms);
    free(remove_mask);
    if (removed_out)
        *removed_out = removed;
    return ok && removed == receipt_len;
}

/* PeTTa removal is the ordered-bag contraction induced by unifiability.
 * Discover the complete occurrence set against one pinned Space revision,
 * then use the resulting receipt to mutate both semantic authority and every
 * derived execution view.  Stored variables are freshened independently for
 * each occurrence, matching the ordinary Space query discipline. */
static bool petta_space_remove_linear_row_pattern(const Atom *pattern) {
    if (!pattern || pattern->kind != ATOM_EXPR || pattern->expr.len == 0u ||
        pattern->expr.len > 16u)
        return false;
    for (CettaExprIndex i = 0u; i < pattern->expr.len; i++) {
        const Atom *variable = pattern->expr.elems[i];
        if (!variable || variable->kind != ATOM_VAR ||
            var_id_is_none(variable->var_id))
            return false;
        for (CettaExprIndex j = 0u; j < i; j++)
            if (var_id_eq(variable->var_id, pattern->expr.elems[j]->var_id))
                return false;
    }
    return true;
}

typedef struct {
    CettaIndex position;
    Atom *atom;
} PettaRemovedRow;

static int petta_removed_row_compare(const void *left, const void *right) {
    CettaIndex a = ((const PettaRemovedRow *)left)->position;
    CettaIndex b = ((const PettaRemovedRow *)right)->position;
    return (a > b) - (a < b);
}

/* Order a removal receipt by position, keeping each row with its atom. */
static void petta_removal_receipt_sort(CettaIndex *positions, Atom **atoms,
                                       CettaCount len) {
    bool ascending = true;
    for (CettaCount i = 1u; i < len && ascending; i++)
        ascending = positions[i - 1u] < positions[i];
    if (ascending)
        return;
    PettaRemovedRow *rows = cetta_malloc((size_t)len * sizeof(*rows));
    for (CettaCount i = 0u; i < len; i++)
        rows[i] = (PettaRemovedRow){positions[i], atoms[i]};
    qsort(rows, (size_t)len, sizeof(*rows), petta_removed_row_compare);
    for (CettaCount i = 0u; i < len; i++) {
        positions[i] = rows[i].position;
        atoms[i] = rows[i].atom;
    }
    free(rows);
}

static bool petta_space_remove_pattern_all(
        Space *space, Atom *pattern, PettaProgram *program,
        CettaCount *removed_out) {
    if (removed_out)
        *removed_out = 0u;
    if (!space || !pattern || pattern->kind == ATOM_VAR)
        return false;

    __attribute__((cleanup(cetta_shared_transition_guard_leave)))
    CettaSharedTransitionGuard shared_transition = {0};
    cetta_shared_transition_guard_enter(&shared_transition);

    CettaCount logical_len = space_length64(space);
    if (logical_len == 0u)
        return true;
    /* A ground fact the space keeps as bits leaves them by its parts: it
     * may have no record of its own to look up.  Its row copies follow. */
    CettaCount bits_removed = atom_has_vars(pattern)
        ? 0u : space_dense_remove_ground(space, pattern);
    /* A ground pattern unifies with exactly the rows equal to it when no
     * row of its head holds a variable: the exact index removes those by
     * id, without reading any other row. */
    if (pattern->kind == ATOM_EXPR && pattern->expr.len != 0u &&
        !atom_has_vars(pattern) && space->native.universe &&
        pattern->expr.elems[0]->kind == ATOM_SYMBOL) {
        AtomId id = term_universe_lookup_atom_id(space->native.universe,
                                                 pattern);
        if (id == CETTA_ATOM_ID_NONE && bits_removed != 0u) {
            /* No record: no row holds it either. */
            petta_specializer_note_mutation(space, pattern);
            if (program)
                petta_program_note_remove_all(program, space, pattern);
            if (removed_out)
                *removed_out = bits_removed;
            return true;
        }
        if (id != CETTA_ATOM_ID_NONE &&
            space_remove_exact_ids(space, atom_symbol_current_id(pattern->expr.elems[0]),
                                   &id, 1u)) {
            CettaCount removed = logical_len - space_length64(space);
            if (removed != 0u)
                petta_specializer_note_mutation(space, pattern);
            for (CettaCount i = 0u; program && i < removed; i++)
                petta_program_note_remove_all(program, space, pattern);
            if (removed_out)
                *removed_out = removed;
            return true;
        }
    }
    bool linear = petta_space_remove_linear_row_pattern(pattern);
    if (logical_len > SIZE_MAX / sizeof(Atom *))
        return false;

    CettaCount receipt_len = 0u;
    SpaceReadToken source = space_read_token(space);
    Arena scratch;
    arena_init(&scratch);
    ArenaMark scratch_origin = arena_mark(&scratch);
    bool ok = true;

    /* Only native, uncomposed candidate coordinates are the logical
     * occurrence positions consumed by the removal mask. Other stores keep
     * the full logical scan until they supply that coordinate contract. */
    bool indexed = pattern->kind == ATOM_EXPR && pattern->expr.len != 0u &&
        !space->overlay_base && !space_has_dependencies(space) &&
        !space_match_reads_rows(space, logical_len) &&
        (space->match_backend.kind == SPACE_ENGINE_NATIVE ||
         space->match_backend.kind == SPACE_ENGINE_NATIVE_CANDIDATE_EXACT);
    if (indexed) {
        /* A constructor with only free argument positions is a broad row
         * scan. Collecting its frontier adds work before the same matching
         * pass, so retain the direct scan for that access shape. */
        bool constrained_argument = false;
        for (CettaExprIndex i = 1u; i < pattern->expr.len; i++) {
            if (pattern->expr.elems[i]->kind != ATOM_VAR) {
                constrained_argument = true;
                break;
            }
        }
        indexed = constrained_argument;
    }
    CettaIndex *candidates = NULL;
    CettaCount candidate_len = indexed
        ? space_match_candidates64(space, pattern, &candidates) : logical_len;
    /* The receipt: removed positions in ascending order and their atoms. */
    CettaIndex *removed_positions = cetta_malloc(
        (size_t)(candidate_len ? candidate_len : 1u) *
        sizeof(*removed_positions));
    Atom **removed_atoms = cetta_malloc(
        (size_t)(candidate_len ? candidate_len : 1u) *
        sizeof(*removed_atoms));
    for (CettaIndex position = 0u; ok && position < candidate_len; position++) {
        CettaIndex index = indexed ? candidates[position] : position;
        if (index >= logical_len) {
            ok = false;
            break;
        }
        CETTA_FRAME_IDENTITY_SCOPE(frame_identity_scope);
        AtomId atom_id = space_get_atom_id_at64(space, index);
        Atom *candidate = space_get_at64(space, index);
        if (linear && candidate && candidate->kind == ATOM_EXPR &&
            atom_petta_value_representation(candidate) == PETTA_VALUE_ORDINARY &&
            !atom_is_list(candidate) && !atom_is_list_rest(candidate) &&
            !atom_structural_has_rational(candidate)) {
            if (candidate->expr.len == pattern->expr.len) {
                removed_positions[receipt_len] = index;
                removed_atoms[receipt_len++] = candidate;
            }
            continue;
        }
        CettaFrameIdentity epoch = CETTA_FRAME_IDENTITY_NONE;
        Bindings trial;
        bindings_init(&trial);

        if (!candidate || !cetta_frame_identity_scope_try(&frame_identity_scope, &epoch)) {
            ok = false;
        } else {
            bool matched = atom_id != CETTA_ATOM_ID_NONE && space->universe
                ? match_atoms_atom_id_epoch(
                      pattern, space->universe, atom_id,
                      &trial, &scratch, epoch)
                : match_atoms_epoch(
                      pattern, candidate, &trial, &scratch, epoch);
            if (matched) {
                removed_positions[receipt_len] = index;
                removed_atoms[receipt_len++] = candidate;
            }
        }

        bindings_free(&trial);
        arena_reset(&scratch, scratch_origin);
    }
    free(candidates);
    arena_free(&scratch);

    if (!ok || !space_read_token_matches_live_space(source, space)) {
        free(removed_atoms);
        free(removed_positions);
        return false;
    }
    /* An index offers its rows in its own order; the receipt is read by
     * ascending position. */
    if (indexed)
        petta_removal_receipt_sort(removed_positions, removed_atoms, receipt_len);
    /* Data rows are marked and contracted later in one pass; other rows,
     * and spaces without marks, contract at once. */
    if (receipt_len != 0u &&
        space_remove_logical_positions(space, removed_positions, receipt_len)) {
        for (CettaCount index = 0u; index < receipt_len; index++) {
            petta_specializer_note_mutation(space, removed_atoms[index]);
            if (program)
                petta_program_note_remove_all(
                    program, space, removed_atoms[index]);
        }
        free(removed_atoms);
        free(removed_positions);
        if (removed_out)
            *removed_out = receipt_len;
        return true;
    }
    uint8_t *remove_mask = cetta_malloc((size_t)logical_len);
    memset(remove_mask, 0, (size_t)logical_len);
    for (CettaCount index = 0u; index < receipt_len; index++)
        remove_mask[removed_positions[index]] = 1u;
    free(removed_positions);
    return petta_space_remove_masked(space, remove_mask, logical_len,
                                     removed_atoms, receipt_len, program,
                                     removed_out);
}

/* The rows of one length, all but the first `keep` of them, removed as
 * petta_space_remove_pattern_all removes: a static-import! load redefining
 * the predicate they are. */
static bool petta_space_remove_rows_of_length(
        Space *space, CettaExprLen length, CettaCount keep,
        PettaProgram *program) {
    if (!space)
        return false;

    __attribute__((cleanup(cetta_shared_transition_guard_leave)))
    CettaSharedTransitionGuard shared_transition = {0};
    cetta_shared_transition_guard_enter(&shared_transition);

    CettaCount logical_len = space_length64(space);
    if (logical_len == 0u)
        return true;
    if (logical_len > SIZE_MAX / sizeof(Atom *))
        return false;
    uint8_t *remove_mask = cetta_malloc((size_t)logical_len);
    memset(remove_mask, 0, (size_t)logical_len);
    Atom **removed_atoms = cetta_malloc(
        (size_t)logical_len * sizeof(*removed_atoms));
    CettaCount receipt_len = 0u;
    CettaCount seen = 0u;
    for (CettaIndex index = 0u; index < logical_len; index++) {
        Atom *row = space_get_at64(space, index);
        if (!row || row->kind != ATOM_EXPR || row->expr.len != length)
            continue;
        if (seen++ < keep)
            continue;
        remove_mask[index] = 1u;
        removed_atoms[receipt_len++] = row;
    }
    if (receipt_len == 0u) {
        free(removed_atoms);
        free(remove_mask);
        return true;
    }
    CettaCount removed = 0u;
    return petta_space_remove_masked(space, remove_mask, logical_len,
                                     removed_atoms, receipt_len, program,
                                     &removed);
}

/* ── Outcome set (unified result type: atom + bindings) ─────────────────── */

void outcome_set_init_with_owner(OutcomeSet *os, Arena *owner) {
    memset(os->inline_items, 0, sizeof(os->inline_items));
    os->items = os->inline_items;
    os->len = 0;
    os->cap = 1;
    os->payload_owner = owner;
}

void outcome_set_init(OutcomeSet *os) {
    outcome_set_init_with_owner(os, NULL);
}

void outcome_set_set_owner(OutcomeSet *os, Arena *owner) {
    if (!os)
        return;
    os->payload_owner = owner;
}

static Arena *outcome_set_payload_arena(const OutcomeSet *os, Arena *fallback) {
    if (!os || !os->payload_owner)
        return fallback;
    return os->payload_owner;
}

static void outcome_set_bind_owner_if_missing(OutcomeSet *os, Arena *owner) {
    if (!os || os->payload_owner || !owner)
        return;
    os->payload_owner = owner;
}

static bool outcome_set_ensure_one(OutcomeSet *os) {
    CettaCount next_cap;
    bool using_inline;
    if (!os)
        return false;
    if (os->len < os->cap)
        return true;
    if (!eval_next_capacity(os->cap, os->len + 1u, sizeof(Outcome), &next_cap))
        return false;
    using_inline = os->items == os->inline_items;
    if (using_inline) {
        Outcome *next = cetta_malloc(sizeof(Outcome) * (size_t)next_cap);
        if (os->len > 0)
            memcpy(next, os->items, sizeof(Outcome) * (size_t)os->len);
        os->items = next;
    } else {
        os->items = cetta_realloc(os->items, sizeof(Outcome) * (size_t)next_cap);
    }
    os->cap = next_cap;
    return true;
}

static Outcome *outcome_set_push_slot(OutcomeSet *os) {
    if (!outcome_set_ensure_one(os))
        return NULL;
    return &os->items[os->len++];
}

static void outcome_init(Outcome *out) {
    if (!out)
        return;
    out->kind = CETTA_OUTCOME_INLINE;
    out->result_form = CETTA_CALL_RESULT_COMPLETED_VALUE;
    out->atom = NULL;
    out->materialized_atom = NULL;
    out->delayed = NULL;
    bindings_init(&out->env);
    variant_instance_init(&out->variant);
    out->answer_ref.bank = NULL;
    out->answer_ref.ref = CETTA_ANSWER_REF_NONE;
    cetta_var_map_init(&out->answer_ref.goal_instantiation);
}

static void outcome_free_fields(Outcome *out) {
    if (!out)
        return;
    bindings_free(&out->env);
    variant_instance_free(&out->variant);
    cetta_var_map_free(&out->answer_ref.goal_instantiation);
    out->answer_ref.bank = NULL;
    out->answer_ref.ref = CETTA_ANSWER_REF_NONE;
    out->kind = CETTA_OUTCOME_INLINE;
    out->result_form = CETTA_CALL_RESULT_COMPLETED_VALUE;
    out->atom = NULL;
    out->materialized_atom = NULL;
    out->delayed = NULL;
}

static void outcome_move(Outcome *dst, Outcome *src) {
    dst->kind = src->kind;
    dst->result_form = src->result_form;
    dst->atom = src->atom;
    dst->materialized_atom = src->materialized_atom;
    dst->delayed = src->delayed;
    bindings_move(&dst->env, &src->env);
    variant_instance_move(&dst->variant, &src->variant);
    dst->answer_ref = src->answer_ref;
    cetta_var_map_init(&src->answer_ref.goal_instantiation);
    src->answer_ref.bank = NULL;
    src->answer_ref.ref = CETTA_ANSWER_REF_NONE;
    src->kind = CETTA_OUTCOME_INLINE;
    src->result_form = CETTA_CALL_RESULT_COMPLETED_VALUE;
    src->atom = NULL;
    src->materialized_atom = NULL;
    src->delayed = NULL;
}

static void outcome_refresh_materialized_fast_path(Outcome *out);
static bool bindings_effective_merge(Bindings *owned,
                                     const Bindings **effective,
                                     const Bindings *outer_env,
                                     const Bindings *inner_env,
                                     bool include_constraints);

static CettaMatchCompletion bindings_effective_merge_checked(
    Bindings *owned, const Bindings **effective,
    const Bindings *outer, const Bindings *inner, bool constraints);

static bool outcome_clone_goal_instantiation(Arena *owner,
                                             CettaVarMap *dst,
                                             const CettaVarMap *src) {
    if (owner)
        return cetta_var_map_clone_live(owner, dst, src);
    return cetta_var_map_clone(dst, src);
}

static bool outcome_promote_payload(Arena *owner, Outcome *out) {
    if (!owner || !out)
        return true;
    AtomDeepCopySession *session =
        atom_deep_copy_session_new(owner);
    if (!session)
        return false;
    bool promoted = true;
    if (out->kind == CETTA_OUTCOME_INLINE && out->atom) {
        Atom *promoted_atom =
            atom_deep_copy_session_copy(session, out->atom);
        if (!promoted_atom) {
            promoted = false;
        } else {
            out->atom = promoted_atom;
        }
    }
    if (promoted && out->delayed) {
        out->delayed = atom_deep_copy_session_copy(session, out->delayed);
        promoted = out->delayed != NULL;
    }
    /* Outcome arenas own the visible bindings and variant payload.  Prime's
       persistent Need frames are owned for the whole top-level evaluation;
       an outcome carries only an immutable snapshot handle into that store. */
    if (promoted)
        promoted = bindings_promote_logical_atoms_with_session(
            &out->env, session);
    if (promoted)
        promoted = variant_instance_promote_atoms_with_session(
            session, &out->variant);
    atom_deep_copy_session_free(session);
    if (!promoted)
        return false;
    out->materialized_atom = NULL;
    outcome_refresh_materialized_fast_path(out);
    return true;
}

/* A pure speculative call may extend the branch-local Need heap even though
 * none of that extension is reachable from the continuation it returns.
 * Discarding the suffix additionally requires every changed cell to be private
 * to the call: a scalar result may have forced a cell the caller still holds.
 * Every visible logical carrier must be free of registry capabilities, and
 * branch-state/receipt observations must be unchanged. The storage-key
 * watermark remains monotone even when the private suffix is discarded. */
static bool outcome_region_prefix_only_need(
    const PrimeNeedRegionScope *scope, const Outcome *src,
    const Atom *extra_support_root, PrimeNeedSnapshot *retained,
    bool *had_suffix) {
    if (had_suffix)
        *had_suffix = false;
    if (!scope || !src || !retained || !had_suffix ||
        !bindings_prime_present(&src->env) ||
        !prime_need_snapshot_present(&scope->context.previous)) {
        return false;
    }
    const PrimeNeedSnapshot *candidate = bindings_need_view(&src->env);
    if (!prime_need_snapshot_present(candidate) ||
        candidate->session_id != scope->context.previous.session_id ||
        candidate->top == scope->context.previous.top ||
        !prime_need_snapshot_is_ancestor(
            &scope->context.previous, candidate)) {
        return false;
    }
    *had_suffix = true;
    cetta_runtime_stats_inc(
        CETTA_RUNTIME_COUNTER_PRIME_NEED_REGION_SUPPORT_QUERY);
    const PrimeNeedBranchState *candidate_state =
        bindings_branch_state_view(&src->env);
    if (atom_has_registry_refs(src->atom) ||
        atom_has_registry_refs(extra_support_root) ||
        bindings_logical_has_registry_refs(&src->env) ||
        variant_instance_has_registry_refs(&src->variant) ||
        candidate_state->session_id !=
            scope->context.previous_branch_state.session_id ||
        candidate_state->top != scope->context.previous_branch_state.top ||
        !cetta_weight_ledger_equal(bindings_weight_view(&src->env),
                                   &scope->context.previous_weights)) {
        return false;
    }
#if CETTA_BUILD_WITH_PRIME_CAUSAL_RECEIPTS
    const PrimeNeedReceipt *candidate_receipt =
        bindings_receipt_view(&src->env);
    const PrimeNeedReceipt *original_receipt =
        prime_need_active_original_receipt(&scope->context);
    if (candidate_receipt->session_id != original_receipt->session_id ||
        candidate_receipt->top != original_receipt->top) {
        return false;
    }
#endif
    if (!prime_need_snapshot_suffix_is_private(
            &scope->context.previous, candidate))
        return false;
    *retained = scope->context.previous;
    if (retained->max_storage_key < candidate->max_storage_key)
        retained->max_storage_key = candidate->max_storage_key;
    cetta_runtime_stats_inc(
        CETTA_RUNTIME_COUNTER_PRIME_NEED_REGION_SUFFIX_ELISION_ELIGIBLE);
    return true;
}

/* Promote one complete speculative outcome into a longer-lived region.  One
 * copy session preserves sharing across the visible atom, logical bindings,
 * variant slots, Need heap suffix, and receipt suffix.  The caller owns the
 * destination rollback boundary and publishes `dst` only after this returns
 * true.  AnswerBank references are intentionally outside this first region
 * contract: tabled execution has a separate revision/lifetime protocol. */
static bool outcome_region_promote_one_with_session(
    Arena *owner, const Arena *forbidden,
    AtomDeepCopySession *session, Outcome *dst,
    const Outcome *src, const Atom *extra_support_root,
    const PrimeNeedRegionScope *scope) {
    if (!owner || !forbidden || !session || !dst || !src ||
        owner == forbidden || src->kind != CETTA_OUTCOME_INLINE) {
        return false;
    }
    outcome_init(dst);
    dst->kind = CETTA_OUTCOME_INLINE;
    dst->result_form = src->result_form;
    dst->atom = src->atom;
    bindings_assert_no_private_variant_slots(&src->env);
    if (!bindings_clone(&dst->env, &src->env) ||
        !variant_instance_clone(&dst->variant, &src->variant)) {
        outcome_free_fields(dst);
        return false;
    }

    PrimeNeedSnapshot retained_need;
    prime_need_snapshot_init(&retained_need);
    bool had_need_suffix = false;
    bool elide_need_suffix = outcome_region_prefix_only_need(
        scope, src, extra_support_root, &retained_need,
        &had_need_suffix);
    if (elide_need_suffix)
        *bindings_need_mut(&dst->env) = retained_need;

    bool promoted = true;
    if (dst->atom) {
        dst->atom = atom_deep_copy_session_copy(session, dst->atom);
        promoted = dst->atom != NULL;
    }
    if (promoted && src->delayed) {
        dst->delayed = atom_deep_copy_session_copy(session, src->delayed);
        promoted = dst->delayed != NULL;
    }
    if (promoted) {
        promoted = bindings_promote_logical_atoms_with_session(
            &dst->env, session);
    }
    if (promoted) {
        promoted = variant_instance_promote_atoms_with_session(
            session, &dst->variant);
    }
    if (promoted && bindings_weight_view(&dst->env)->length)
        promoted = cetta_weight_ledger_promote(owner, bindings_weight_mut(&dst->env));
    if (promoted && bindings_prime_present(&dst->env)) {
        promoted = prime_need_snapshot_promote_suffix_with_session(
            owner, forbidden, session, bindings_need_mut(&dst->env));
    }
    if (promoted && bindings_prime_present(&dst->env)) {
        promoted = prime_need_branch_state_promote_suffix_with_session(
            owner, forbidden, session,
            bindings_branch_state_mut(&dst->env));
    }
#if CETTA_BUILD_WITH_PRIME_CAUSAL_RECEIPTS
    if (promoted && bindings_prime_present(&dst->env)) {
        promoted = prime_need_receipt_carry_suffix_with_session(
            owner, forbidden, session, bindings_receipt_mut(&dst->env));
    }
#endif

    /* This audit is always on.  The atom closure predicates are exact and
     * stronger than excluding only `forbidden`: every owned atom pointer is
     * now either in `owner` or globally immutable.  Need and receipt audits
     * walk their complete persistent structures because those may retain a
     * deliberately mixed longer-lived prefix. */
    if (promoted && dst->atom)
        promoted = atom_graph_is_closed_for_arena(owner, dst->atom);
    if (promoted) {
        promoted = bindings_logical_atoms_closed_for_arena(
            &dst->env, owner);
    }
    if (promoted) {
        promoted = variant_instance_atoms_closed_for_arena(
            &dst->variant, owner);
    }
    if (promoted && bindings_prime_present(&dst->env)) {
        promoted = prime_need_snapshot_excludes_arena(
                       bindings_need_view(&dst->env), forbidden) &&
                   prime_need_branch_state_excludes_arena(
                       bindings_branch_state_view(&dst->env), forbidden);
    }
#if CETTA_BUILD_WITH_PRIME_CAUSAL_RECEIPTS
    if (promoted && bindings_prime_present(&dst->env)) {
        promoted = prime_need_receipt_excludes_arena(
            bindings_receipt_view(&dst->env), forbidden);
    }
#endif
    if (!promoted) {
        outcome_free_fields(dst);
        return false;
    }
    if (elide_need_suffix) {
        cetta_runtime_stats_inc(
            CETTA_RUNTIME_COUNTER_PRIME_NEED_REGION_SUFFIX_ELISION_COMMIT);
    } else if (had_need_suffix) {
        cetta_runtime_stats_inc(
            CETTA_RUNTIME_COUNTER_PRIME_NEED_REGION_SUFFIX_RETAINED);
    }
    dst->materialized_atom = NULL;
    outcome_refresh_materialized_fast_path(dst);
    return true;
}

/* All-or-nothing publication of a complete occurrence bag.  Failed
 * promotion restores both the OutcomeSet length and the destination arena;
 * the caller can then run the canonical non-region path unchanged. */
static bool outcome_set_append_region_promoted(
    Arena *owner, const Arena *forbidden,
    OutcomeSet *dst, const OutcomeSet *src,
    const PrimeNeedRegionScope *scope) {
    if (!owner || !forbidden || !dst || !src || owner == forbidden)
        return false;
    ArenaMark mark = arena_mark(owner);
    CettaCount original_len = dst->len;
    AtomDeepCopySession *session = atom_deep_copy_session_new(owner);
    if (!session)
        return false;

    bool promoted = true;
    for (CettaCount i = 0u; promoted && i < src->len; i++) {
        Outcome candidate;
        promoted = outcome_region_promote_one_with_session(
            owner, forbidden, session, &candidate, &src->items[i],
            NULL, scope);
        if (!promoted)
            break;
        Outcome *slot = outcome_set_push_slot(dst);
        if (!slot) {
            outcome_free_fields(&candidate);
            promoted = false;
            break;
        }
        outcome_init(slot);
        outcome_move(slot, &candidate);
    }
    atom_deep_copy_session_free(session);
    if (promoted)
        return true;

    while (dst->len > original_len) {
        dst->len--;
        outcome_free_fields(&dst->items[dst->len]);
    }
    arena_reset(owner, mark);
    return false;
}

static bool outcome_region_promote_tail(
    Arena *owner, const Arena *forbidden,
    Atom *source_atom, Atom *source_type,
    const Bindings *source_env,
    Atom **promoted_atom, Atom **promoted_type,
    Bindings *promoted_env, const PrimeNeedRegionScope *scope) {
    if (promoted_atom)
        *promoted_atom = NULL;
    if (promoted_type)
        *promoted_type = NULL;
    if (!owner || !forbidden || !source_atom || !source_env ||
        !promoted_atom || !promoted_env || owner == forbidden) {
        return false;
    }

    ArenaMark mark = arena_mark(owner);
    AtomDeepCopySession *session = atom_deep_copy_session_new(owner);
    if (!session)
        return false;
    Outcome source;
    outcome_init(&source);
    source.atom = source_atom;
    /* The source is borrowed: the promotion routine clones it before making
     * any change, so the branch retains sole ownership of its heap metadata. */
    source.env = *source_env;
    Outcome candidate;
    outcome_init(&candidate);
    bool promoted = outcome_region_promote_one_with_session(
        owner, forbidden, session, &candidate, &source,
        source_type, scope);
    Atom *type = NULL;
    if (promoted && source_type) {
        type = atom_deep_copy_session_copy(session, source_type);
        promoted = type && atom_graph_is_closed_for_arena(owner, type);
    }
    atom_deep_copy_session_free(session);
    if (!promoted) {
        if (candidate.kind == CETTA_OUTCOME_INLINE)
            outcome_free_fields(&candidate);
        arena_reset(owner, mark);
        return false;
    }

    *promoted_atom = candidate.atom;
    if (promoted_type)
        *promoted_type = type;
    bindings_move(promoted_env, &candidate.env);
    outcome_free_fields(&candidate);
    return true;
}

static bool outcome_clone_fields(Outcome *dst, const Outcome *src, Arena *owner) {
    if (!dst || !src)
        return false;
    outcome_init(dst);
    dst->kind = src->kind;
    dst->result_form = src->result_form;
    dst->atom = src->atom;
    dst->materialized_atom = src->materialized_atom;
    dst->delayed = src->delayed;
    dst->answer_ref.bank = src->answer_ref.bank;
    dst->answer_ref.ref = src->answer_ref.ref;
    if (!bindings_clone(&dst->env, &src->env) ||
        !variant_instance_clone(&dst->variant, &src->variant) ||
        !outcome_clone_goal_instantiation(owner,
                                          &dst->answer_ref.goal_instantiation,
                                          &src->answer_ref.goal_instantiation)) {
        outcome_free_fields(dst);
        return false;
    }
    return true;
}

static bool outcome_clone(Outcome *dst, const Outcome *src, Arena *owner) {
    if (!outcome_clone_fields(dst, src, owner))
        return false;
    if (owner && !outcome_promote_payload(owner, dst)) {
        outcome_free_fields(dst);
        return false;
    }
    if (!dst->materialized_atom)
        outcome_refresh_materialized_fast_path(dst);
    return true;
}

typedef CettaMatchCompletion (*OutcomeReaderContextCopy)(
    const PrimeNeedReaderContext *,AtomDeepCopySession *,PrimeNeedReaderContext **);
static bool outcome_copy_owned(Outcome *dst, const Outcome *src,
    Arena *arena,AtomDeepCopySession *atoms,bool retain_readers,
    OutcomeReaderContextCopy copy_readers) {
    /* A table reference has a separate bank owner. It cannot be made owned
     * by copying the visible answer or by retaining its numeric index. */
    if (src->kind != CETTA_OUTCOME_INLINE || src->answer_ref.bank ||
        !outcome_clone_fields(dst, src, NULL))
        return false;
    if(retain_readers)return true;
    PrimeNeedReaderContext *readers=NULL;
    PrimeNeedReaderContext *source_readers=bindings_reader_context_view(&src->env);
    if(source_readers) {
        if(!copy_readers||copy_readers(source_readers,atoms,&readers)!=CETTA_MATCH_MATCHED) {
            outcome_free_fields(dst);return false;
        }
        bindings_reader_context_set(&dst->env,NULL);
    }
    Atom **roots[] = {&dst->atom, &dst->materialized_atom, &dst->delayed};
    bool copied = true;
    for (size_t i = 0u; copied && i < sizeof(roots) / sizeof(*roots); i++) {
        if (*roots[i]) {
            *roots[i] = atom_deep_copy_session_copy(atoms, *roots[i]);
            copied = *roots[i] != NULL;
        }
    }
    CettaVarMap *map = &dst->answer_ref.goal_instantiation;
    for (uint32_t i = 0u; copied && i < map->len; i++) {
        if (map->items[i].mapped_var) {
            map->items[i].mapped_var = atom_deep_copy_session_copy(
                atoms, map->items[i].mapped_var);
            copied = map->items[i].mapped_var != NULL;
        }
    }
    copied = copied && bindings_copy_owned_atoms_with_session(
            &dst->env,arena,atoms) &&
             variant_instance_promote_atoms_with_session(atoms, &dst->variant);
    if(copied&&readers)bindings_reader_context_set(&dst->env,readers);
    prime_need_reader_context_release(readers);
    if (!copied)
        outcome_free_fields(dst);
    return copied;
}

static bool outcome_set_copy_to_arena_mode(const OutcomeSet *source,
    OutcomeSet *destination,Arena *arena,AtomDeepCopySession *atoms,
    bool retain_readers,OutcomeReaderContextCopy copy_readers) {
    if (!source || !destination || source == destination || !source->items ||
        !source->cap || source->len > source->cap ||
        source->cap > SIZE_MAX / sizeof(Outcome) ||
        (source->items == source->inline_items && source->cap != 1u) ||
        !atom_deep_copy_session_targets(atoms, arena) ||
        (source->payload_owner && !atom_deep_copy_session_maps_arena(
            atoms, source->payload_owner, arena)))
        return false;
    OutcomeSet prepared;
    outcome_set_init_with_owner(&prepared, source->payload_owner ? arena : NULL);
    if (source->items != source->inline_items) {
        prepared.items = cetta_malloc(sizeof(Outcome) * (size_t)source->cap);
        prepared.cap = source->cap;
    }
    for (CettaCount i = 0u; i < source->len; i++) {
        if (!outcome_copy_owned(&prepared.items[i], &source->items[i], arena,
                atoms,retain_readers,copy_readers)) {
            outcome_set_free(&prepared);
            return false;
        }
        prepared.len++;
    }
    /* Commit only metadata owned by this set. The enclosing transport owns
     * arena/session rollback; a refused preparation may have copied roots. */
    outcome_set_free(destination);
    destination->payload_owner = prepared.payload_owner;
    if (prepared.items != prepared.inline_items) {
        destination->items = prepared.items;
        destination->len = prepared.len;
        destination->cap = prepared.cap;
    } else if (prepared.len) {
        outcome_init(&destination->inline_items[0]);
        outcome_move(&destination->inline_items[0], &prepared.inline_items[0]);
        destination->len = prepared.len;
    }
    return true;
}

bool outcome_set_copy_to_arena(const OutcomeSet *source,OutcomeSet *destination,
        Arena *arena,AtomDeepCopySession *atoms) {
    return outcome_set_copy_to_arena_mode(
        source,destination,arena,atoms,false,NULL);
}

bool outcome_set_copy_to_episode(const OutcomeSet *source,
        OutcomeSet *destination,Arena *arena,AtomDeepCopySession *atoms) {
    return outcome_set_copy_to_arena_mode(
        source,destination,arena,atoms,true,NULL);
}

static bool outcome_set_copy_to_arena_mapping_readers(
        const OutcomeSet *source,OutcomeSet *destination,Arena *arena,
        AtomDeepCopySession *atoms,OutcomeReaderContextCopy copy_readers) {
    return outcome_set_copy_to_arena_mode(source,destination,arena,atoms,
        false,copy_readers);
}

bool outcome_set_relocate_clone(OutcomeSet *dst, const OutcomeSet *src,
                               Arena *owner, AtomDeepCopySession *session) {
    if (!dst || !src || dst == src || !owner || !session)
        return false;
    outcome_set_init_with_owner(dst, owner);
    for (CettaCount index = 0u; index < src->len; index++) {
        const Outcome *source = &src->items[index];
        /* Answer-bank references and Need snapshots have separate authority
         * and lifetime contracts. They are not admitted by this relocation. */
        if (source->kind == CETTA_OUTCOME_ANSWER_REF ||
            bindings_prime_present(&source->env))
            goto failed;
        Outcome *target = outcome_set_push_slot(dst);
        if (!target || !outcome_clone(target, source, NULL)) {
            if (target)
                dst->len--;
            goto failed;
        }
        Atom **atoms[] = {&target->atom, &target->materialized_atom,
                          &target->delayed};
        for (size_t field = 0u; field < sizeof(atoms) / sizeof(atoms[0]); field++) {
            if (*atoms[field] && !(*atoms[field] =
                    atom_deep_copy_session_copy(session, *atoms[field])))
                goto failed;
        }
        if (!bindings_promote_logical_atoms_with_session(&target->env, session) ||
            !variant_instance_promote_atoms_with_session(session, &target->variant))
            goto failed;
        for (uint32_t item = 0u;
             item < target->answer_ref.goal_instantiation.len; item++) {
            Atom **mapped = &target->answer_ref.goal_instantiation.items[item].mapped_var;
            if (*mapped && !(*mapped = atom_deep_copy_session_copy(session, *mapped)))
                goto failed;
        }
    }
    return true;
failed:
    outcome_set_free(dst);
    return false;
}

static bool atom_contains_vars(const Atom *atom) {
    return atom_has_vars(atom);
}

static Atom *outcome_preview_atom(const Outcome *out) {
    if (!out)
        return NULL;
    if (out->kind == CETTA_OUTCOME_INLINE)
        return out->atom;
    if (!out->answer_ref.bank || out->answer_ref.ref == CETTA_ANSWER_REF_NONE)
        return NULL;
    const AnswerRecord *record =
        answer_bank_get(out->answer_ref.bank, out->answer_ref.ref);
    return record ? record->result : NULL;
}

static bool dispatch_native_op(Space *s, Arena *a, Atom *head, Atom **args, uint32_t nargs, CettaCallOutcome *outcome);
static bool dispatch_native_invocation(Space *s, Arena *a,
                                       const CettaInvocation *invocation,
                                       CettaCallOutcome *outcome);
static Atom *native_outcome_expression(Arena *a, CettaCallOutcome outcome);
static bool sequence_native_call(Space *space, Arena *arena,
    CettaCallOutcome outcome, bool expression_is_value, Atom *expected_type,
    const Bindings *environment, OutcomeSet *outcomes, Atom **expression);
static bool try_stream_count_size_collapse(Space *s, Arena *a, Atom *atom,
                                           const Bindings *current_env, int fuel,
                                           CettaCallOutcome *outcome);
static bool count_size_collapse_for_native_call(Space *space, Arena *arena,
    Atom *source, int fuel, CettaCallOutcome *outcome);
static Atom *materialize_runtime_token(Space *s, Arena *a, Atom *atom);

/* The one environment action (Prime): capture-avoiding substitution of the
 * store over the binding structure (prime_semantics_env_apply).  It acts on
 * variable identity, the slot, never on spelling.  HE and PeTTa keep
 * whole-term substitution. A refused action leaves the episode incomplete;
 * whole-term substitution is a different interpretation of binders/code. */
static Atom *eval_env_apply(const Bindings *env, Arena *a, Atom *atom) {
    if (!env || !atom || !atom_has_vars(atom) ||
        !bindings_has_bound_values(env))
        return atom;
    if (eval_current_language_id() == CETTA_LANGUAGE_PRIME) {
        Atom *applied = prime_semantics_env_apply(a, env, atom);
        if (!applied)
            eval_mark_interrupted(CETTA_EVAL_INCOMPLETE_HOST_FAILURE);
        return applied;
    }
    return bindings_apply_if_vars(env, a, atom);
}

static Space *resolve_single_space_arg(Space *s, Arena *a, Atom *space_expr, int fuel);
static Space *petta_ensure_named_space(
    Space *root, Arena *a, Atom *space_ref);
