/* Compiled result interfaces are distinct cache identities. Source argument
 * interpretation, revisions and value readiness remain independent keys. */
typedef enum {
    PREPARED_PURE_PROGRAM_SINGLE_VALUE,
    PREPARED_PURE_PROGRAM_ANSWERS,
    PREPARED_PURE_PROGRAM_RETAINED_CALL,
    PREPARED_PURE_PROGRAM_OPTIONAL_VALUE,
} PreparedPureProgramKind;
typedef enum {
    PREPARED_PURE_COMPILE_INQUIRY,
    PREPARED_PURE_ADMISSION_INQUIRY,
    PREPARED_PURE_ENTRY_INQUIRY,
} PreparedPureRefusalInquiry;

typedef struct PreparedPureCacheEntry {
    struct PreparedPureCacheEntry *next;
    Space *space;
    SymbolId head;
    CettaExprLen arity;
    CettaLanguageId language_id;
    CettaGsltPureCallMode call_mode;
    PreparedPureProgramKind kind;
    const void *source_identity;
    bool entry_arguments_are_values;
    bool total_structural_equality;
    bool admission_refused;
    CettaPreparedPureProgram *program;
} PreparedPureCacheEntry;

/* A remembered answer of the decline lookup for one head-keyed question.
 * `stamp` is the entry generation it was read under, plus one, so a zeroed
 * slot never answers. */
typedef struct {
    uint64_t stamp;
    SymbolId head;
    CettaExprLen arity;
    CettaLanguageId language_id;
    CettaGsltPureCallMode call_mode;
    PreparedPureProgramKind kind;
    bool entry_arguments_are_values;
    bool total_structural_equality;
    bool declined;
    PreparedPureRefusalInquiry inquiry;
} PreparedPureDeclineSlot;

enum { PREPARED_PURE_DECLINE_SLOTS = 64u };

/* Compiled entry programs are invocation-local executable metadata.  The
 * owning evaluator guarantees root_space remains live until this cache is
 * destroyed; restricting reuse to that root avoids retaining temporary
 * transaction/with-space objects without a lifetime lease. */
struct PreparedPureProgramCache {
    PreparedPureCacheEntry *entries;
    /* Advanced by every change to `entries`; decline answers remembered
     * under an older generation are not read. */
    uint64_t entry_generation;
    PreparedPureDeclineSlot decline_slots[PREPARED_PURE_DECLINE_SLOTS];
    Space *root_space;
    /* What compiled entries read besides the program: the libraries the
     * session imported (a pattern module makes its operations callable),
     * the language and its profile.  A program that would read the
     * registry's bindings is declined, so the registry is no key. */
    SpaceProgramToken program;
    uint64_t capability_revision;
    CettaLibraryMask library_mask;
    const CettaProfile *profile;
    CettaLanguageId language;
    Arena execution_scratch;
    bool execution_scratch_ready;
    bool answer_collection_budget_declined;
    /* Only construction decisions are retained, never effectful answers.
     * Bodies are closed over the actual environment and owned here. */
    struct {
        Atom *body;
        CettaLanguageId language;
        const CettaProfile *profile;
        CettaLibraryMask library_mask;
        bool safe;
    } replay[64];
    size_t replay_len;
    Arena replay_storage;
    bool replay_storage_ready;
};


static void prepared_pure_program_cache_clear_entries(
    PreparedPureProgramCache *cache) {
    if (!cache)
        return;
    PreparedPureCacheEntry *entry = cache->entries;
    while (entry) {
        PreparedPureCacheEntry *next = entry->next;
        cetta_prepared_pure_program_free(entry->program);
        free(entry);
        entry = next;
    }
    cache->entries = NULL;
    cache->entry_generation++;
    cache->replay_len = 0u;
    if (cache->replay_storage_ready) {
        arena_free(&cache->replay_storage);
        cache->replay_storage_ready = false;
    }
}

static void prepared_pure_program_cache_free(
    PreparedPureProgramCache *cache) {
    if (!cache)
        return;
    prepared_pure_program_cache_clear_entries(cache);
    if (cache->execution_scratch_ready) {
        arena_free(&cache->execution_scratch);
        cache->execution_scratch_ready = false;
    }
    cache->root_space = NULL;
    memset(&cache->program, 0, sizeof(cache->program));
    cache->capability_revision = 0u;
    cache->library_mask = 0u;
    cache->profile = NULL;
}

static void prepared_pure_program_cache_destroy(PreparedPureProgramCache *cache) {
    prepared_pure_program_cache_free(cache);
    free(cache);
}

static PreparedPureProgramCache *eval_execution_prepared_cache(void) {
    EvalExecutionContext *context = g_eval_execution;
    if (!context || !context->scoped)
        return NULL;
    if (!context->prepared) {
        context->prepared = cetta_malloc(sizeof(*context->prepared));
        *context->prepared = (PreparedPureProgramCache){
            .root_space = context->root_space,
        };
    }
    return context->prepared;
}

static Arena *prepared_pure_program_cache_execution_scratch(
        PreparedPureProgramCache *cache) {
    if (!cache)
        return NULL;
    if (!cache->execution_scratch_ready) {
        arena_init(&cache->execution_scratch);
        arena_set_hashcons(&cache->execution_scratch, NULL);
        arena_set_runtime_kind(
            &cache->execution_scratch,
            CETTA_ARENA_RUNTIME_KIND_SCRATCH);
        /* The prepared machine yields a boolean or small integer at most
         * scalar steps; share them within each reset epoch. */
        arena_set_scalar_cache(&cache->execution_scratch, true);
        cache->execution_scratch_ready = true;
    }
    return &cache->execution_scratch;
}

static bool prepared_pure_program_cache_prepare_revision(
    PreparedPureProgramCache *cache, Space *space,
    uint64_t capability_revision) {
    if (!cache || !space || cache->root_space != space)
        return false;
    uint32_t library_mask = g_library_context ? g_library_context->active_mask : 0u;
    const CettaProfile *profile = active_profile();
    CettaLanguageId language = eval_current_language_id();
    if (space_program_token_matches_live_space(
            cache->program, space) &&
        cache->capability_revision == capability_revision &&
        cache->library_mask == library_mask && cache->profile == profile &&
        cache->language == language)
        return true;
    prepared_pure_program_cache_clear_entries(cache);
    cache->program = space_program_token(space);
    cache->capability_revision = capability_revision;
    cache->library_mask = library_mask;
    cache->profile = profile;
    cache->language = language;
    return cache->program.instance_id != 0u;
}


/* This bounds optimization metadata, not program admission. Larger keys
 * use the ordinary check without retaining copies of captured data. */
static bool prepared_collection_small_replay_key(Atom *body) {
    Atom *pending[128];
    size_t length = 1u, nodes = 0u, bytes = 0u;
    pending[0] = body;
    while (length) {
        Atom *value = pending[--length];
        if (!value || ++nodes > 128u) return false;
        if (value->kind == ATOM_GROUNDED && value->ground.gkind == GV_STRING) {
            size_t size = atom_string_len(value);
            if (size > 4096u - bytes) return false;
            bytes += size;
        }
        if (value->kind == ATOM_EXPR) {
            if (value->expr.len > 128u - length) return false;
            for (CettaExprIndex i = 0u; i < value->expr.len; i++)
                pending[length++] = value->expr.elems[i];
        }
    }
    return true;
}

static bool prepared_collection_cached_replay_safe(
        Space *space, Atom *body, PreparedUnaryCollectionKind kind) {
    CettaLanguageId language = eval_current_language_id();
    /* Minimal HE callbacks may borrow no library profile. NULL is a valid,
     * distinct preparation dependency, not an implicit default profile. */
    const CettaProfile *profile = active_profile();
    CettaLibraryMask library_mask = g_library_context ? g_library_context->active_mask : 0u;
    PreparedPureProgramCache *cache = eval_execution_prepared_cache();
    uint64_t capabilities = language == CETTA_LANGUAGE_PETTA && g_library_context
        ? petta_libpl_capability_revision(g_library_context->lib_prolog) : 0u;
    if (!prepared_pure_program_cache_prepare_revision(cache, space, capabilities))
        cache = NULL;
    if (cache && !prepared_collection_small_replay_key(body)) cache = NULL;
    if (cache) {
        for (size_t i = 0; i < cache->replay_len; i++)
            if (cache->replay[i].language == language &&
                cache->replay[i].profile == profile &&
                cache->replay[i].library_mask == library_mask &&
                /* Replay safety observes variable roles, not fresh names;
                 * alpha-equivalence does not license answer memoization. */
                atom_alpha_eq(cache->replay[i].body, body)) {
                prepared_unary_collection_count(
                    kind, PREPARED_UNARY_SAFETY_REUSE);
                return cache->replay[i].safe;
            }
    }
    PreparedFoldSafety safety = {.space = space, .read = space_read_token(space)};
    prepared_unary_collection_count(kind, PREPARED_UNARY_SAFETY_CHECK);
    bool safe = prepared_fold_expression_replay_safe(&safety, body, NULL);
    bool current = space_read_token_is_current(safety.read);
    free(safety.heads);
    if (cache && current) {
        /* A bounded invocation-local cache. Reset all owned keys rather
         * than leave evicted bodies retaining handles until teardown. */
        if (cache->replay_len == 64u) {
            arena_free(&cache->replay_storage);
            cache->replay_storage_ready = false;
            cache->replay_len = 0u;
        }
        if (!cache->replay_storage_ready) {
            arena_init(&cache->replay_storage);
            arena_set_hashcons(&cache->replay_storage, NULL);
            cache->replay_storage_ready = true;
        }
        Atom *key = atom_deep_copy(&cache->replay_storage, body);
        if (key) {
            size_t index = cache->replay_len++;
            cache->replay[index].body = key;
            cache->replay[index].language = language;
            cache->replay[index].profile = profile;
            cache->replay[index].library_mask = library_mask;
            cache->replay[index].safe = safe;
        }
    }
    return safe && current;
}

