typedef struct PrimeEvalStackFrame {
    CettaOwnedFrameLink continuation;
    /* The native agenda retains a consumer while any producer can still
     * publish into it.  This graph is separate from the active C invocation
     * chain; shared return obligations are not copied into each alternative. */
    struct PrimeEvalStackFrame *control_next;
    struct PrimeEvalStackFrame *control_previous;
    struct PrimeEvalStackFrame *control_parent;
    size_t control_pending;
    /* Registration order. A scan visits changed frames newest first, the
     * order of the registered frame list. */
    uint64_t control_sequence;
    bool control_queued;
    bool control_closed;
    bool control_notified;
    bool control_changed;
    bool control_retired;
    /* Registered frames whose parent, continuation or stream-consumer link
     * names this frame and which are still allocated.  A retired frame that
     * no such link names can be freed (prime_native_control_reclaim). */
    size_t control_shell_refs;
    /* Within a scorer's return graph: no source answer or consumer
     * obligation. Fixed at registration with the parent link. */
    bool control_advisory;
    bool control_force_stream;
    /* The initial task of a FORCE can move once. Its return graph continues
     * owning the producer and every waiting equation/normalization frame. */
    bool control_force_detached;
    Atom *control_key;
    Atom *control_bound;
    PrimeNativeAdvice *control_advice;
    Atom **control_child_bounds;
    size_t control_child_bound_length;
    size_t control_child_bound_capacity;
    PrimeNativeControl *control_nested;
    PrimeNativeAcquiredOperation *control_nested_operation;
    CettaSearchPolicySpec control_nested_policy;
    uint64_t control_nested_budget;
    uint64_t control_nested_handle;
    bool control_nested_retained;
    bool control_nested_parked;
    bool control_scoring;
    uint64_t control_generation;
    size_t *control_selection;
    size_t control_selection_length;
    NativeDialectWork *dialect_source;
    bool dialect_source_success;
    bool dialect_source_is_call;
    CettaCount dialect_error_index;
    PrimeNativeReturnAdvice *control_return_advice;
    size_t control_return_advice_capacity;
    size_t control_return_advice_length;
    /* A synchronous producer can append rows before sidecar allocation is
     * attempted. Refusal retains the exact producing context for the whole
     * missing interval; a later scan must not substitute its ambient advice. */
    PrimeNativeReturnAdvice control_return_pending_advice;
    size_t control_return_pending_begin;
    size_t control_return_pending_end;
    bool control_return_pending;
    PrimeEvalStackFrameKind kind;
    bool ordinary_ordered;
    bool pure_authority;
    PrimeEvalStackFrameState state;
    Space *space;
    Arena *arena;
    OutcomeSet *target;
    /* Dynamic scope and execution ancestry are distinct: a consumer can
     * schedule work while another scope's producer is still on the stack. */
    PrimeEvalContext *context;
    Atom *atom;
    Atom *etype;
    int fuel;
    bool preserve_bindings;
    Bindings env;
    bool env_initialized;
    OutcomeSet child;
    bool child_initialized;
    /* One completed FORCE row, retained until observation and delivery both
     * commit. The raw child remains available to qualified waiters. */
    OutcomeSet force_pending;
    bool force_pending_initialized;
    bool force_pending_observed;
    bool force_published;
    bool force_retry_pending;
    CettaCount index;
    uint32_t branch_index;
    bool variable_branches_active;

    PrimeNeedEquationContinuation *equation_search;
    PrimeCapsuleSearch *capsule_search;
    PrimeMatchRows *match_rows;
    PrimeNativeService *native_service;
    PrimeNeedCallForceReader *call_force_reader;

    Atom **normalization_children;
    size_t normalization_child_count;
    CettaExprIndex normalization_child_index;
    bool normalization_value_ready;
    CettaCallResultForm normalization_result_form;
    /* A completed CALL returns a value head. Its observer must still force
     * embedded Need references without applying that head as new source. */
    bool normalization_return_value_ready;
    /* The children are evaluated as a tuple's elements, each to its values,
     * rather than normalized; the result is published as a call's. */
    bool tuple_bind;

    int strict_argument;
    PrimeNeedArgumentMode strict_mode;
    bool strict_error_is_data;
    Atom *strict_source;

    Atom *then_branch;
    Atom *else_branch;

    Atom *weight_subject;
    Atom *weight_algebra;
    Atom *weight_trace;
    size_t weight_index;
    uint64_t weight_dependency;
    /* The paid return and both complete worlds remain owned when two
     * incomparable observations claim one production. This is not failure
     * of matching, and repeated grants must not poll or discard it. */
    bool weight_ownership_parked;

    /* Force capability, or the defined symbol whose alternative right sides
     * are being produced by an ALTERNATIVES frame. Both are traced roots. */
    Atom *ref;
    uint64_t thunk_id;
    /* Set by the actual direct named demand, before its child can return. */
    uint64_t value_producer_thunk;
    PrimeNeedCellView cell;
    PrimeNeedSnapshot before;
    PrimeNeedSnapshot evaluating;
#if CETTA_BUILD_WITH_PRIME_CAUSAL_RECEIPTS
    /* The producer starts in the force origin. Both uses share this value;
     * the captured lexical environment may carry a different receipt. */
    PrimeNeedReceipt before_receipt;
#endif
    Arena *heap_owner;
    uint64_t previous_evaluator_id;
    uint64_t evaluator_id;
    bool source_argument_universal_demand;
    /* A worker is waiting on another worker's extension of this thunk.
     * The frame does not start a second evaluation. */
    bool shared_need_wait;
    struct PrimeEvalStackFrame *force_waiters;
    struct PrimeEvalStackFrame *force_waiter_next;
    struct PrimeEvalStackFrame *force_producer;
    struct PrimeEvalStackFrame *open_force_next;
    bool force_empty_lexical_env;
    SpaceReadToken force_source_read;

    /* In a streaming run: how many values of `child` a relaying frame has
     * already passed to its target, and, for a STREAM_RESUME frame, the
     * frame whose remaining values it goes on consuming. */
    CettaCount stream_forwarded;
    struct PrimeEvalStackFrame *stream_consumer;
} PrimeEvalStackFrame;

static void prime_need_call_force_reader_free(PrimeNeedCallForceReader *reader);
static void prime_need_call_force_resume(PrimeEvalStackFrame *frame);

/* Lexical projection has no occurrence carrier. Install the evaluating
 * context once, without importing the lexical origin's diary. */
static void prime_eval_stack_prepare_force_plain(const PrimeEvalStackFrame *frame,
    const Bindings *caller, Bindings *environment) {
    *bindings_need_mut(environment) = frame->evaluating;
    if (caller && caller->prime_ext) {
        environment->prime_ext->branch_state = caller->prime_ext->branch_state;
        environment->prime_ext->weights = caller->prime_ext->weights;
        environment->prime_ext->occurrence_token = caller->prime_ext->occurrence_token;
    }
    bindings_reader_context_set(environment,bindings_reader_context_view(caller));
}

/* Frame construction already initializes empty storage. A plain origin
 * captures the operational heap without reading absent history. */
static PrimeNeedForceEnvironmentPrepare prime_eval_stack_capture_force_plain(
    PrimeEvalStackFrame *frame) {
    frame->before = g_prime_need_active;
    return prime_eval_stack_prepare_force_plain;
}

#if CETTA_BUILD_WITH_PRIME_CAUSAL_RECEIPTS
static void prime_eval_stack_prepare_force_carried(const PrimeEvalStackFrame *frame,
    const Bindings *caller, Bindings *environment) {
    prime_eval_stack_prepare_force_plain(frame, caller, environment);
    *bindings_receipt_mut(environment) = frame->before_receipt;
}

static PrimeNeedForceEnvironmentPrepare prime_eval_stack_capture_force_carried(
    PrimeEvalStackFrame *frame) {
    (void)prime_eval_stack_capture_force_plain(frame);
    frame->before_receipt = g_prime_need_receipt_active;
    return prime_eval_stack_prepare_force_carried;
}
#endif

