typedef struct {
    PrimeEvalStackTaskKind kind;
    PrimeEvalContext *context;
    bool pure_authority;
    Space *space;
    Arena *arena;
    Atom *atom;
    Atom *etype;
    int fuel;
    bool preserve_bindings;
    int strict_ready_argument;
    OutcomeSet *target;
    Bindings dynamic_env;
    bool dynamic_env_initialized;
    /* A call retained at its actual refusal boundary owns one complete
     * environment. Reuse that same carrier as the resumed call's seed;
     * duplicating it solely to represent the two evaluator views would add
     * an allocation-failure hole after a paid prefix. */
    bool dynamic_env_is_seed;
    Bindings seed_env;
    bool seed_env_initialized;
    uint64_t evaluator_id;
    Atom *control_key;
    bool control_scoring;
} PrimeEvalStackTask;

typedef struct PrimeEvalStackDriver {
    PrimeEvalStackFrame *top;
    PrimeNativeControl *control;
    /* A nested owned continuation borrows the enclosing call authority.
     * Its lifetime is contained in that owner; this is not a control owner. */
    struct PrimeEvalStackDriver *authority_parent;
    void (*observe_space_read)(void *context,SpaceReadToken read);
    void *space_read_context;
    bool (*observe_context_read)(void *context,Space *program,SymbolId name,Space *space);
    void *context_read_context;
    /* A resident computation's execution guard follows only its own
     * authenticated data publications, never an external revision. */
    SpaceReadToken *own_data_read;
    void (*own_data_published)(void *context,Space *target,
        uint64_t revision_before,uint64_t prefix_before);
    void *own_data_context;
    /* A child borrows this service protocol until its containing search is
     * released. Authority and service progress are independent checks. */
    PettaMachineOperationPermit call_permit;
    void *call_permit_context;
    /* A retained resident call reports a refusal to its shared producer.
     * Generation distinguishes a refusal already counted by call_permit
     * from an authority refusal which short-circuited before that permit. */
    uint64_t (*call_refusal_generation)(void *context);
    void (*call_refusal_retained)(void *context,CettaEvalCompletion reason);
    void *call_refusal_context;
    /* Synchronous nested runs borrow only the service protocol, without
     * changing their world/read or grant ancestry. */
    struct PrimeEvalStackDriver *call_permit_parent;
    bool (*normalization_value_role)(void *,Atom *,Atom *,const Bindings *,bool *);
    void *normalization_role_context;
    bool ordinary_ordered;
    bool ordinary_shared_source;
    bool ordinary_ready_queue;
    bool ordinary_refill;
    bool ordinary_descendants;
    /* Execution authority stays in control; this flag selects only the
     * exclusive owned stack instead of the indexed ready-work graph. */
    bool capsule_stack;
    bool capsule_frontier;
    /* Opaque prepared roots retain this arena through the live serial call.
     * Collection requires a separate visitor before these roots may move. */
    size_t prepared_opaque_frames;
    CettaOwnedFrameStack continuations;
    PrimeEvalStackTask task;
    PrimeEvalStackTask *active_task;
    bool task_ready;
    Arena *arena;
    ArenaMark gc_anchor;
    OutcomeSet *root_target;
    /* The root of an internal service can request only its produced head.
     * Ordinary public roots retain their full-observation contract. */
    bool root_weak_head;
    uint32_t raw_call_depth;
    uint32_t bind_depth;
    uint32_t poison_depth;
    bool running_bind_task;
    bool retain_bind_calls;
    bool pure_authority;
    bool running_task;
    bool heap_phase;
    bool collection_admitted;
    bool failed;
    bool capacity_blocked;
    bool ownership_parked;
    /* The run streams: a value a frame publishes is consumed by the frame
     * waiting for it before the producer computes its next alternative, so
     * only the work that leads to the outcomes taken is done and each effect
     * on the way runs once. */
    bool streaming;
    /* A streaming run that observes only a prefix of its root call's
     * outcomes ends once the root target holds this many; zero when the run
     * is not ended by its root's outcomes (an ordinary run, or one whose
     * controller decides). */
    uint64_t answer_limit;
    /* Started for a bounded observation inside another run, whose frames
     * are not this run's roots: this run never collects. */
    bool nested;
    /* The target a frame just published into, consumed at the next step. */
    OutcomeSet *stream_pending;
    /* The root call itself is running, before any task: its tail loop may
     * collect as a task's does. */
    bool root_call_running;
    size_t frame_depth;
    size_t gc_survivor_floor_bytes;
    uint64_t continuation_generation;
    PreparedPureProgramCache prepared_pure_cache;
} PrimeEvalStackDriver;

typedef struct {
    PrimeEvalStackDriver *driver;
    bool active;
} PrimeEvalStackCallGuard;

static __thread PrimeEvalStackDriver *g_prime_eval_stack_driver = NULL;

typedef struct {
    EvalContextState previous;
    PrimeEvalContext *previous_scope,*entered;
    bool active;
} PrimeEvalContextGuard;

static PrimeEvalContextGuard prime_eval_stack_context_enter(
    PrimeEvalContext *context) {
    if (!context && !g_prime_eval_context) return (PrimeEvalContextGuard){0};
    PrimeEvalContextGuard guard={.previous=eval_context_capture(),
        .previous_scope=g_prime_eval_context,.entered=context,.active=true};
    prime_eval_context_retain(context);
    if (context) eval_context_restore(&context->value);
    else {
        PrimeEvalContext *root=g_prime_eval_context;
        while(root->parent) root=root->parent;
        eval_context_restore(&root->entrance);
    }
    g_prime_eval_context=context;
    return guard;
}

/* A separately owned resident already captures its complete base context.
 * Its root must not inherit the receiving driver's active scope identity. */
static PrimeEvalContextGuard prime_eval_stack_context_detach(void) {
    PrimeEvalContextGuard guard={.previous=eval_context_capture(),
        .previous_scope=g_prime_eval_context,.active=true};
    g_prime_eval_context=NULL;
    return guard;
}

static void prime_eval_stack_context_leave(PrimeEvalContextGuard *guard) {
    if (!guard->active) return;
    eval_context_restore(&guard->previous);
    g_prime_eval_context=guard->previous_scope;
    prime_eval_context_release(guard->entered);
}
/* A synchronous host invocation can open an independent top-level episode.
 * Its return storage is not part of the suspended caller's task stack, but
 * the caller still owns the surrounding lifetime and execution authority. */
static __thread PrimeEvalStackDriver *g_prime_eval_top_authority = NULL;

typedef struct PrimeEvalTopGuard {
    PrimeEvalStackDriver *driver;
    PrimeEvalStackDriver *authority;
    struct PrimeEvalTopGuard *previous;
} PrimeEvalTopGuard;
static __thread PrimeEvalTopGuard *g_prime_eval_top_scopes = NULL;

static void prime_eval_top_enter(PrimeEvalTopGuard *saved) {
    *saved = (PrimeEvalTopGuard){g_prime_eval_stack_driver,
        g_prime_eval_top_authority, g_prime_eval_top_scopes};
    if (g_prime_eval_stack_driver)
        g_prime_eval_top_authority = g_prime_eval_stack_driver;
    g_prime_eval_top_scopes = saved;
    g_prime_eval_stack_driver = NULL;
}

static void prime_eval_top_leave(PrimeEvalTopGuard *saved) {
    g_prime_eval_stack_driver = saved->driver;
    g_prime_eval_top_authority = saved->authority;
    g_prime_eval_top_scopes = saved->previous;
}

static PrimeEvalStackDriver *prime_eval_authority_driver(void) {
    return g_prime_eval_stack_driver ? g_prime_eval_stack_driver
                                     : g_prime_eval_top_authority;
}

/* An inline observation may renew its quantum only when it is outermost:
 * no enclosing budget bounds its steps, and no enclosing native control
 * interleaves it with siblings that would wait while it runs. */
static bool prime_inline_quantum_may_renew(void) {
    for (const CettaEvalEpisode *tracker = g_eval_completion_tracker;
         tracker; tracker = tracker->parent)
        if (tracker->budget_limited)
            return false;
    for (const PrimeEvalStackDriver *driver = prime_eval_authority_driver();
         driver; driver = driver->authority_parent)
        if (driver->control)
            return false;
    return true;
}

/* Whether a frame of an inline observation's stack still holds an untried
 * alternative: a value of its child not yet taken, or a branch, equation
 * or row not yet started.  A kind not listed is taken to hold one. */
static bool prime_eval_stack_frame_holds_alternative(
        const PrimeEvalStackFrame *frame) {
    bool untaken = frame->child_initialized && frame->index < frame->child.len;
    if (frame->call_force_reader) return true;
    switch (frame->kind) {
    case PRIME_EVAL_STACK_FRAME_STRICT:
        /* Waiting for the call made with its only value. */
        return frame->state != PRIME_EVAL_STACK_FRAME_WAIT_CALL && untaken;
    case PRIME_EVAL_STACK_FRAME_IF:
        if (frame->state == PRIME_EVAL_STACK_FRAME_WAIT_CALL)
            return false;
        return untaken || (frame->variable_branches_active &&
                           frame->branch_index < 2u);
    case PRIME_EVAL_STACK_FRAME_LET:
    case PRIME_EVAL_STACK_FRAME_FORCE:
    case PRIME_EVAL_STACK_FRAME_NORMALIZE_ATOM:
    case PRIME_EVAL_STACK_FRAME_NORMALIZE_CHILDREN:
        return untaken;
    case PRIME_EVAL_STACK_FRAME_BIND_FINISH:
        return frame->child_initialized &&
            frame->stream_forwarded < frame->child.len;
    case PRIME_EVAL_STACK_FRAME_EQUATION_SEARCH: {
        /* Only a search that is running its last body holds nothing more:
         * deciding which equations apply, or forcing an argument to decide
         * it, keeps the other equations waiting. */
        const PrimeNeedEquationContinuation *search = frame->equation_search;
        return !search ||
            search->state != PRIME_NEED_EQUATION_SEARCH_WAIT_PUBLICATION ||
            search->publication_index < search->publication.len ||
            search->residuals.len != 0u ||
            (frame->child_initialized &&
             frame->stream_forwarded < frame->child.len);
    }
    case PRIME_EVAL_STACK_FRAME_CHOICE: {
        /* The cursor counts the elements of the branch list's sequence
         * view, as prime_eval_stack_resume_choice reads them. */
        Atom *list = frame->atom ? expr_arg(frame->atom, 0u) : NULL;
        Atom *const *branches = NULL;
        CettaExprLen branch_len = 0u;
        return !list || !atom_sequence_view(list, &branches, &branch_len) ||
            frame->index < branch_len;
    }
    default:
        return true;
    }
}

/* Renew an outermost inline observation's quantum when no alternative
 * waits.  The quantum bounds how long depth-first descent runs while some
 * other alternative waits (prime_inline_quantum_visit); a run whose stack
 * holds no untried alternative starves nothing, so it is not charged.  Only
 * the observation's own driver is inspected, at a point where no host frame
 * holds an alternative of its own: between two tasks, or at the step of a
 * call the driver made directly (the observed call, or a call task).  A scan
 * that finds an alternative waiting is not repeated for a while; the renewed
 * quantum covers at least twice the frames scanned. */
static void prime_inline_quantum_renew(
        PrimeEvalStackDriver *driver, bool between_tasks) {
    CettaEvalEpisode *tracker = g_eval_completion_tracker;
    if (!tracker || !driver || !tracker->observation || !tracker->observation->renew_quantum ||
        tracker->observation->renew_driver != driver ||
        tracker->budget_remaining >
            tracker->observation->renew_quantum / 2u + tracker->observation->renew_cushion ||
        tracker->steps_spent < tracker->observation->renew_next_scan ||
        tracker->interrupted ||
        tracker->completion != CETTA_EVAL_COMPLETE)
        return;
    if (between_tasks
            ? driver->raw_call_depth != 0u || driver->running_task ||
              driver->root_call_running
            : driver->raw_call_depth != 1u || driver->task_ready ||
              !(driver->root_call_running ||
                (driver->running_task && driver->active_task &&
                 driver->active_task->kind == PRIME_EVAL_STACK_TASK_CALL)))
        return;
    if (driver->answer_limit != 0u &&
        (uint64_t)driver->root_target->len >= driver->answer_limit)
        return;
    uint64_t frames = 0u;
    for (const PrimeEvalStackFrame *frame = driver->top; frame;
         frame = (const PrimeEvalStackFrame *)frame->continuation.next) {
        frames++;
        if (prime_eval_stack_frame_holds_alternative(frame)) {
            tracker->observation->renew_next_scan = tracker->steps_spent +
                (frames > UINT64_C(64) ? frames : UINT64_C(64));
            return;
        }
    }
    tracker->budget_remaining = (frames > tracker->observation->renew_quantum / 2u
        ? 2u * frames : tracker->observation->renew_quantum) + tracker->observation->renew_cushion;
}

static bool prime_inline_quantum_alternative_waits(
        const CettaEvalEpisode *tracker,
        const CettaEvalEpisode *quantum) {
    PrimeEvalStackDriver *driver = g_prime_eval_stack_driver;
    if (!tracker || !quantum || tracker != quantum ||
        !tracker->observation || !tracker->observation->renew_quantum || !driver ||
        tracker->observation->renew_driver != driver ||
        tracker->interrupted ||
        tracker->completion != CETTA_EVAL_COMPLETE)
        return true;
    if (driver->raw_call_depth != 1u || driver->task_ready ||
        !(driver->root_call_running ||
          (driver->running_task && driver->active_task &&
           driver->active_task->kind == PRIME_EVAL_STACK_TASK_CALL)))
        return true;
    for (const PrimeEvalStackFrame *frame = driver->top; frame;
         frame = (const PrimeEvalStackFrame *)frame->continuation.next)
        if (prime_eval_stack_frame_holds_alternative(frame))
            return true;
    return false;
}

