/* A suspended continuation may publish only into the root result or an
 * OutcomeSet physically owned by an active heap frame.  Native-stack result
 * sets are deliberately rejected: their caller may return before the
 * continuation resumes. */
static bool prime_eval_stack_target_is_owned(const OutcomeSet *target) {
    PrimeEvalStackDriver *driver = g_prime_eval_stack_driver;
    if (!driver || !target)
        return false;
    if (target == driver->root_target)
        return true;
    if (prime_eval_stack_queued(driver))
        return prime_native_control_target_owner(
            driver->control, target) != NULL;
    for (PrimeEvalStackFrame *frame = driver->top;
         frame; frame = (PrimeEvalStackFrame *)frame->continuation.next) {
        if (frame->child_initialized && target == &frame->child)
            return true;
    }
    return false;
}

static uint64_t prime_eval_stack_continuation_generation(void) {
    return g_prime_eval_stack_driver
        ? g_prime_eval_stack_driver->continuation_generation : 0u;
}

static void prime_eval_stack_call_enter(PrimeEvalStackCallGuard *guard) {
    guard->driver = g_prime_eval_stack_driver;
    guard->active = guard->driver != NULL;
    if (guard->active)
        guard->driver->raw_call_depth++;
}

static void prime_eval_stack_call_leave(PrimeEvalStackCallGuard *guard) {
    if (!guard || !guard->active)
        return;
    assert(guard->driver != NULL);
    assert(guard->driver->raw_call_depth > 0u);
    guard->driver->raw_call_depth--;
    guard->active = false;
}

static void prime_eval_stack_bind_enter(PrimeEvalStackBindGuard *guard) {
    if (!guard)
        return;
    guard->active = g_prime_eval_stack_driver != NULL &&
                    g_prime_eval_stack_driver->running_bind_task;
    if (guard->active)
        g_prime_eval_stack_driver->bind_depth++;
}

static void prime_eval_stack_bind_leave(PrimeEvalStackBindGuard *guard) {
    if (!guard || !guard->active)
        return;
    assert(g_prime_eval_stack_driver != NULL);
    assert(g_prime_eval_stack_driver->bind_depth > 0u);
    g_prime_eval_stack_driver->bind_depth--;
    guard->active = false;
}

static bool prime_eval_stack_bind_force_admitted(void) {
    return g_prime_eval_stack_driver != NULL &&
           g_prime_eval_stack_driver->poison_depth == 0u &&
           g_prime_eval_stack_driver->running_bind_task &&
           g_prime_eval_stack_driver->bind_depth == 1u;
}

/* Record the selected producer at the ordinary bind dispatch. A bind
 * completion is the only transparent relay here; pattern demands or other
 * enclosing computations do not make their caller a direct return owner.
 * Keeping dispatch in its task preserves the existing force admission. */
static void prime_eval_stack_record_named_return(
    const OutcomeSet *target, uint64_t producer) {
    PrimeEvalStackDriver *driver = g_prime_eval_stack_driver;
    if (!driver || !producer || !target)
        return;
    size_t remaining = driver->frame_depth;
    while (remaining-- && target != driver->root_target) {
        PrimeEvalStackFrame *owner = NULL;
        if (prime_eval_stack_queued(driver))
            owner = prime_native_control_target_owner(driver->control, target);
        else for (PrimeEvalStackFrame *frame = driver->top; frame;
                  frame = (PrimeEvalStackFrame *)frame->continuation.next)
            if (frame->child_initialized && target == &frame->child) {
                owner = frame;
                break;
            }
        if (!owner)
            return;
        if (owner->kind == PRIME_EVAL_STACK_FRAME_FORCE) {
            owner->value_producer_thunk = producer;
            return;
        }
        if (owner->kind != PRIME_EVAL_STACK_FRAME_BIND_FINISH)
            return;
        target = owner->target;
    }
}

static bool prime_eval_stack_target_weak_head(const OutcomeSet *target) {
    PrimeEvalStackDriver *driver = g_prime_eval_stack_driver;
    if (!driver || !target) return false;
    size_t remaining = driver->frame_depth;
    /* A forwarded target belongs to a frame below the frame that forwards
     * it, so each search continues below the owner found last: one pass over
     * the stack, not one per level.  An owner above it is still found. */
    PrimeEvalStackFrame *below = driver->top;
    for (;;) {
        if (target == driver->root_target) return driver->root_weak_head;
        if (!remaining--) return false;
        PrimeEvalStackFrame *owner = NULL;
        if (prime_eval_stack_queued(driver)) {
            owner = prime_native_control_target_owner(driver->control, target);
        } else {
            for (PrimeEvalStackFrame *frame = below; frame;
                 frame = (PrimeEvalStackFrame *)frame->continuation.next)
                if (frame->child_initialized && target == &frame->child) {
                    owner = frame;
                    break;
                }
            for (PrimeEvalStackFrame *frame = driver->top;
                 !owner && frame && frame != below;
                 frame = (PrimeEvalStackFrame *)frame->continuation.next)
                if (frame->child_initialized && target == &frame->child)
                    owner = frame;
            if (owner)
                below = (PrimeEvalStackFrame *)owner->continuation.next;
        }
        if (!owner) return false;
        if (owner->kind == PRIME_EVAL_STACK_FRAME_FORCE) return true;
        if (owner->kind == PRIME_EVAL_STACK_FRAME_EQUATION_SEARCH &&
            owner->equation_search && owner->equation_search->inspect_incrementally &&
            owner->equation_search->state == PRIME_NEED_EQUATION_SEARCH_WAIT_FORCE)
            return owner->equation_search->inspection.demand == PRIME_NEED_PATTERN_WEAK_HEAD;
        if (owner->kind == PRIME_EVAL_STACK_FRAME_NORMALIZE_ATOM &&
            owner->state == PRIME_EVAL_STACK_FRAME_WAIT_CALL &&
            !owner->normalization_return_value_ready) return true;
        /* Binding completion and a named RHS relay forward the value; their
         * receiver determines whether production alone suffices. This does
         * not forward a named producer identity across several RHSs. Tuple
         * and let bindings do not promise a later structural observer. */
        if (owner->kind == PRIME_EVAL_STACK_FRAME_BIND_FINISH ||
            (owner->kind == PRIME_EVAL_STACK_FRAME_ALTERNATIVES && owner->ref)) {
            target = owner->target; continue;
        }
        if (owner->kind == PRIME_EVAL_STACK_FRAME_EQUATION_SEARCH &&
            owner->equation_search && owner->equation_search->state ==
                PRIME_NEED_EQUATION_SEARCH_WAIT_PUBLICATION) {
            target = owner->target; continue;
        }
        if (owner->kind == PRIME_EVAL_STACK_FRAME_CAPSULE_SEARCH) {
            target = owner->target; continue;
        }
        return false;
    }
}


typedef enum {
    PRIME_PUBLIC_VERDICT_INVALID = 0,
    PRIME_PUBLIC_VERDICT_ESTABLISHED,
    PRIME_PUBLIC_VERDICT_REFUTED,
    PRIME_PUBLIC_VERDICT_UNDETERMINED,
    PRIME_PUBLIC_VERDICT_INCOMPLETE,
} PrimePublicVerdictStatus;

static bool prime_public_symbol_named(Atom *atom, const char *name) {
    const char *atom_name = atom && atom->kind == ATOM_SYMBOL
        ? atom_name_cstr(atom) : NULL;
    return atom_name && name && strcmp(atom_name, name) == 0;
}

static PrimePublicVerdictStatus prime_public_verdict_view(
    Atom *verdict, Atom **evidence_out) {
    if (evidence_out) *evidence_out = NULL;
    if (!verdict || verdict->kind != ATOM_EXPR || verdict->expr.len != 4u ||
        !prime_public_symbol_named(verdict->expr.elems[0], "PrimeVerdict"))
        return PRIME_PUBLIC_VERDICT_INVALID;
    Atom *evidence = verdict->expr.elems[3];
    if (evidence && evidence->kind == ATOM_EXPR && evidence->expr.len >= 2u &&
        prime_public_symbol_named(evidence->expr.elems[0], "PrimeEvidenceV1"))
        evidence = evidence->expr.elems[1];
    if (evidence_out) *evidence_out = evidence;
    Atom *status = verdict->expr.elems[1];
    if (prime_public_symbol_named(status, "Established"))
        return PRIME_PUBLIC_VERDICT_ESTABLISHED;
    if (prime_public_symbol_named(status, "Refuted"))
        return PRIME_PUBLIC_VERDICT_REFUTED;
    if (prime_public_symbol_named(status, "Undetermined"))
        return PRIME_PUBLIC_VERDICT_UNDETERMINED;
    if (prime_public_symbol_named(status, "Incomplete"))
        return PRIME_PUBLIC_VERDICT_INCOMPLETE;
    return PRIME_PUBLIC_VERDICT_INVALID;
}

static bool prime_public_native_check_evidence(Atom *evidence) {
    if (!evidence || evidence->kind != ATOM_EXPR || evidence->expr.len != 2u)
        return false;
    return prime_public_symbol_named(
               evidence->expr.elems[0], "PrimeRegularChecked") ||
           prime_public_symbol_named(
               evidence->expr.elems[0], "PrimeRegularDeclaredChecked");
}

/* Checked on the declared route: in a context of space declarations. */
static bool prime_public_declared_check_evidence(Atom *evidence) {
    return evidence && evidence->kind == ATOM_EXPR &&
           evidence->expr.len == 2u &&
           prime_public_symbol_named(
               evidence->expr.elems[0], "PrimeRegularDeclaredChecked");
}

static Atom *prime_public_bound_operand_syntax(
    Arena *arena, Atom *operand, const Bindings *environment);

static Atom *prime_public_applied_call(
    Arena *arena, Atom *call, const Bindings *environment) {
    return prime_public_bound_operand_syntax(arena, call, environment);
}

/* Type judgments already consume syntax as data.  A generated quotation
 * crosses that boundary only through the explicit staging redex
 * `unquote (quote term)`; bare quotations remain ordinary data. */
static Atom *prime_public_splice_type_operand(
    Arena *arena, Atom *operand) {
    if (!operand || operand->kind != ATOM_EXPR || operand->expr.len != 2u ||
        !atom_is_symbol_id(operand->expr.elems[0], g_builtin_syms.unquote)) {
        return operand;
    }
    Atom *quoted = operand->expr.elems[1];
    if (!quoted || quoted->kind != ATOM_EXPR || quoted->expr.len != 2u ||
        !atom_is_symbol_id(quoted->expr.elems[0], g_builtin_syms.quote)) {
        return operand;
    }
    Atom *spliced = cetta_prime_typed_boundary_splice_explicit_v1(
        arena, operand);
    return spliced ? spliced : operand;
}

static bool prime_public_positive_budget(Atom *atom, uint64_t *budget_out) {
    if (!atom || atom->kind != ATOM_GROUNDED ||
        atom->ground.gkind != GV_INT || atom->ground.ival <= 0)
        return false;
    if (budget_out) *budget_out = (uint64_t)atom->ground.ival;
    return true;
}

Space *prime_public_space_argument(Arena *arena, Atom *atom) {
    if (!atom) return NULL;
    Atom *value = prime_need_ready_syntax(arena, atom_prime_held_payload(atom),
        g_prime_need_logical_env);
    Atom *resolved = resolve_registry_refs(arena, atom_prime_held_payload(value));
    resolved = prime_need_ready_syntax(arena, resolved, g_prime_need_logical_env);
    resolved = atom_prime_held_payload(resolved);
    return resolve_registry_space_payload(g_registry, resolved);
}

/* Add a record that a scoped judgment published to its theory space and
 * admit it there, as the Prime readout does, for a dialect that reaches
 * the judgments through a module. */
bool eval_admit_scoped_record(Space *space, Arena *arena, Atom *record) {
    if (!space || !record ||
        !eval_admit_atom(space, arena, eval_storage_arena(arena), record))
        return false;
    prime_scoped_judgment_admit(arena, space, record);
    return true;
}

static Atom *prime_public_make_judgment(
    Arena *arena, SymbolId head_id, Atom *first, Atom *second) {
    const char *judgment_name = NULL;
    if (head_id == g_builtin_syms.type_colon_of)
        judgment_name = "type:of";
    else if (head_id == g_builtin_syms.type_colon_normalize)
        judgment_name = "type:normalize";
    else if (head_id == g_builtin_syms.type_colon_check)
        judgment_name = "type:check";
    else if (head_id == g_builtin_syms.type_colon_analyze)
        judgment_name = "type:analyze";
    else if (head_id == g_builtin_syms.type_colon_eq)
        judgment_name = "type:eq";
    else if (head_id == g_builtin_syms.type_colon_formed)
        judgment_name = "type:formed";
    else if (head_id == g_builtin_syms.type_colon_refine)
        judgment_name = "type:refine";
    else if (head_id == g_builtin_syms.type_colon_may)
        judgment_name = "type:may";
    else if (head_id == g_builtin_syms.type_colon_must)
        judgment_name = "type:must";
    if (!judgment_name) return NULL;
    if (head_id == g_builtin_syms.type_colon_may ||
        head_id == g_builtin_syms.type_colon_must) {
        first = atom_expr2(
            arena, atom_symbol(arena, "PrimeEvaluate"), first);
    }
    Atom *head = atom_symbol(arena, judgment_name);
    return second ? atom_expr3(arena, head, first, second)
                  : atom_expr2(arena, head, first);
}

static bool prime_public_is_type_query(SymbolId head_id) {
    return head_id == g_builtin_syms.type_colon_of ||
           head_id == g_builtin_syms.type_colon_normalize ||
           head_id == g_builtin_syms.type_colon_check ||
           head_id == g_builtin_syms.type_colon_analyze ||
           head_id == g_builtin_syms.type_colon_eq ||
           head_id == g_builtin_syms.type_colon_formed ||
           head_id == g_builtin_syms.type_colon_refine ||
           head_id == g_builtin_syms.type_colon_may ||
           head_id == g_builtin_syms.type_colon_must;
}

static bool prime_public_type_query_is_binary(SymbolId head_id) {
    return head_id == g_builtin_syms.type_colon_check ||
           head_id == g_builtin_syms.type_colon_analyze ||
           head_id == g_builtin_syms.type_colon_eq ||
           head_id == g_builtin_syms.type_colon_may ||
           head_id == g_builtin_syms.type_colon_must;
}

static Atom *prime_public_declaration_atom(
    Arena *arena, Atom *name, Atom *type) {
    return atom_expr3(
        arena, atom_symbol_id(arena, g_builtin_syms.colon), name, type);
}

static bool prime_public_declaration_compatible(
    Space *space, Arena *arena, Atom *name, Atom *type,
    bool *already_present_out) {
    if (already_present_out) *already_present_out = false;
    if (!space || !arena || !name || name->kind != ATOM_SYMBOL || !type)
        return false;
    Atom *canonical = prime_semantics_canonicalize_type(arena, type);
    if (!canonical || atom_has_vars(canonical)) return false;
    Atom **declared = NULL;
    uint32_t count = space_get_declared_types(
        space, arena, name, &declared);
    if (count == 0u) {
        free(declared);
        return true;
    }
    bool compatible = true;
    for (uint32_t i = 0u; i < count; i++) {
        Atom *prior = atom_has_vars(declared[i])
            ? NULL
            : prime_semantics_canonicalize_type(arena, declared[i]);
        if (!prior || !atom_eq(canonical, prior)) {
            compatible = false;
            break;
        }
    }
    free(declared);
    if (compatible && already_present_out) *already_present_out = true;
    return compatible;
}

static bool prime_public_publish_declaration(
    Space *space, Arena *arena, Atom *name, Atom *type) {
    if (prime_scoped_judgment_reserved_name(name)) return false;
    bool already_present = false;
    if (!prime_public_declaration_compatible(
            space, arena, name, type, &already_present))
        return false;
    if (already_present) return true;
    return eval_admit_atom(
        space, arena, eval_storage_arena(arena),
        prime_public_declaration_atom(arena, name, type));
}

static void prime_public_emit(
    Arena *arena, OutcomeSet *outcomes, Atom *value,
    const Bindings *current_env, bool preserve_bindings) {
    if (eval_unwinding()) return;
    Bindings empty;
    bindings_init(&empty);
    outcome_set_add_prefixed(
        arena, outcomes, value, &empty, current_env, preserve_bindings);
}

/* Native synthesis returns intrinsic terms.  Public `type:of` returns the
 * corresponding lower-case authored spelling so its answer can be fed back
 * to every `type:` operation without crossing an implementation vocabulary. */
static Atom *prime_public_authored_type(Arena *arena, Atom *intrinsic) {
    return cetta_prime_regular_term_quote_named_v1(arena, intrinsic);
}

/* The curried reading of a type: an arrow of several parameters is an arrow
 * of the first returning the arrow of the rest. */
static Atom *prime_he_curried_type(Arena *a, Atom *type) {
    if (!type || type->kind != ATOM_EXPR) return type;
    Atom **items = arena_alloc(a, sizeof(Atom *) * type->expr.len);
    for (CettaExprIndex i = 0u; i < type->expr.len; i++)
        items[i] = prime_he_curried_type(a, type->expr.elems[i]);
    if (type->expr.len > 3u && atom_is_symbol_id(items[0], g_builtin_syms.arrow)) {
        Atom *curried = items[type->expr.len - 1u];
        for (CettaExprIndex i = type->expr.len - 1u; i > 1u; i--)
            curried = atom_expr3(a, items[0], items[i - 1u], curried);
        return curried;
    }
    return atom_expr(a, items, type->expr.len);
}

/* What the native routes establish, in HE's flat form, or the HE reading
 * of the same declarations where it means the same type; no type where they
 * refute; the unknown type where they abstain. */
static uint32_t prime_get_type_native(Space *s, Arena *a, Atom *target,
                                      Atom *verdict, int fuel,
                                      Atom ***types_out) {
    Atom *evidence = NULL;
    PrimePublicVerdictStatus status = prime_public_verdict_view(verdict, &evidence);
    *types_out = NULL;
    if (status == PRIME_PUBLIC_VERDICT_REFUTED) return 0u;
    Atom *native = NULL;
    if (status == PRIME_PUBLIC_VERDICT_ESTABLISHED && evidence &&
        evidence->kind == ATOM_EXPR) {
        if (evidence->expr.len == 2u &&
            (prime_public_symbol_named(evidence->expr.elems[0],
                                       "PrimeRegularSynthesis") ||
             prime_public_symbol_named(evidence->expr.elems[0],
                                       "PrimeRegularDeclaredSynthesis")))
            native = prime_public_authored_type(a, evidence->expr.elems[1]);
        else if (evidence->expr.len == 4u &&
                 prime_public_symbol_named(evidence->expr.elems[0],
                                           "PrimeTypedQuery"))
            native = evidence->expr.elems[1];
    }
    Atom **types = cetta_malloc(sizeof(*types));
    *types_out = types;
    if (!native) {
        types[0] = atom_undefined_type(a);
        return 1u;
    }
    Atom *flat = prime_semantics_flat_named_term(a, native);
    if (!flat) flat = native;
    Atom **checked = NULL;
    uint32_t checked_count = 0u;
    eval_prime_judgment_enter();
    CettaPrimeHeTypeAnswer answer = cetta_prime_he_declaration_types(
        s, a, target, &checked, &checked_count);
    eval_prime_judgment_leave();
    if (answer == CETTA_PRIME_HE_TYPE_CHECKED && checked_count == 1u) {
        Atom *reading = prime_get_type_normalize(s, a, checked[0], fuel);
        if (atom_eq(prime_he_curried_type(a, reading),
                    prime_he_curried_type(a, flat)))
            flat = reading;
    }
    types[0] = flat;
    return 1u;
}

static void prime_public_emit_type_evidence(
    Arena *arena, OutcomeSet *outcomes, Atom *evidence, Atom *inert_call,
    const Bindings *current_env, bool preserve_bindings) {
    if (evidence && evidence->kind == ATOM_EXPR && evidence->expr.len == 2u &&
        (prime_public_symbol_named(
             evidence->expr.elems[0], "PrimeRegularSynthesis") ||
         prime_public_symbol_named(
             evidence->expr.elems[0], "PrimeRegularDeclaredSynthesis"))) {
        Atom *type = prime_public_authored_type(
            arena, evidence->expr.elems[1]);
        prime_public_emit(
            arena, outcomes, type ? type : inert_call, current_env,
            preserve_bindings);
        return;
    }
    /* A typed query's type is the type of its answers. */
    if (evidence && evidence->kind == ATOM_EXPR && evidence->expr.len == 4u &&
        prime_public_symbol_named(evidence->expr.elems[0], "PrimeTypedQuery")) {
        prime_public_emit(
            arena, outcomes, evidence->expr.elems[1], current_env,
            preserve_bindings);
        return;
    }
    if (evidence && evidence->kind == ATOM_EXPR && evidence->expr.len >= 3u &&
        prime_public_symbol_named(evidence->expr.elems[0], "InferredTypes")) {
        bool emitted = false;
        for (CettaExprIndex i = 3u; i < evidence->expr.len; i++) {
            if (atom_is_symbol_id(
                    evidence->expr.elems[i], g_builtin_syms.undefined_type))
                continue;
            /* HE-style types are authored as they stand. */
            prime_public_emit(
                arena, outcomes, evidence->expr.elems[i], current_env,
                preserve_bindings);
            emitted = true;
        }
        if (emitted) return;
    }
    prime_public_emit(
        arena, outcomes, inert_call, current_env, preserve_bindings);
}

static Atom *prime_public_bound_operand_syntax(
    Arena *arena, Atom *operand, const Bindings *environment);

/* The judgment a typing query call poses, with its space and optional
 * budget; on a malformed call, the error to emit. */
static bool prime_public_type_query_judgment(
    Space *current_space, Arena *arena, Atom *call,
    const Bindings *current_env, Space **space_out, Atom **judgment_out,
    bool *limited_out, uint64_t *steps_out, Atom **error_out) {
    SymbolId head_id = atom_head_symbol_id(call);
    bool binary = prime_public_type_query_is_binary(head_id);
    CettaExprLen required = binary ? 2u : 1u;
    CettaExprLen nargs = expr_nargs(call);
    Space *space = current_space;
    CettaExprIndex start = 0u;
    Atom *first_applied = nargs > 0u
        ? prime_public_bound_operand_syntax(arena, expr_arg(call, 0u), current_env)
        : NULL;
    Space *explicit_space = prime_public_space_argument(arena, first_applied);
    if (explicit_space) {
        space = explicit_space;
        start = 1u;
    }
    CettaExprLen remaining = nargs - start;
    if (remaining != required && remaining != required + 1u) {
        *error_out = atom_error(
            arena, call, atom_symbol(arena, "IncorrectNumberOfArguments"));
        return false;
    }
    Atom *first = prime_public_splice_type_operand(
        arena,
        prime_public_bound_operand_syntax(arena, expr_arg(call, start), current_env));
    Atom *second = binary
        ? prime_public_splice_type_operand(
              arena,
              prime_public_bound_operand_syntax(arena, expr_arg(call, start + 1u), current_env))
        : NULL;
    bool limited = remaining == required + 1u;
    uint64_t steps = 0u;
    if (limited) {
        Atom *budget = prime_public_bound_operand_syntax(arena, expr_arg(call, start + required), current_env);
        if (!prime_public_positive_budget(budget, &steps)) {
            *error_out = atom_error(
                arena, call, atom_symbol(arena, "PositiveBudgetIsExpected"));
            return false;
        }
    }
    *space_out = space;
    *judgment_out = prime_public_make_judgment(
        arena, head_id, first, second);
    *limited_out = limited;
    *steps_out = steps;
    return true;
}

static void prime_public_eval_type_query(
    Space *current_space, Arena *arena, Atom *call, int fuel,
    const Bindings *current_env, bool preserve_bindings,
    OutcomeSet *outcomes) {
    (void)fuel;
    SymbolId head_id = atom_head_symbol_id(call);
    Space *space = NULL;
    Atom *judgment = NULL;
    bool limited = false;
    uint64_t steps = 0u;
    Atom *error = NULL;
    if (!prime_public_type_query_judgment(
            current_space, arena, call, current_env, &space, &judgment,
            &limited, &steps, &error)) {
        prime_public_emit(
            arena, outcomes, error, current_env, preserve_bindings);
        return;
    }
    Atom *verdict = prime_semantics_judge_typing_direct(
        arena, space, judgment, limited, steps);
    Atom *inert = prime_public_applied_call(arena, call, current_env);
    Atom *evidence = NULL;
    PrimePublicVerdictStatus status =
        prime_public_verdict_view(verdict, &evidence);
    if (status == PRIME_PUBLIC_VERDICT_ESTABLISHED) {
        if (head_id == g_builtin_syms.type_colon_normalize)
            prime_public_emit(
                arena, outcomes, evidence, current_env, preserve_bindings);
        else if (head_id == g_builtin_syms.type_colon_of)
            prime_public_emit_type_evidence(
                arena, outcomes, evidence, inert, current_env,
                preserve_bindings);
        else
            prime_public_emit(
                arena, outcomes, atom_true(arena), current_env,
                preserve_bindings);
        return;
    }
    if (status == PRIME_PUBLIC_VERDICT_REFUTED) {
        prime_public_emit(
            arena, outcomes, atom_false(arena), current_env,
            preserve_bindings);
        return;
    }
    /* A term whose implicit parameters are not determined has no one type:
     * the query answers so, as `try` shows it, rather than standing as
     * written as an unasked query would. */
    if (status == PRIME_PUBLIC_VERDICT_UNDETERMINED &&
        head_id == g_builtin_syms.type_colon_of && evidence &&
        evidence->kind == ATOM_EXPR && evidence->expr.len >= 1u &&
        prime_public_symbol_named(
            evidence->expr.elems[0], "implicit-parameters")) {
        prime_public_emit(
            arena, outcomes,
            atom_expr2(arena, atom_symbol(arena, "Undetermined"), evidence),
            current_env, preserve_bindings);
        return;
    }
    prime_public_emit(
        arena, outcomes, inert, current_env, preserve_bindings);
}

/* `(type:kernel-query (type:eq ...))` or `(type:kernel-query (type:check ...))`:
 * the represented query the judgment poses to the kernel.  The judgment is
 * not evaluated for its answer. */
static void prime_public_eval_kernel_query(
    Space *current_space, Arena *arena, Atom *call,
    const Bindings *current_env, bool preserve_bindings,
    OutcomeSet *outcomes) {
    Atom *inner = expr_nargs(call) == 1u
        ? bindings_apply_if_vars(current_env, arena, expr_arg(call, 0u))
        : NULL;
    SymbolId inner_head = inner ? atom_head_symbol_id(inner) : SYMBOL_ID_NONE;
    if (inner_head != g_builtin_syms.type_colon_eq &&
        inner_head != g_builtin_syms.type_colon_check) {
        prime_public_emit(
            arena, outcomes,
            atom_error(arena, call,
                       atom_symbol(arena, "TypeEqOrTypeCheckIsExpected")),
            current_env, preserve_bindings);
        return;
    }
    Space *space = NULL;
    Atom *judgment = NULL;
    bool limited = false;
    uint64_t steps = 0u;
    Atom *error = NULL;
    if (!prime_public_type_query_judgment(
            current_space, arena, inner, current_env, &space, &judgment,
            &limited, &steps, &error)) {
        prime_public_emit(
            arena, outcomes, error, current_env, preserve_bindings);
        return;
    }
    Atom *query = prime_semantics_kernel_query(
        arena, space, judgment, limited, steps);
    prime_public_emit(
        arena, outcomes,
        query ? query : prime_public_applied_call(arena, call, current_env),
        current_env, preserve_bindings);
}

static void prime_public_eval_nik_check(
    Space *current_space, Arena *arena, Atom *call,
    const Bindings *current_env, bool preserve_bindings,
    OutcomeSet *outcomes) {
    CettaExprLen nargs = expr_nargs(call);
    Space *space = current_space;
    CettaExprIndex start = 0u;
    Atom *first_applied = nargs > 0u
        ? prime_public_bound_operand_syntax(arena, expr_arg(call, 0u), current_env)
        : NULL;
    Space *explicit_space = prime_public_space_argument(arena, first_applied);
    if (explicit_space) {
        space = explicit_space;
        start = 1u;
    }
    CettaExprLen remaining = nargs - start;
    if (remaining != 3u && remaining != 4u) {
        prime_public_emit(
            arena, outcomes,
            atom_error(arena, call,
                       atom_symbol(arena, "IncorrectNumberOfArguments")),
            current_env, preserve_bindings);
        return;
    }
    Atom *authority = prime_public_bound_operand_syntax(arena, expr_arg(call, start), current_env);
    Atom *claim = prime_public_bound_operand_syntax(arena, expr_arg(call, start + 1u), current_env);
    Atom *proof = prime_public_bound_operand_syntax(arena, expr_arg(call, start + 2u), current_env);
    bool limited = remaining == 4u;
    uint64_t steps = 0u;
    if (limited) {
        Atom *budget = prime_public_bound_operand_syntax(arena, expr_arg(call, start + 3u), current_env);
        if (!prime_public_positive_budget(budget, &steps)) {
            prime_public_emit(
                arena, outcomes,
                atom_error(arena, call,
                           atom_symbol(arena, "PositiveBudgetIsExpected")),
                current_env, preserve_bindings);
            return;
        }
    }
    Atom *judgment_children[] = {
        atom_symbol(arena, "nik:check"), authority, claim, proof,
    };
    Atom *judgment = atom_expr(arena, judgment_children, 4u);
    Atom *verdict = prime_semantics_check_nik_direct(
        arena, space, judgment, limited, steps);
    Atom *inert = prime_public_applied_call(arena, call, current_env);
    PrimePublicVerdictStatus status =
        prime_public_verdict_view(verdict, NULL);
    if (status == PRIME_PUBLIC_VERDICT_ESTABLISHED) {
        prime_public_emit(
            arena, outcomes, atom_true(arena), current_env,
            preserve_bindings);
        return;
    }
    if (status == PRIME_PUBLIC_VERDICT_REFUTED) {
        prime_public_emit(
            arena, outcomes, atom_false(arena), current_env,
            preserve_bindings);
        return;
    }
    prime_public_emit(
        arena, outcomes, inert, current_env, preserve_bindings);
}

/* The public spellings `type:theorem` and `type:prove` are provisional.
 * Their semantic split is stable: the former checks a supplied proof; the
 * latter evaluates a relational candidate stream and admits every proof it
 * can establish.  Both publish one opaque declaration only after a current
 * native judgment succeeds. */
/* Judgment operands are data.  An operand the evaluator has suspended as a
 * need on its way to the judgment stands for the syntax it suspended; the
 * judgment reads that syntax back through the inspection right and never
 * forces the suspension. */
Atom *prime_public_operand_syntax(Arena *arena, Atom *atom) {
    Atom *syntax = prime_need_reify_mode(
        arena, atom, &g_prime_need_active, PRIME_NEED_REIFY_JUDGMENT_SYNTAX,
        g_prime_need_logical_env, NULL, NULL);
    /* A refused traversal leaves the complete owned operand opaque. */
    Atom *projected = atom_prime_held_strip(arena, syntax ? syntax : atom);
    if (!projected && atom) {
        eval_mark_interrupted(CETTA_EVAL_INCOMPLETE_HOST_FAILURE);
        return atom;
    }
    return projected;
}

/* A data-only judgment inspects a retained operand in its owning world.
 * Reuse the scoped syntax observer: inspection never executes captured code,
 * and a missing inspection right leaves the operand opaque. */
static Atom *prime_public_bound_operand_syntax(
    Arena *arena, Atom *operand, const Bindings *environment) {
    __attribute__((cleanup(prime_need_active_leave)))
    PrimeNeedActiveGuard active;
    prime_need_active_enter(&active, environment);
    return prime_public_operand_syntax(arena,
        bindings_apply_if_vars(environment,arena,operand));
}

static Atom *prime_admitted_head_conflict(Arena *arena, Space *space, Atom *name) {
    if (!name || name->kind != ATOM_SYMBOL) return NULL;
    SpaceEquationCursor cursor;
    if (!space_rule_cursor_init_view(space, atom_symbol_current_id(name),
            eval_admitted_rule_forms(), true, &cursor))
        return atom_expr2(arena, atom_symbol(arena, "scope-unavailable"), name);
    SpaceEquationOccurrenceId occurrence;
    SpaceEquationCursorStep step = space_equation_cursor_next(&cursor, &occurrence);
    if (step == SPACE_EQUATION_CURSOR_END) return NULL;
    SpaceEquationOccurrence row;
    if (step != SPACE_EQUATION_CURSOR_ITEM ||
        !space_rule_occurrence_resolve_view(occurrence, eval_admitted_rule_forms(), true, &row))
        return atom_expr2(arena, atom_symbol(arena, "scope-changed"), name);
    return atom_expr3(arena, atom_symbol(arena, "scope-conflict"), name, row.equation);
}

/* Strict scope selection rejects ordinary equations at admitted computing
 * heads and constructors. It is an editing policy over the whole scope;
 * the default isolated view instead excludes those ordinary equations. */
static Atom *prime_admitted_scope_conflict(Arena *arena, Space *space) {
    for (Atom *rules = prime_semantics_kernel_rules(arena, space);
         rules && rules->kind == ATOM_EXPR && rules->expr.len == 3u &&
             prime_public_symbol_named(rules->expr.elems[0], "LCons");
         rules = rules->expr.elems[2]) {
        Atom *rule = rules->expr.elems[1];
        if (!rule || rule->kind != ATOM_EXPR || rule->expr.len != 5u) continue;
        Atom *conflict = prime_admitted_head_conflict(arena, space, rule->expr.elems[1]);
        if (conflict) return conflict;
    }
    CettaCount length = space_length64(space);
    for (CettaIndex i = 0u; i < length; i++) {
        Atom *record = space_get_at64(space, i);
        if (!record || record->kind != ATOM_EXPR || record->expr.len != 8u ||
            !(prime_public_symbol_named(record->expr.elems[0], "hol:known") ||
              prime_public_symbol_named(record->expr.elems[0], "set:known")) ||
            !prime_public_symbol_named(record->expr.elems[3], "inductive") ||
            !prime_scoped_judgment_admitted(arena, space, record)) continue;
        Atom *source = record->expr.elems[2];
        if (!source || source->kind != ATOM_EXPR) continue;
        for (CettaExprIndex j = 2u; j < source->expr.len; j++) {
            Atom *constructor = source->expr.elems[j];
            if (!constructor || constructor->kind != ATOM_EXPR || constructor->expr.len != 3u)
                continue;
            Atom *conflict = prime_admitted_head_conflict(arena, space, constructor->expr.elems[1]);
            if (conflict) return conflict;
        }
    }
    return NULL;
}

/* An admitted context is a request to the declaration checker, not an
 * authority-bearing value. Neither operand is evaluated to resolve it. */
static bool prime_public_eval_admitted(
    Space *current_space, Arena *arena, Atom *call,
    const Bindings *current_env, bool preserve_bindings,
    bool inspect, OutcomeSet *outcomes) {
    SymbolId head = atom_head_symbol_id(call);
    if ((head != g_builtin_syms.eval && head != g_builtin_syms.evalc) ||
        expr_nargs(call) != 2u) return false;
    Atom *scope = prime_public_bound_operand_syntax(
        arena, expr_arg(call, 1u), current_env);
    if (!scope || scope->kind != ATOM_EXPR || scope->expr.len == 0u ||
        !prime_public_symbol_named(scope->expr.elems[0], "admitted")) return false;
    Atom *inert = prime_public_applied_call(arena, call, current_env);
    Atom *reason = atom_symbol(arena, "admitted-scope-shape");
    Atom *verdict = NULL;
    if (scope->expr.len >= 2u && scope->expr.len <= 4u) {
        Space *target = prime_public_space_argument(arena, scope->expr.elems[1]);
        bool policy = scope->expr.len >= 3u && scope->expr.elems[2]->kind == ATOM_SYMBOL;
        bool strict = policy && prime_public_symbol_named(scope->expr.elems[2], "strict");
        bool known = !policy || strict || prime_public_symbol_named(scope->expr.elems[2], "isolated");
        size_t budget_at = policy ? 3u : 2u;
        bool limited = scope->expr.len == budget_at + 1u;
        uint64_t steps = 0u;
        CettaNikDirectAuthorityTokenV1 strict_token;
        if (!target) reason = atom_symbol(arena, "admitted-scope-space");
        else if (!known || scope->expr.len > budget_at + 1u)
            reason = atom_symbol(arena, "admitted-scope-policy");
        else if (limited && !prime_public_positive_budget(scope->expr.elems[budget_at], &steps))
            reason = atom_symbol(arena, "PositiveBudgetIsExpected");
        else if (strict && !cetta_prime_typing_direct_authority_token_v1(
                target, UINT32_C(0x4d535452), &strict_token))
            reason = atom_symbol(arena, "scope-changed");
        else if (strict && (reason = prime_admitted_scope_conflict(arena, target)) != NULL) {
            /* The conflict is inspectable; it licenses no computation. */
        }
        else {
            Atom *source = prime_public_bound_operand_syntax(
                arena, expr_arg(call, 0u), current_env);
            source = prime_public_splice_type_operand(arena, source);
            verdict = prime_semantics_evaluate_admitted(
                arena, target, source, limited, steps);
            if (strict && !cetta_prime_typing_direct_authority_token_v1_is_current(
                    &strict_token, target, UINT32_C(0x4d535452))) {
                verdict = NULL;
                reason = atom_symbol(arena, "scope-changed");
            }
        }
    }
    Atom *evidence = NULL;
    PrimePublicVerdictStatus status = prime_public_verdict_view(verdict, &evidence);
    Atom *result = inert;
    if (inspect) {
        Atom *tag = status != PRIME_PUBLIC_VERDICT_INVALID
            ? verdict->expr.elems[1] : atom_symbol(arena, "Undetermined");
        result = atom_expr2(arena, tag,
            status != PRIME_PUBLIC_VERDICT_INVALID ? verdict->expr.elems[3] : reason);
    } else if (status == PRIME_PUBLIC_VERDICT_ESTABLISHED && evidence &&
               evidence->kind == ATOM_EXPR && evidence->expr.len == 5u &&
               prime_public_symbol_named(evidence->expr.elems[0], "TypeNormalForm")) {
        result = evidence->expr.elems[2];
    }
    /* A normal form, including an opaque function application, is data in
     * its caller. Only another explicit evaluation can run it as code. */
    result = prime_completed_value(current_space, arena, result);
    prime_public_emit(arena, outcomes, result ? result : inert,
                      current_env, preserve_bindings);
    return true;
}

/* Scoped judgment bubbles (`set:`, `lang:`) share the `type:` readout: an
 * Established verdict is True unless its evidence carries a value to return
 * or a proposition to publish; Refuted is False; everything else stays inert. */
static void prime_public_eval_scoped_judgment(
    Space *current_space, Arena *arena, Atom *call,
    const Bindings *current_env, bool preserve_bindings,
    OutcomeSet *outcomes) {
    CettaExprLen nargs = expr_nargs(call);
    Space *space = current_space;
    CettaExprIndex start = 0u;
    Atom *first_applied = nargs > 0u
        ? bindings_apply_if_vars(current_env, arena, expr_arg(call, 0u))
        : NULL;
    Space *explicit_space = prime_public_space_argument(arena, first_applied);
    if (explicit_space) {
        space = explicit_space;
        start = 1u;
    }
    CettaExprLen count = nargs - start;
    if (atom_head_symbol_id(call) == g_builtin_syms.try_judgment && count == 1u) {
        Atom *subject = bindings_apply_if_vars(current_env, arena, expr_arg(call, start));
        if (prime_public_eval_admitted(space, arena, subject, current_env,
                preserve_bindings, true, outcomes)) return;
        SymbolId subject_head = atom_head_symbol_id(subject);
        bool judgment_subject = subject_head != SYMBOL_ID_NONE &&
            (prime_scoped_judgment_is_head_id(subject_head) ||
             prime_public_is_type_query(subject_head) ||
             subject_head == g_builtin_syms.nik_colon_check ||
             subject_head == g_builtin_syms.type_colon_may ||
             subject_head == g_builtin_syms.type_colon_must);
        if (!judgment_subject) {
            /* A program under try: evaluated once; no result and errors are
             * reported as such instead of vanishing. */
            OutcomeSet tmp;
            outcome_set_init(&tmp);
            eval_direct_outcomes(space, arena, NULL, subject, eval_get_default_fuel(), &tmp);
            Atom *value = NULL;
            Atom *error = NULL;
            for (CettaCount i = 0u; i < tmp.len && !error; i++)
                if (atom_is_error(tmp.items[i].atom)) error = tmp.items[i].atom;
            /* An error of the program is not a refutation: no judgment was
             * asked.  It is reported as the evaluation failing. */
            if (error) {
                value = atom_expr(arena, (Atom *[]) {atom_symbol(arena, "Failed"), error}, 2);
            } else if (tmp.len == 0u) {
                value = atom_expr(arena, (Atom *[]) {atom_symbol(arena, "Undetermined"),
                    atom_expr(arena, (Atom *[]) {atom_symbol(arena, "no-result"), subject}, 2)}, 2);
            } else {
                Atom **results = arena_alloc(arena, sizeof(Atom *) * (size_t)tmp.len);
                for (CettaCount i = 0u; i < tmp.len; i++) results[i] = tmp.items[i].atom;
                value = atom_expr(arena, (Atom *[]) {atom_symbol(arena, "Established"),
                    atom_expr(arena, results, (CettaExprLen)tmp.len)}, 2);
            }
            outcome_set_free(&tmp);
            prime_public_emit(arena, outcomes, value, current_env, preserve_bindings);
            return;
        }
    }
    Atom **items = arena_alloc(arena, sizeof(Atom *) * (size_t)(count + 1u));
    items[0] = call->expr.elems[0];
    for (CettaExprIndex i = 0u; i < count; i++) {
        /* A judgment takes its operands as syntax: a held value is the
         * syntax it holds. */
        items[i + 1u] = prime_public_operand_syntax(
            arena,
            prime_public_splice_type_operand(
                arena,
                atom_prime_held_strip(
                    arena,
                    bindings_apply_if_vars(
                        current_env, arena, expr_arg(call, start + i)))));
        if (!items[i + 1u] || eval_unwinding()) {
            eval_mark_interrupted(CETTA_EVAL_INCOMPLETE_HOST_FAILURE);
            return;
        }
    }
    Atom *judgment = atom_expr(arena, items, count + 1u);
    Atom *verdict = prime_scoped_judgment_judge(
        arena, space, judgment, false, 0u);
    Atom *inert = prime_public_applied_call(arena, call, current_env);
    Atom *evidence = NULL;
    PrimePublicVerdictStatus status =
        prime_public_verdict_view(verdict, &evidence);
    if (status == PRIME_PUBLIC_VERDICT_ESTABLISHED) {
        if (evidence && evidence->kind == ATOM_EXPR &&
            evidence->expr.len == 2u &&
            prime_public_symbol_named(
                evidence->expr.elems[0], "PrimeScopedValue")) {
            prime_public_emit(
                arena, outcomes, evidence->expr.elems[1], current_env,
                preserve_bindings);
            return;
        }
        if (evidence && evidence->kind == ATOM_EXPR &&
            evidence->expr.len >= 2u &&
            (prime_public_symbol_named(evidence->expr.elems[0], "SetPublish") ||
             prime_public_symbol_named(evidence->expr.elems[0], "HolPublish"))) {
            Atom *record = evidence->expr.elems[1];
            if (!record || record->kind != ATOM_EXPR || record->expr.len < 2u ||
                !eval_admit_atom(
                    space, arena, eval_storage_arena(arena), record)) {
                prime_public_emit(
                    arena, outcomes, inert, current_env, preserve_bindings);
                return;
            }
            prime_scoped_judgment_admit(arena, space, record);
            for (CettaExprIndex i = 2u; i < evidence->expr.len; i++) {
                Atom *extra = evidence->expr.elems[i];
                if (!extra) continue;
                eval_admit_atom(space, arena, eval_storage_arena(arena), extra);
                prime_scoped_judgment_admit(arena, space, extra);
            }
            prime_public_emit(
                arena, outcomes, record->expr.elems[1], current_env,
                preserve_bindings);
            return;
        }
        prime_public_emit(
            arena, outcomes, atom_true(arena), current_env,
            preserve_bindings);
        return;
    }
    if (status == PRIME_PUBLIC_VERDICT_REFUTED) {
        prime_public_emit(
            arena, outcomes, atom_false(arena), current_env,
            preserve_bindings);
        return;
    }
    prime_public_emit(
        arena, outcomes, inert, current_env, preserve_bindings);
}

/* Publication selects a checking space without moving the caller's proof
 * strategy into that space. The three-operand form retains its local scope. */
static Atom *prime_public_publication_scope(
    Arena *arena, Atom *call, const Bindings *environment, Space **space) {
    if (expr_nargs(call) != 4u) return call;
    Atom *scope = prime_public_bound_operand_syntax(
        arena, expr_arg(call, 0u), environment);
    Space *selected = prime_public_space_argument(arena, scope);
    if (!selected) return call;
    *space = selected;
    Atom *items[] = {call->expr.elems[0], expr_arg(call, 1u),
                     expr_arg(call, 2u), expr_arg(call, 3u)};
    return atom_expr(arena, items, 4u);
}

static void prime_public_eval_theorem(
    Space *space, Arena *arena, Atom *call,
    const Bindings *current_env, bool preserve_bindings,
    OutcomeSet *outcomes) {
    Atom *inert = prime_public_applied_call(arena, call, current_env);
    call = prime_public_publication_scope(arena, call, current_env, &space);
    if (expr_nargs(call) != 3u) {
        prime_public_emit(
            arena, outcomes,
            atom_error(arena, call,
                       atom_symbol(arena, "IncorrectNumberOfArguments")),
            current_env, preserve_bindings);
        return;
    }
    Atom *name = prime_public_bound_operand_syntax(
        arena, expr_arg(call, 0u), current_env);
    Atom *type = prime_public_bound_operand_syntax(
        arena, expr_arg(call, 1u), current_env);
    Atom *proof = prime_public_bound_operand_syntax(
        arena, expr_arg(call, 2u), current_env);
    if (!name || name->kind != ATOM_SYMBOL) {
        prime_public_emit(
            arena, outcomes, inert, current_env, preserve_bindings);
        return;
    }
    CettaNikDirectAuthorityTokenV1 token;
    if (!cetta_prime_typing_direct_authority_token_v1(
            space, UINT32_C(0x54595448), &token)) {
        prime_public_emit(
            arena, outcomes, inert, current_env, preserve_bindings);
        return;
    }
    Atom *judgment = atom_expr3(
        arena, atom_symbol(arena, "type:check"), proof, type);
    Atom *evidence = NULL;
    PrimePublicVerdictStatus status = prime_public_verdict_view(
        prime_semantics_judge_typing_direct(
            arena, space, judgment, false, 0u),
        &evidence);
    if (status == PRIME_PUBLIC_VERDICT_REFUTED) {
        prime_public_emit(
            arena, outcomes, atom_false(arena), current_env,
            preserve_bindings);
        return;
    }
    /* The theorem is published with the context its judgment used, so that
     * it is reused only while that context is available. */
    Atom *context = status == PRIME_PUBLIC_VERDICT_ESTABLISHED &&
                            prime_public_native_check_evidence(evidence)
        ? prime_semantics_theorem_context(
              arena, space, judgment,
              prime_public_declared_check_evidence(evidence))
        : NULL;
    if (!context ||
        !cetta_prime_typing_direct_authority_token_v1_is_current(
            &token, space, UINT32_C(0x54595448)) ||
        !prime_public_publish_declaration(space, arena, name, type)) {
        prime_public_emit(
            arena, outcomes, inert, current_env, preserve_bindings);
        return;
    }
    prime_semantics_theorem_record(space, name, type, &context, 1u);
    prime_public_emit(
        arena, outcomes, name, current_env, preserve_bindings);
}

static void prime_public_eval_prove(
    Space *space, Arena *arena, Atom *call, int fuel,
    const Bindings *current_env, bool preserve_bindings,
    OutcomeSet *outcomes) {
    Space *strategy_space = space;
    Atom *inert = prime_public_applied_call(arena, call, current_env);
    call = prime_public_publication_scope(arena, call, current_env, &space);
    if (expr_nargs(call) != 3u) {
        prime_public_emit(
            arena, outcomes,
            atom_error(arena, call,
                       atom_symbol(arena, "IncorrectNumberOfArguments")),
            current_env, preserve_bindings);
        return;
    }
    Atom *name = prime_public_bound_operand_syntax(
        arena, expr_arg(call, 0u), current_env);
    Atom *type = prime_public_bound_operand_syntax(
        arena, expr_arg(call, 1u), current_env);
    Atom *search = prime_public_bound_operand_syntax(
        arena, expr_arg(call, 2u), current_env);
    if (!name || name->kind != ATOM_SYMBOL) {
        prime_public_emit(
            arena, outcomes, inert, current_env, preserve_bindings);
        return;
    }

    OutcomeSet candidates;
    outcome_set_init(&candidates);
    metta_eval_bind(strategy_space, arena, search, fuel, &candidates);
    Atom **accepted = candidates.len
        ? cetta_malloc(sizeof(Atom *) * (size_t)candidates.len)
        : NULL;
    Atom **contexts = candidates.len
        ? cetta_malloc(sizeof(Atom *) * (size_t)candidates.len)
        : NULL;
    CettaCount accepted_count = 0u;
    CettaNikDirectAuthorityTokenV1 token;
    bool token_valid = cetta_prime_typing_direct_authority_token_v1(
        space, UINT32_C(0x54595052), &token);
    for (CettaCount i = 0u; i < candidates.len; i++) {
        Atom *candidate = outcome_atom_materialize(
            arena, &candidates.items[i]);
        if (!candidate) continue;
        if (atom_is_error(candidate)) {
            prime_public_emit(
                arena, outcomes, candidate, current_env, preserve_bindings);
            continue;
        }
        Atom *judgment = atom_expr3(
            arena, atom_symbol(arena, "type:check"), candidate, type);
        Atom *evidence = NULL;
        PrimePublicVerdictStatus status = token_valid
            ? prime_public_verdict_view(
                  prime_semantics_judge_typing_direct(
                      arena, space, judgment, false, 0u),
                  &evidence)
            : PRIME_PUBLIC_VERDICT_UNDETERMINED;
        /* An accepted proof carries the context its judgment used. */
        Atom *context = status == PRIME_PUBLIC_VERDICT_ESTABLISHED &&
                                prime_public_native_check_evidence(evidence)
            ? prime_semantics_theorem_context(
                  arena, space, judgment,
                  prime_public_declared_check_evidence(evidence))
            : NULL;
        if (context) {
            contexts[accepted_count] = context;
            accepted[accepted_count++] = candidate;
        } else if (status != PRIME_PUBLIC_VERDICT_REFUTED) {
            Atom *retry_children[] = {
                atom_symbol_id(arena, g_builtin_syms.type_colon_theorem),
                name, type, candidate,
            };
            Atom *retry = atom_expr(arena, retry_children, 4u);
            prime_public_emit(
                arena, outcomes, retry, current_env, preserve_bindings);
        }
    }
    bool current = token_valid &&
        cetta_prime_typing_direct_authority_token_v1_is_current(
            &token, space, UINT32_C(0x54595052));
    bool published = accepted_count > 0u && current &&
        prime_public_publish_declaration(space, arena, name, type);
    if (published) {
        prime_semantics_theorem_record(
            space, name, type, contexts, (size_t)accepted_count);
        for (CettaCount i = 0u; i < accepted_count; i++) {
            (void)accepted[i];
            prime_public_emit(
                arena, outcomes, name, current_env, preserve_bindings);
        }
    } else {
        for (CettaCount i = 0u; i < accepted_count; i++) {
            Atom *retry_children[] = {
                atom_symbol_id(arena, g_builtin_syms.type_colon_theorem),
                name, type, accepted[i],
            };
            Atom *retry = atom_expr(arena, retry_children, 4u);
            prime_public_emit(
                arena, outcomes, retry, current_env, preserve_bindings);
        }
    }
    free(contexts);
    free(accepted);
    outcome_set_free(&candidates);
}

/* A measurement (cost:firings, demand:report) answers one value for all the
 * values of the expression it measures, and owns the productions that
 * evaluation forced.  Those forced before the values parted are shared by
 * all of them, and the continuation keeps them, up to any cell still being
 * evaluated there: a producer forced inside the measurement and used again
 * after it is produced, and charged, once.  A production that one value
 * alone depends on stays with that value. */
static void prime_public_emit_measurement(
    Arena *arena, OutcomeSet *outcomes, Atom *result,
    const OutcomeSet *values, const Bindings *current_env,
    bool preserve_bindings) {
    PrimeNeedSnapshot shared;
    prime_need_snapshot_init(&shared);
    bool shared_known = false;
    bool shared_ok = true;
    for (CettaCount i = 0u; i < values->len && shared_ok; i++) {
        const PrimeNeedSnapshot *heap =
            bindings_need_view(&values->items[i].env);
        if (!prime_need_snapshot_present(heap))
            continue;
        if (!shared_known) {
            shared = *heap;
            shared_known = true;
        } else if (!prime_need_snapshot_common_ancestor(
                       &shared, heap, &shared)) {
            shared_ok = false;
        }
    }
    if (shared_ok && shared_known &&
        prime_need_snapshot_is_ancestor(&g_prime_need_active, &shared) &&
        prime_need_snapshot_settled_ancestor(
            &g_prime_need_active, &shared, &shared)) {
        Bindings kept;
        bindings_init(&kept);
        *bindings_need_mut(&kept) = shared;
        outcome_set_add_prefixed(
            arena, outcomes, result, &kept, current_env, preserve_bindings);
        bindings_free(&kept);
        return;
    }
    prime_public_emit(arena, outcomes, result, current_env, preserve_bindings);
}

/* ── Prime: demand bubbles ────────────────────────────────────────────────
 * Prime's top commits to no evaluation strategy.  A bubble commits the region
 * written inside it to one.  The region's binding sites are the arguments of
 * the calls written there, which are passed lazily, as shared suspensions,
 * unless something commits otherwise, and its `let` bindings, which are
 * evaluated eagerly.  A strategy is `eager` (evaluate the binding before it is
 * used, once, and go on once per answer), `lazy` (evaluate it at its first use
 * and share that answer) or `resample` (evaluate it again at every use).
 *
 * Two forms stand side by side, so that programs can compare them:
 *
 *   (demand:licensed S e)   applies S at a site only where the answers stay
 *     the same as with the site's own strategy.  A binding used n times whose
 *     computation has b answers gives the same bag eagerly and lazily exactly
 *     when n >= 1 or b = 1 (GSLT.Dynamics.DemandAgreement.eagerShared_eq_lazyShared_iff),
 *     and the same bag shared and resampled exactly when n <= 1 or b <= 1
 *     (GSLT.Dynamics.DemandAgreement.lazyShared_eq_resampledUses_iff); the three
 *     agree together exactly when both hold
 *     (GSLT.Dynamics.DemandAgreement.strategies_agree_iff, their conjunction).
 *     Where that is not established the site keeps its strategy, and a record
 *     says why.
 *
 *   (demand:committed S e)  applies S at every site, and so changes the
 *     answers where the theorem says it must.  Its records name the change: a
 *     computation evaluated eagerly though it is discarded still contributes
 *     its answers, one copy of the result for each; a resampled binding draws
 *     an answer of its own at each use.
 *
 *   (demand:report e)  answers e's values together with the records the
 *     bubbles in e made: ((values ...) (records ...)).
 *
 * A bubble is elaborated into Prime's own forms, then runs: an argument
 * evaluated eagerly is bound by `let` before the call; a `let` binding made
 * lazy becomes `(force p)` of one `(delay v)`; a `let` binding resampled is
 * replaced at each use by `(force (resample v))`.  The records are made as the
 * bubble is elaborated, one per site.  The region is what is written in the
 * bubble, through calls, `let`, `let*`, `if` and `collapse`; it does not extend
 * into the bodies of the functions it calls nor inside other forms, and an
 * inner bubble governs its own region.  A call shares the one suspension of
 * its argument, and passing an argument to be evaluated again at each use is
 * not available, so an argument cannot be resampled; such a site keeps its
 * strategy and is recorded. */
typedef enum {
    PRIME_DEMAND_EAGER = 0,
    PRIME_DEMAND_LAZY,
    PRIME_DEMAND_RESAMPLE,
} PrimeDemandStrategy;

/* The bubble words are recognized without being interned: a program that
 * never writes them leaves the symbol table as it found it. */
static PrimeDemandForm prime_demand_form(SymbolId head) {
    static const char *const names[3] = {
        "demand:licensed", "demand:committed", "demand:report",
    };
    static __thread const SymbolTable *table = NULL;
    static __thread uint64_t table_instance_id = 0u;
    static __thread SymbolId ids[3] = {
        SYMBOL_ID_NONE, SYMBOL_ID_NONE, SYMBOL_ID_NONE,
    };
    if (!g_symbols || head == SYMBOL_ID_NONE || symbol_id_is_builtin_for(head, eval_current_language_id()))
        return PRIME_DEMAND_FORM_NONE;
    uint64_t instance_id = symbol_table_instance_id(g_symbols);
    if (table != g_symbols || table_instance_id != instance_id) {
        table = g_symbols;
        table_instance_id = instance_id;
        for (size_t i = 0u; i < 3u; i++)
            ids[i] = SYMBOL_ID_NONE;
    }
    for (size_t i = 0u; i < 3u; i++)
        if (head == ids[i])
            return (PrimeDemandForm)(i + 1u);
    if (ids[0] != SYMBOL_ID_NONE && ids[1] != SYMBOL_ID_NONE &&
        ids[2] != SYMBOL_ID_NONE)
        return PRIME_DEMAND_FORM_NONE;
    uint32_t length = symbol_len(g_symbols, head);
    for (size_t i = 0u; i < 3u; i++) {
        if (ids[i] == SYMBOL_ID_NONE &&
            length == (uint32_t)strlen(names[i]) &&
            symbol_eq_cstr(g_symbols, head, names[i])) {
            ids[i] = head;
            return (PrimeDemandForm)(i + 1u);
        }
    }
    return PRIME_DEMAND_FORM_NONE;
}

static bool prime_demand_strategy(Atom *word, PrimeDemandStrategy *out) {
    if (!word || word->kind != ATOM_SYMBOL)
        return false;
    if (atom_symbol_equals_cstr(word, "eager"))
        *out = PRIME_DEMAND_EAGER;
    else if (atom_symbol_equals_cstr(word, "lazy"))
        *out = PRIME_DEMAND_LAZY;
    else if (atom_symbol_equals_cstr(word, "resample"))
        *out = PRIME_DEMAND_RESAMPLE;
    else
        return false;
    return true;
}

/* The theorems that license a strategy at a site: eager and lazy sharing
 * agree on a binding used at least once or with one answer; eager sharing
 * and resampling agree on one used exactly once or with one answer. */
static const char *const PRIME_DEMAND_EAGER_LAZY_LICENCE =
    "GSLT.Dynamics.DemandAgreement.eagerShared_eq_lazyShared_iff";
static const char *const PRIME_DEMAND_STRATEGIES_LICENCE =
    "GSLT.Dynamics.DemandAgreement.strategies_agree_iff";

static const char *prime_demand_strategy_word(PrimeDemandStrategy strategy) {
    return strategy == PRIME_DEMAND_EAGER ? "eager"
         : strategy == PRIME_DEMAND_LAZY ? "lazy"
         : "resample";
}

/* The reports being made, innermost first.  A record goes to each of them,
 * copied into its arena, once; a record made while no report is open is
 * read by no one and is not kept. */
typedef struct PrimeDemandReport {
    struct PrimeDemandReport *outer;
    Arena *arena;
    Atom **items;
    size_t len;
    size_t cap;
} PrimeDemandReport;

static __thread PrimeDemandReport *g_prime_demand_report = NULL;

static void prime_demand_record(Arena *a, const char *kind,
                                PrimeDemandStrategy strategy,
                                const char *why, const char *license,
                                Atom *site) {
    if (!g_prime_demand_report)
        return;
    /* A record is data: held, it prints as written, and the site's call is
     * not run again when the record is observed.  A strategy applied under
     * licence names the theorem that licenses it. */
    Atom *reason = license
        ? atom_expr2(a, atom_symbol(a, why), atom_symbol(a, license))
        : atom_expr(a, (Atom *[]){atom_symbol(a, why)}, 1u);
    Atom *record = atom_prime_held_wrap(a, atom_expr(a, (Atom *[]){
        atom_symbol(a, kind),
        atom_symbol(a, prime_demand_strategy_word(strategy)),
        reason,
        site,
    }, 4u));
    if (!record)
        return;
    for (PrimeDemandReport *report = g_prime_demand_report; report;
         report = report->outer) {
        bool seen = false;
        for (size_t i = 0u; i < report->len && !seen; i++)
            seen = atom_eq(report->items[i], record);
        if (seen)
            continue;
        Atom *kept = report->arena != a
            ? atom_deep_copy(report->arena, record) : record;
        if (!kept)
            continue;
        if (report->len == report->cap) {
            size_t cap = report->cap ? report->cap * 2u : 8u;
            report->items = cetta_realloc(
                report->items, sizeof(*report->items) * cap);
            report->cap = cap;
        }
        report->items[report->len++] = kept;
    }
}

/* How an applied function uses its argument at `index`, read from the
 * equations of its head: demanded when the head is an operation that
 * demands it, or when every equation demands it, by a pattern that
 * inspects it or by a body that certainly uses the variable its pattern
 * binds it to (returns it, or passes it where it is demanded: at least once
 * on every path, the licence of a let binding in
 * prime_demand_elaborate_binding); unused when every equation binds it to a
 * variable that occurs nowhere else in the equation. */
typedef enum {
    PRIME_DEMAND_USE_UNKNOWN = 0,
    PRIME_DEMAND_USE_DEMANDED,
    PRIME_DEMAND_USE_UNUSED,
} PrimeDemandUse;

static size_t prime_demand_var_occurrences(Atom *atom, VarId var) {
    if (!atom)
        return 0u;
    if (atom->kind == ATOM_VAR)
        return var_id_eq(atom->var_id, var) ? 1u : 0u;
    if (atom->kind != ATOM_EXPR || !atom_has_vars(atom))
        return 0u;
    size_t count = 0u;
    for (CettaExprIndex i = 0u; i < atom->expr.len; i++)
        count += prime_demand_var_occurrences(atom->expr.elems[i], var);
    return count;
}

typedef struct {
    uint32_t min;
    uint32_t max;
} PrimeDemandUses;

static PrimeDemandUses prime_demand_var_uses(Space *s, Atom *expr,
                                             VarId var);

/* The argument-use queries being answered on this thread: a query met again
 * inside its own answer (a recursive equation) answers unknown, the least
 * it can claim. */
typedef struct PrimeDemandUseQuery {
    SymbolId head;
    CettaExprLen nargs;
    CettaExprIndex index;
    const struct PrimeDemandUseQuery *outer;
} PrimeDemandUseQuery;

static __thread const PrimeDemandUseQuery *g_prime_demand_use_queries = NULL;

static PrimeDemandUse prime_demand_argument_use(Space *s, Atom *call,
                                                CettaExprIndex index) {
    Atom *head = call->expr.elems[0];
    if (head->kind != ATOM_SYMBOL)
        return PRIME_DEMAND_USE_UNKNOWN;
    CettaExprLen nargs = call->expr.len - 1u;
    if (prime_need_argument_mode(atom_symbol_current_id(head), nargs, index) !=
        PRIME_NEED_ARGUMENT_DATA)
        return PRIME_DEMAND_USE_DEMANDED;
    if (!space_equations_may_match_known_head(s, atom_symbol_current_id(head)))
        return PRIME_DEMAND_USE_UNKNOWN;
    for (const PrimeDemandUseQuery *q = g_prime_demand_use_queries; q;
         q = q->outer)
        if (q->head == atom_symbol_current_id(head) && q->nargs == nargs &&
            q->index == index)
            return PRIME_DEMAND_USE_UNKNOWN;
    SpaceEquationCursor cursor;
    if (!space_equation_cursor_init(s, atom_symbol_current_id(head), &cursor))
        return PRIME_DEMAND_USE_UNKNOWN;
    PrimeDemandUseQuery query = {
        atom_symbol_current_id(head), nargs, index, g_prime_demand_use_queries};
    g_prime_demand_use_queries = &query;
    bool any = false;
    bool all_demanded = true;
    bool all_unused = true;
    for (;;) {
        SpaceEquationOccurrenceId id;
        if (space_equation_cursor_next(&cursor, &id) !=
            SPACE_EQUATION_CURSOR_ITEM)
            break;
        SpaceEquationOccurrence occurrence;
        if (!space_equation_occurrence_resolve(id, &occurrence) ||
            !occurrence.lhs || occurrence.lhs->kind != ATOM_EXPR ||
            occurrence.lhs->expr.len != call->expr.len ||
            !atom_is_symbol_id(occurrence.lhs->expr.elems[0], atom_symbol_current_id(head)))
            continue;
        any = true;
        Atom *pattern = occurrence.lhs->expr.elems[index + 1u];
        if (pattern->kind != ATOM_VAR) {
            all_unused = false;
            continue;
        }
        size_t uses =
            prime_demand_var_occurrences(occurrence.lhs, pattern->var_id) +
            prime_demand_var_occurrences(occurrence.rhs, pattern->var_id);
        if (uses > 1u)
            all_unused = false;
        if (all_demanded &&
            prime_demand_var_uses(s, occurrence.rhs, pattern->var_id).min ==
                0u)
            all_demanded = false;
    }
    g_prime_demand_use_queries = query.outer;
    if (!any)
        return PRIME_DEMAND_USE_UNKNOWN;
    if (all_demanded)
        return PRIME_DEMAND_USE_DEMANDED;
    return all_unused ? PRIME_DEMAND_USE_UNUSED : PRIME_DEMAND_USE_UNKNOWN;
}

/* Bounds on how many times evaluating `expr` uses the variable `var`: an
 * occurrence counts once, at least once only where it is certainly
 * evaluated (PrimeDemandUses). */

#define PRIME_DEMAND_USES_MANY UINT32_MAX

static uint32_t prime_demand_uses_sum(uint32_t x, uint32_t y) {
    return x > PRIME_DEMAND_USES_MANY - y ? PRIME_DEMAND_USES_MANY : x + y;
}

static PrimeDemandUses prime_demand_uses_add(PrimeDemandUses x,
                                             PrimeDemandUses y) {
    return (PrimeDemandUses){
        prime_demand_uses_sum(x.min, y.min),
        prime_demand_uses_sum(x.max, y.max),
    };
}

static bool prime_demand_is_call_head(Atom *head) {
    if (!head || head->kind != ATOM_SYMBOL)
        return false;
    SymbolId id = atom_symbol_current_id(head);
    if (prime_demand_form(id) != PRIME_DEMAND_FORM_NONE ||
        prime_scoped_judgment_is_head_id(id) || registry_lookup_atom(head))
        return false;
    return is_grounded_op(id) || !symbol_id_is_builtin_for(id, eval_current_language_id());
}

static PrimeDemandUses prime_demand_var_uses(Space *s, Atom *expr,
                                             VarId var) {
    PrimeDemandUses none = {0u, 0u};
    if (!expr)
        return none;
    if (expr->kind == ATOM_VAR)
        return var_id_eq(expr->var_id, var) ? (PrimeDemandUses){1u, 1u} : none;
    if (expr->kind != ATOM_EXPR || expr->expr.len == 0u ||
        !atom_has_vars(expr) || prime_demand_var_occurrences(expr, var) == 0u)
        return none;
    Atom *head = expr->expr.elems[0];
    if (atom_is_symbol_id(head, g_builtin_syms.quote))
        return none;
    if (expr->expr.len == 4u && atom_is_symbol_id(head, g_builtin_syms.if_text)) {
        PrimeDemandUses then_uses = prime_demand_var_uses(s, expr->expr.elems[2], var);
        PrimeDemandUses else_uses = prime_demand_var_uses(s, expr->expr.elems[3], var);
        PrimeDemandUses branch = {
            then_uses.min < else_uses.min ? then_uses.min : else_uses.min,
            then_uses.max > else_uses.max ? then_uses.max : else_uses.max,
        };
        return prime_demand_uses_add(
            prime_demand_var_uses(s, expr->expr.elems[1], var), branch);
    }
    if (expr->expr.len == 4u && atom_is_symbol_id(head, g_builtin_syms.let))
        return prime_demand_uses_add(
            prime_demand_var_uses(s, expr->expr.elems[2], var),
            prime_demand_var_uses(s, expr->expr.elems[3], var));
    if (expr->expr.len == 2u && atom_is_symbol_id(head, g_builtin_syms.collapse))
        return prime_demand_var_uses(s, expr->expr.elems[1], var);
    if (!prime_need_is_explicit_control_form(expr) &&
        prime_demand_is_call_head(head)) {
        PrimeDemandUses total = none;
        for (CettaExprIndex i = 1u; i < expr->expr.len; i++) {
            PrimeDemandUses argument =
                prime_demand_var_uses(s, expr->expr.elems[i], var);
            if (argument.max == 0u)
                continue;
            if (prime_demand_argument_use(s, expr, i - 1u) !=
                PRIME_DEMAND_USE_DEMANDED)
                argument.min = 0u;
            total = prime_demand_uses_add(total, argument);
        }
        return total;
    }
    return (PrimeDemandUses){0u, PRIME_DEMAND_USES_MANY};
}

/* A binding whose computation is already a value has one answer: no
 * strategy changes it. */
static bool prime_demand_is_value(Space *s, Arena *a, Atom *atom) {
    return atom_eval_is_immediate_value(atom, 1) ||
           (!prime_need_atom_has_observable_ref(atom) &&
            !prime_need_is_explicit_control_form(atom) &&
            atom_is_constructor_normal_form(s, a, atom, 1));
}

typedef struct {
    Space *space;
    Arena *arena;
    PrimeDemandStrategy strategy;
    bool committed;
} PrimeDemandElaboration;

static Atom *prime_demand_elaborate(PrimeDemandElaboration *el, Atom *expr);

static Atom *prime_demand_fresh_var(Arena *a) {
    return atom_var_with_id(a, "demand", fresh_var_id());
}

/* A `let` binding of a variable, at the bubble's strategy. */
static Atom *prime_demand_elaborate_binding(PrimeDemandElaboration *el,
                                            Atom *let, Atom *site_source,
                                            Atom *var, Atom *value, Atom *body) {
    Arena *a = el->arena;
    Atom *site = atom_expr(a, (Atom *[]){
        atom_symbol(a, "binding"), site_source->expr.elems[1],
        site_source->expr.elems[2]}, 3u);
    Atom *kept = atom_expr(a, (Atom *[]){let->expr.elems[0], var, value, body}, 4u);
    if (el->strategy == PRIME_DEMAND_EAGER ||
        prime_demand_is_value(el->space, a, value))
        return kept;
    PrimeDemandUses uses = prime_demand_var_uses(el->space, body, var->var_id);
    bool licensed;
    const char *reason;
    if (el->strategy == PRIME_DEMAND_LAZY) {
        /* Eager and lazy agree exactly when the binding is used. */
        licensed = uses.min >= 1u;
        reason = "may-discard-answers";
    } else {
        /* Eager and resampled agree exactly when it is used once. */
        licensed = uses.min >= 1u && uses.max <= 1u;
        reason = uses.max >= 2u ? "may-copy-answers" : "may-discard-answers";
    }
    if (!el->committed && !licensed) {
        prime_demand_record(a, "demand-kept", PRIME_DEMAND_EAGER, reason,
                            NULL, site);
        return kept;
    }
    if (licensed)
        prime_demand_record(
            a, "demand-applied", el->strategy,
            el->strategy == PRIME_DEMAND_LAZY ? "used" : "used-once",
            el->strategy == PRIME_DEMAND_LAZY
                ? PRIME_DEMAND_EAGER_LAZY_LICENCE
                : PRIME_DEMAND_STRATEGIES_LICENCE,
            site);
    else
        prime_demand_record(
            a, "demand-changed", el->strategy,
            el->strategy == PRIME_DEMAND_RESAMPLE && uses.max >= 2u
                ? "copied-per-use"
                : uses.max == 0u ? "unused-unrun" : "may-discard-answers",
            NULL, site);
    if (el->strategy == PRIME_DEMAND_RESAMPLE) {
        Atom *draw = atom_expr2(
            a, atom_symbol_id(a, prime_need_symbols()->force),
            atom_expr2(a, atom_symbol_id(a, prime_need_symbols()->resample),
                       value));
        return instantiate_template_variable_once(a, body, var->var_id, draw);
    }
    Atom *promise = prime_demand_fresh_var(a);
    Atom *use = atom_expr2(a, atom_symbol_id(a, prime_need_symbols()->force),
                           promise);
    Atom *delayed = atom_expr2(
        a, atom_symbol_id(a, prime_need_symbols()->delay), value);
    return atom_expr(a, (Atom *[]){
        let->expr.elems[0], promise, delayed,
        instantiate_template_variable_once(a, body, var->var_id, use)}, 4u);
}

/* A call: its arguments are elaborated, then each is a site. */
static Atom *prime_demand_elaborate_call(PrimeDemandElaboration *el,
                                         Atom *call) {
    Arena *a = el->arena;
    CettaExprLen len = call->expr.len;
    Atom **elems = arena_alloc(a, sizeof(*elems) * (size_t)len);
    Atom **bound = arena_alloc(a, sizeof(*bound) * (size_t)len);
    elems[0] = call->expr.elems[0];
    bound[0] = NULL;
    for (CettaExprIndex i = 1u; i < len; i++) {
        elems[i] = prime_demand_elaborate(el, call->expr.elems[i]);
        bound[i] = NULL;
        if (el->strategy == PRIME_DEMAND_LAZY ||
            prime_demand_is_value(el->space, a, elems[i]))
            continue;
        Atom *site = atom_expr(a, (Atom *[]){
            atom_symbol(a, "argument"), atom_int(a, (int64_t)i), call}, 3u);
        if (el->strategy == PRIME_DEMAND_RESAMPLE) {
            prime_demand_record(a, "demand-kept", PRIME_DEMAND_LAZY,
                                "by-name-unavailable", NULL, site);
            continue;
        }
        PrimeDemandUse use = prime_demand_argument_use(el->space, call, i - 1u);
        if (use == PRIME_DEMAND_USE_DEMANDED) {
            prime_demand_record(a, "demand-applied", PRIME_DEMAND_EAGER,
                                "demanded", PRIME_DEMAND_EAGER_LAZY_LICENCE,
                                site);
        } else if (!el->committed) {
            prime_demand_record(a, "demand-kept", PRIME_DEMAND_LAZY,
                                "may-discard-answers", NULL, site);
            continue;
        } else {
            prime_demand_record(
                a, "demand-changed", PRIME_DEMAND_EAGER,
                use == PRIME_DEMAND_USE_UNUSED
                    ? "discarded-contributes-answers" : "may-discard-answers",
                NULL, site);
        }
        bound[i] = elems[i];
        elems[i] = prime_demand_fresh_var(a);
    }
    Atom *result = atom_expr(a, elems, len);
    for (CettaExprIndex i = len; i-- > 1u;) {
        if (!bound[i])
            continue;
        result = atom_expr(a, (Atom *[]){
            atom_symbol_id(a, g_builtin_syms.let), elems[i], bound[i], result},
            4u);
    }
    return result;
}

static Atom *prime_demand_elaborate(PrimeDemandElaboration *el, Atom *expr) {
    Arena *a = el->arena;
    /* Scope annotations have already resolved ownership. Demand still sees
     * the annotated binding site, just as ordinary execution does. */
    if (atom_is_prime_meta(expr) && prime_semantics_meta_core(a, expr))
        return prime_demand_elaborate(el, expr->expr.elems[1]);
    Atom *activation = prime_semantics_pattern_activation(a, expr);
    if (!activation) return NULL;
    /* Receipts name the authored site; fresh slots are execution evidence,
     * not a renaming of the binding the user asked to observe. */
    Atom *site_source = expr;
    expr = activation;
    if (!expr || expr->kind != ATOM_EXPR || expr->expr.len == 0u ||
        atom_prime_held_is(expr))
        return expr;
    Atom *head = expr->expr.elems[0];
    if (head->kind != ATOM_SYMBOL)
        return expr;
    SymbolId id = atom_symbol_current_id(head);
    if (expr->expr.len == 4u && id == g_builtin_syms.let) {
        Atom *pattern = expr->expr.elems[1];
        Atom *value = prime_demand_elaborate(el, expr->expr.elems[2]);
        Atom *body = prime_demand_elaborate(el, expr->expr.elems[3]);
        if (pattern->kind != ATOM_VAR)
            return atom_expr(a, (Atom *[]){head, pattern, value, body}, 4u);
        return prime_demand_elaborate_binding(el, expr, site_source, pattern, value, body);
    }
    if (expr->expr.len == 3u && id == g_builtin_syms.let_star &&
        expr->expr.elems[1]->kind == ATOM_EXPR) {
        /* (let* ((p1 v1) ...) body) is (let p1 v1 (let* (...) body)). */
        Atom *bindings = expr->expr.elems[1];
        Atom *body = expr->expr.elems[2];
        for (CettaExprIndex i = bindings->expr.len; i-- > 0u;) {
            Atom *pair = bindings->expr.elems[i];
            if (pair->kind != ATOM_EXPR || pair->expr.len != 2u)
                return expr;
            body = atom_expr(a, (Atom *[]){
                atom_symbol_id(a, g_builtin_syms.let),
                pair->expr.elems[0], pair->expr.elems[1], body}, 4u);
        }
        return prime_demand_elaborate(el, body);
    }
    if (expr->expr.len == 4u && id == g_builtin_syms.if_text)
        return atom_expr(a, (Atom *[]){
            head,
            prime_demand_elaborate(el, expr->expr.elems[1]),
            prime_demand_elaborate(el, expr->expr.elems[2]),
            prime_demand_elaborate(el, expr->expr.elems[3])}, 4u);
    if (expr->expr.len == 2u && id == g_builtin_syms.collapse)
        return atom_expr2(a, head, prime_demand_elaborate(el, expr->expr.elems[1]));
    if (prime_need_is_explicit_control_form(expr) ||
        !prime_demand_is_call_head(head))
        return expr;
    return prime_demand_elaborate_call(el, expr);
}

/* The expression a bubble runs as: its body elaborated at its strategy, or
 * NULL when the bubble is not one Prime can read (it then stays as
 * written). */
static Atom *prime_demand_bubble(Space *s, Arena *a, Atom *call,
                                 bool committed, const Bindings *env) {
    if (!call || call->kind != ATOM_EXPR || call->expr.len != 3u)
        return NULL;
    PrimeDemandStrategy strategy;
    Atom *word = bindings_apply_if_vars((Bindings *)env, a, call->expr.elems[1]);
    if (!prime_demand_strategy(word, &strategy))
        return NULL;
    Atom *body = bindings_apply_if_vars((Bindings *)env, a, call->expr.elems[2]);
    if (!body)
        return NULL;
    PrimeDemandElaboration elaboration = {
        .space = s,
        .arena = a,
        .strategy = strategy,
        .committed = committed,
    };
    return prime_demand_elaborate(&elaboration, body);
}

/* `(demand:report expression)`: the expression's values, as `reify` lists
 * them, and the records of the demand bubbles that ran while it was
 * evaluated, each once, in the order they were first made.  A report inside
 * another passes its records on to the outer one too. */
/* A report joins answers from possibly incompatible branch worlds. Resolve
 * private value carriers in each owning world before collecting its data;
 * only the common production prefix can be retained by the report itself. */
static Atom *prime_public_measurement_values(Arena *arena, OutcomeSet *values) {
    Atom **items = values->len
        ? cetta_malloc(sizeof(*items) * (size_t)values->len) : NULL;
    CettaExprLen count = 0u;
    for (CettaCount i = 0u; i < values->len; i++) {
        Atom *value = outcome_observe_top_value(arena,&values->items[i]);
        if (!value) {
            if (!eval_unwinding()) continue;
            free(items);
            return NULL;
        }
        items[count++] = value;
    }
    Atom *tuple = atom_expr(arena, items, count);
    free(items);
    return tuple;
}

static void prime_public_eval_demand_report(
    Space *space, Arena *arena, Atom *call, int fuel,
    const Bindings *current_env, bool preserve_bindings,
    OutcomeSet *outcomes) {
    if (expr_nargs(call) != 1u) {
        prime_public_emit(
            arena, outcomes,
            atom_error(arena, call,
                       atom_symbol(arena, "IncorrectNumberOfArguments")),
            current_env, preserve_bindings);
        return;
    }
    Atom *expression = bindings_apply_if_vars(
        current_env, arena, expr_arg(call, 0u));
    PrimeDemandReport report = {
        .outer = g_prime_demand_report,
        .arena = arena,
    };
    g_prime_demand_report = &report;
    OutcomeSet values;
    outcome_set_init(&values);
    metta_eval_bind(space, arena, expression, fuel, &values);
    g_prime_demand_report = report.outer;
    Atom *answers = prime_public_measurement_values(arena, &values);
    if (!answers) {
        free(report.items);
        outcome_set_free(&values);
        return;
    }
    Atom *result = atom_expr2(
        arena, answers,
        atom_expr(arena, report.items, (CettaExprLen)report.len));
    free(report.items);
    prime_public_emit_measurement(
        arena, outcomes, result, &values, current_env, preserve_bindings);
    outcome_set_free(&values);
}

/* `(cost:firings expression)`: the expression's values, as `reify` lists
 * them, and the number of firings their evaluation took, a firing being one
 * call rewritten by one rule of a declared definition (or the projection of
 * a pair).  Ordinary equations and built-in operations are not counted.  The
 * count is of this evaluation alone, nested evaluations included.  The
 * `cost:` namespace holds the named measurements of a run, each its own. */
static void prime_public_eval_cost_firings(
    Space *space, Arena *arena, Atom *call, int fuel,
    const Bindings *current_env, bool preserve_bindings,
    OutcomeSet *outcomes) {
    if (expr_nargs(call) != 1u) {
        prime_public_emit(
            arena, outcomes,
            atom_error(arena, call,
                       atom_symbol(arena, "IncorrectNumberOfArguments")),
            current_env, preserve_bindings);
        return;
    }
    Atom *expression = bindings_apply_if_vars(
        current_env, arena, expr_arg(call, 0u));
    OutcomeSet values;
    outcome_set_init(&values);
    uint64_t before = g_prime_rule_firings;
    metta_eval_bind(space, arena, expression, fuel, &values);
    uint64_t taken = g_prime_rule_firings - before;
    Atom *answers = prime_public_measurement_values(arena, &values);
    if (!answers) {
        outcome_set_free(&values);
        return;
    }
    Atom *result = atom_expr2(
        arena, answers,
        atom_int(arena, (int64_t)taken));
    prime_public_emit_measurement(
        arena, outcomes, result, &values, current_env, preserve_bindings);
    outcome_set_free(&values);
}

static bool prepared_pure_closed_invocation_try(
    Space *space, Arena *destination, const CettaInvocation *invocation,
    Atom *call, int fuel, bool entry_arguments_are_values,
    bool preserve_internal_values, PreparedPureProgramCache *program_cache,
    PreparedPureProgramKind kind, CettaCallOutcome *outcome);
static bool prepared_pure_closed_result_try(
    Space *space, Arena *destination, Atom *call, int fuel,
    bool entry_arguments_are_values, bool preserve_internal_values,
    PreparedPureProgramCache *program_cache,
    PreparedPureProgramKind kind, CettaCallOutcome *reply);

static bool prepared_pure_closed_call_try(
    Space *space, Arena *arena, Atom *call, int fuel,
    bool arguments_are_values, bool preserve_result,
    PreparedPureProgramCache *program_cache, CettaCallOutcome *outcome);

/* The worker shares call admission and typed completion. A raw one-step
 * observer alone projects completed data into a return instruction; a
 * source fallback remains an explicitly unfinished computation. */
static bool prepared_minimal_worker_call(
    Space *s, Arena *a, Atom *atom, const Bindings *outer_environment,
    int fuel, CettaCallOutcome *outcome) {
    *outcome = (CettaCallOutcome){0};
    SymbolId head_id = atom_head_symbol_id(atom);
    CettaExprLen nargs = atom && atom->kind == ATOM_EXPR && atom->expr.len
        ? expr_nargs(atom) : 0u;
    if (head_id == g_builtin_syms.minimal_map_atom && nargs == 3u) {
        Atom *mapped_value = NULL;
        PreparedFoldResult mapped = prepared_map_single_result(
            s, a,
            expr_arg(atom, 0u), expr_arg(atom, 1u),
            expr_arg(atom, 2u), outer_environment, fuel,
            false, NULL, &mapped_value);
        if (mapped == PREPARED_FOLD_VALUE) {
            *outcome = cetta_call_completed_value(mapped_value);
            return true;
        }
        if (mapped == PREPARED_FOLD_INTERRUPTED) {
            *outcome = cetta_call_interrupted();
            return true;
        }
    }

    if (head_id == g_builtin_syms.minimal_sum_by && nargs == 2u) {
        Atom *item = atom_var_with_id(
            a, "$__prepared_sum_item", fresh_var_id());
        Atom *projection = item
            ? atom_expr2(a, expr_arg(atom, 1u), item)
            : NULL;
        Atom *sum = NULL;
        PreparedFoldResult summed = projection
            ? prepared_sum_by_single_result(
                s, a, expr_arg(atom, 0u), item,
                projection, outer_environment, fuel, &sum)
            : PREPARED_FOLD_NOT_APPLICABLE;
        if (summed == PREPARED_FOLD_VALUE) {
            *outcome = cetta_call_value(sum);
            return true;
        }
        if (summed == PREPARED_FOLD_INTERRUPTED) {
            *outcome = cetta_call_interrupted();
            return true;
        }
    }

    if (head_id == g_builtin_syms.minimal_retain_top_k_by_number &&
        nargs == 4u) {
        Atom *retained_value = NULL;
        PreparedFoldResult retained =
            prepared_retain_top_k_by_number_single_result(
                s, a, expr_arg(atom, 0u), expr_arg(atom, 1u),
                expr_arg(atom, 2u), expr_arg(atom, 3u),
                outer_environment, fuel, &retained_value);
        if (retained == PREPARED_FOLD_VALUE) {
            *outcome = cetta_call_completed_value(retained_value);
            return true;
        }
        if (retained == PREPARED_FOLD_INTERRUPTED) {
            *outcome = cetta_call_interrupted();
            return true;
        }
    }

    if (head_id == g_builtin_syms.minimal_foldl_atom && nargs == 6u) {
        Atom *space_atom = expr_arg(atom, 5u);
        Space *fold_space =
            space_atom && space_atom->kind == ATOM_GROUNDED &&
                    space_atom->ground.gkind == GV_SPACE
                ? payload_resolve_space_read((Space *)space_atom->ground.ptr)
                : NULL;
        Atom *fold_value = NULL;
        PreparedFoldResult folded = prepared_foldl_single_result(
            fold_space, a,
            expr_arg(atom, 0u), expr_arg(atom, 1u),
            expr_arg(atom, 2u), expr_arg(atom, 3u),
            expr_arg(atom, 4u), outer_environment, fuel,
            NULL,
            &fold_value);
        if (folded == PREPARED_FOLD_VALUE) {
            *outcome = cetta_call_completed_value(fold_value);
            return true;
        }
        if (folded == PREPARED_FOLD_INTERRUPTED) {
            *outcome = cetta_call_interrupted();
            return true;
        }
    }

    if (head_id == g_builtin_syms.minimal_foldl_sequence && nargs == 7u) {
        PreparedSequenceRepresentation representation;
        if (!prepared_sequence_representation_lookup(
                expr_arg(atom, 0u), &representation)) {
            return false;
        }
        Atom *space_atom = expr_arg(atom, 6u);
        Space *fold_space =
            space_atom && space_atom->kind == ATOM_GROUNDED &&
                    space_atom->ground.gkind == GV_SPACE
                ? payload_resolve_space_read((Space *)space_atom->ground.ptr)
                : NULL;
        Atom *fold_value = NULL;
        Atom *sequence_items = expr_arg(atom, 1u);
        bool projected_source = false;
        bool erasure_attempted = false;
        bool erasure_admitted = false;
        Atom *sequence_source = prime_need_source_argument(
            sequence_items, &projected_source);
        PreparedFoldResult folded = PREPARED_FOLD_NOT_APPLICABLE;
        if (!projected_source) {
            folded = prepared_foldl_single_result(
                fold_space, a,
                sequence_items, expr_arg(atom, 2u),
                expr_arg(atom, 3u), expr_arg(atom, 4u),
                expr_arg(atom, 5u), outer_environment, fuel,
                &representation, &fold_value);
        }
        if (folded == PREPARED_FOLD_NOT_APPLICABLE) {
            erasure_attempted = true;
            Arena producer_scratch;
            arena_init(&producer_scratch);
            arena_set_runtime_kind(
                &producer_scratch, CETTA_ARENA_RUNTIME_KIND_SCRATCH);
            arena_set_hashcons(&producer_scratch, NULL);
            Atom *erased_source = NULL;
            bool erased_is_value = false;
            bool erased = prepared_sequence_erase_source(
                    expr_arg(atom, 0u), &producer_scratch,
                    sequence_source, &erased_source,
                    &erased_is_value);
            if (erased) {
                erasure_admitted = true;
                cetta_runtime_stats_inc(
                    CETTA_RUNTIME_COUNTER_PREPARED_SEQUENCE_ERASURE_ADMISSION);
            }
            CettaCallOutcome produced_return = {0};
            bool produced_ready = erased && (erased_is_value
                ? (produced_return = cetta_call_completed_value(erased_source), true)
                : prepared_pure_closed_call_try(fold_space, &producer_scratch,
                    erased_source, fuel, false, true, NULL, &produced_return));
            if (produced_ready && produced_return.kind != CETTA_CALL_VALUE) {
                *outcome = produced_return;
                arena_free(&producer_scratch);
                return true;
            }
            Atom *produced = produced_ready ? produced_return.term : NULL;
            if (produced) {
                folded = prepared_foldl_single_result(
                    fold_space, a,
                    produced, expr_arg(atom, 2u),
                    expr_arg(atom, 3u), expr_arg(atom, 4u),
                    expr_arg(atom, 5u), outer_environment, fuel,
                    NULL, &fold_value);
            }
            arena_free(&producer_scratch);
        }
        if (folded == PREPARED_FOLD_VALUE) {
            if (erasure_admitted) {
                cetta_runtime_stats_inc(
                    CETTA_RUNTIME_COUNTER_PREPARED_SEQUENCE_ERASURE_COMMIT);
            }
            *outcome = cetta_call_completed_value(fold_value);
            return true;
        }
        if (folded == PREPARED_FOLD_INTERRUPTED) {
            *outcome = cetta_call_interrupted();
            return true;
        }
        if (erasure_attempted) {
            cetta_runtime_stats_inc(
                CETTA_RUNTIME_COUNTER_PREPARED_SEQUENCE_ERASURE_DECLINE);
        }

        Atom *sequence_value = atom_var_with_id(
            a, "$__prepared_sequence_value", fresh_var_id());
        Atom *evaluate_sequence = projected_source
            ? expr_arg(atom, 1u)
            : (eval_current_language_id() == CETTA_LANGUAGE_HE
                ? atom_expr(a, (Atom *[]){
                    atom_symbol_id(a, g_builtin_syms.metta),
                    expr_arg(atom, 1u), atom_symbol(a, "%Undefined%"),
                    atom_space(a, fold_space)}, 4u)
                : atom_expr2(a, atom_symbol_id(a, g_builtin_syms.eval),
                             expr_arg(atom, 1u)));
        Atom *materialized_items = atom_expr2(
            a, atom_symbol_id(a, representation.materializer),
            sequence_value);
        Atom *ordinary_fold = atom_expr(
            a,
            (Atom *[]){
                atom_symbol_id(a, representation.fallback_fold),
                materialized_items,
                expr_arg(atom, 2u),
                expr_arg(atom, 3u),
                expr_arg(atom, 4u),
                expr_arg(atom, 5u),
            },
            6u);
        /* The fallback materializes a producer and invokes a higher-level
         * fold.  Unlike the admitted worker, neither is a single raw step. */
        Atom *evaluate_fold = eval_current_language_id() == CETTA_LANGUAGE_HE
            ? atom_expr(a, (Atom *[]){
                atom_symbol_id(a, g_builtin_syms.metta), ordinary_fold,
                atom_symbol(a, "%Undefined%"), atom_space(a, fold_space)}, 4u)
            : atom_expr2(a, atom_symbol_id(a, g_builtin_syms.eval), ordinary_fold);
        Atom *folded_value = atom_var_with_id(
            a, "$__prepared_sequence_folded", fresh_var_id());
        Atom *return_folded = atom_expr2(
            a, atom_symbol_id(a, g_builtin_syms.return_text), folded_value);
        Atom *finish_fold = atom_expr(
            a,
            (Atom *[]){
                atom_symbol_id(a, g_builtin_syms.chain),
                evaluate_fold,
                folded_value,
                return_folded,
            },
            4u);
        Atom *fallback = atom_expr(
            a,
            (Atom *[]){
                atom_symbol_id(a, g_builtin_syms.chain),
                evaluate_sequence,
                sequence_value,
                finish_fold,
            },
            4u);
        *outcome = cetta_call_value(fallback);
        return true;
    }

    return false;
}

/* One-step observers retain the authored instruction view. Ordinary worker
 * completion stays typed until that observation is actually requested. */
static Atom *prepared_minimal_worker_readback(Arena *arena, CettaCallOutcome outcome) {
    if (outcome.kind == CETTA_CALL_VALUE &&
        outcome.result_form == CETTA_CALL_RESULT_COMPLETED_VALUE)
        return atom_expr2(arena, atom_symbol_id(arena, g_builtin_syms.return_text),
            outcome.term);
    if (outcome.kind == CETTA_CALL_VALUE &&
        outcome.result_form == CETTA_CALL_RESULT_EXPRESSION)
        return outcome.term;
    eval_mark_interrupted(CETTA_EVAL_INCOMPLETE_HOST_FAILURE);
    return NULL;
}

/* HE's get-type takes an optional second argument, the space it types its
 * subject in, as Rust HE's does.  That space; or NULL, with *error_out the
 * error HE answers for an argument that is not a space (he-compat keeps
 * Rust HE's message, which names match). */
static Space *eval_get_type_space_argument(Arena *a, Atom *call,
                                           Atom *argument, Atom **error_out) {
    Atom *space_atom = argument;
    Atom *registered = registry_lookup_atom(space_atom);
    if (registered)
        space_atom = registered;
    if (space_atom->kind == ATOM_GROUNDED &&
        space_atom->ground.gkind == GV_SPACE)
        return payload_resolve_space_read((Space *)space_atom->ground.ptr);
    *error_out = atom_error(a, call, atom_symbol(a,
        active_profile_uses_rust_he_compat_semantics()
            ? "match expects a space as the first argument"
            : "get-type expects a space as its second argument"));
    return NULL;
}

