/* Candidate bindings are shared by its retained descendants.  Regrading
 * changes scheduling metadata, never those bindings or the occurrence set.
 * A publication made under other advice inherits that advice's key until a
 * score of its own completes, so a late score reaches every occurrence that
 * still inherits it. `follows` is NULL when the key is the cell's own. */
struct PrimeNativeAdvice {
    PrimeNativeAdvice *next;
    PrimeNativeAdvice *inherited;
    PrimeNativeAdvice *follows;
    bool scoring;
    /* The body as authored: an attached coefficient is `factor`, not part
     * of the subject a key pattern sees. */
    Atom *subject;
    Atom *factor;
    /* The accumulated coefficient of this publication in the enclosing
     * read's algebra, its own factor included, or NULL when unknown.  Under
     * a licensed monotonicity law it bounds every answer derived from it. */
    Atom *coefficient;
    Bindings environment;
    Atom *key;
    char *key_text;
};

/* The cell whose key an advice currently carries. A followed cell with no
 * score in flight can never hold a key apart from the cell it follows, so
 * lookups bypass it (path halving); a regrade restores the inherited links. */
static PrimeNativeAdvice *prime_native_advice_holder(PrimeNativeAdvice *advice) {
    while (advice && advice->follows) {
        PrimeNativeAdvice *next = advice->follows;
        if (next->follows && !next->scoring)
            advice->follows = next->follows;
        advice = advice->follows;
    }
    return advice;
}

