    uint64_t reclamation_shared_bytes_after;
    uint64_t reclamation_shared_bytes_reclaimed;
    uint64_t refusals;
    uint64_t answers;
    size_t maximum_frontier_length;
    size_t maximum_frontier_shared_bytes;
    size_t maximum_frontier_exclusive_bytes;
