#if CETTA_BUILD_WITH_PETTA_TYPECHECK_V2
#define PETTA_TYPECHECK_BOUNDARY_CACHE_SLOTS 64u
#define PETTA_TYPECHECK_BOUNDARY_PACKED_ARITY 32u

_Static_assert(
    PETTA_TYPECHECK_BOUNDARY_NONEMPTY_EXPRESSION <= 3,
    "boundary requirements must fit in two packed bits");

typedef struct {
    SpaceReadToken read;
    uint64_t global_mutation_epoch;
    SymbolId head;
    CettaExprLen arity;
    uint64_t packed_requirements;
    uint64_t nonzero_mask;
    bool valid;
} PettaTypecheckBoundaryCacheEntry;

typedef struct {
    PettaTypecheckBoundaryCacheEntry
        boundary_cache[PETTA_TYPECHECK_BOUNDARY_CACHE_SLOTS];
} PettaEvalMachineAnalysisState;
#endif

#define PETTA_BUILTIN_ADMISSION_CACHE_SLOTS 64u

_Static_assert(
    (PETTA_BUILTIN_ADMISSION_CACHE_SLOTS &
     (PETTA_BUILTIN_ADMISSION_CACHE_SLOTS - 1u)) == 0u,
    "builtin admission cache must use a power-of-two slot count");

typedef struct {
    SymbolId head;
    bool valid;
    bool allowed;
} PettaBuiltinAdmissionCacheEntry;

#define PETTA_RELATION_ADMISSION_CACHE_SLOTS 64u

_Static_assert(
    (PETTA_RELATION_ADMISSION_CACHE_SLOTS &
     (PETTA_RELATION_ADMISSION_CACHE_SLOTS - 1u)) == 0u,
    "relation admission cache must use a power-of-two slot count");

/* How the relational machine may dispatch one relation, valid for exactly
 * the program, library tables, foreign imports and symbol table it was
 * derived under. */
typedef struct {
    SpaceProgramToken program;
    uint64_t library_revision;
    uint64_t foreign_instance;
    uint64_t foreign_revision;
    uint64_t symbol_table_instance;
    CettaLibraryMask active_mask;
    SymbolId head;
    CettaExprLen arity;
    bool valid;
    PettaMachineSpaceQueryAdmission admission;
    /* Checked body entry may have a type signature or equations of other
     * arities. Full calls still need their independent call admission. */
    PettaMachineSpaceQueryAdmission open_admission;
} PettaRelationAdmissionCacheEntry;

typedef struct {
    SpaceProgramToken token;
    CettaOpenEquationRead reads;
    uint64_t admission_revision;
    CettaLibPrologReadToken foreign;
    CettaLibraryMask active_mask;
    /* What else the compilation read: the symbol table, the language and
     * profile, whose builtins and collection heads it consults, and
     * let/count fusion. */
    uint64_t symbol_table_instance;
    CettaLanguageId language;
    const CettaProfile *profile;
    SymbolId reify_head;
    bool count_fusion;
    CettaOpenEquationEntryKind entry_kind;
    SymbolId head;
    uint32_t arity;
    /* A non-admitted program is a dependency-stamped refusal certificate. */
    CettaOpenEquationProgram *program;
} PettaOpenProgramCacheEntry;

/* The session's compiled open-tier programs (CettaLibraryContext's
 * `petta_open_programs`), at most PETTA_OPEN_PROGRAM_CACHE_BOUND. */
enum { PETTA_OPEN_PROGRAM_CACHE_BOUND = 4096u };
typedef struct {
    PettaOpenProgramCacheEntry *entries;
    size_t len;
    size_t cap;
} PettaOpenProgramCache;

typedef struct {
    int fuel;
    bool data_ops;
    bool typecheck_ops;
    bool pattern_query_ready;
    uint64_t diagnostic_transition_limit;
    uint64_t diagnostic_transitions_permitted;
    bool diagnostic_transition_exhausted;
    CettaSearchControllerPolicy controller_policy;
    bool controller_admitted;
    bool controller_measure_representation;
    bool controller_quantum_active;
    bool controller_quantum_expired;
    uint64_t controller_quantum_limit;
    uint64_t controller_quantum_transitions;
    CettaObservationContract observation_contract;
    CettaControlPlan control_plan;
    PettaEvalControllerStats controller_stats;
    PettaEvalTransaction *transaction;
    uint64_t semantic_authority_epoch;
    CettaLibraryContext *library_context;
    const PettaProgramRevisionProjection *program_projection;
    PreparedPureProgramCache prepared_pure_cache;
    PettaBuiltinAdmissionCacheEntry
        builtin_admission_cache[PETTA_BUILTIN_ADMISSION_CACHE_SLOTS];
    uint32_t builtin_admission_imports;
    uint32_t builtin_admission_modules;
    PettaRelationAdmissionCacheEntry
        relation_admission_cache[PETTA_RELATION_ADMISSION_CACHE_SLOTS];
#if CETTA_BUILD_WITH_PETTA_TYPECHECK_V2
    PettaEvalMachineAnalysisState *analysis_state;
#endif
} PettaEvalMachineContext;

static PettaTransactionCatalog *petta_eval_private_catalog(void *raw, const Space *space) {
    PettaEvalMachineContext *context = raw;
    for (PettaEvalTransaction *tx = context->transaction; tx; tx = tx->parent)
        for (size_t i = 0u; i < tx->space_len; i++)
            if (tx->spaces[i].working == space) return tx->spaces[i].catalog;
    return NULL;
}

static Space *petta_eval_private_map(void *raw, Space *space) {
    PettaEvalMachineContext *context = raw;
    for (;;) {
        Space *before = space;
        for (PettaEvalTransaction *tx = context->transaction; tx; tx = tx->parent)
            for (size_t i = 0u; i < tx->space_len; i++)
                if (tx->spaces[i].original == space) space = tx->spaces[i].working;
        if (space == before) return space;
    }
}

static Space *petta_eval_private_image_at(void *raw, size_t index) {
    PettaEvalMachineContext *context = raw;
    for (PettaEvalTransaction *tx = context->transaction; tx; tx = tx->parent) {
        if (index < tx->space_len) return tx->spaces[index].working;
        index -= tx->space_len;
    }
    return NULL;
}

static void petta_eval_machine_context_storage(const PettaEvalMachineContext *context,
        CettaStorageCensus *census) {
    if (!context || !cetta_storage_object(census, context, 0u,
            CETTA_STORAGE_VISITED)) return;
    prepared_pure_program_cache_storage(&context->prepared_pure_cache, census);
#if CETTA_BUILD_WITH_PETTA_TYPECHECK_V2
    if (context->analysis_state)
        cetta_storage_object(census, context->analysis_state,
            sizeof(*context->analysis_state), CETTA_STORAGE_BLOCK);
#endif
    petta_eval_transaction_storage(context->transaction, census);
}

static bool petta_eval_machine_is_data_constructor(
    void *opaque, SymbolId head, CettaExprLen arity) {
    PettaEvalMachineContext *context = opaque;
    if (!context || head == SYMBOL_ID_NONE)
        return false;
    const char *name = symbol_bytes(g_symbols, head);
    if (!name)
        return false;
    if (context->data_ops && strcmp(name, "data") == 0)
        return true;
    return context->typecheck_ops &&
        (strcmp(name, "make-list") == 0 ||
         (arity == 2u && strcmp(name, "the") == 0));
}

#if CETTA_BUILD_WITH_PETTA_TYPECHECK_V2
static bool petta_eval_machine_boundary_requirement_satisfied(
    PettaTypecheckBoundaryRequirement requirement, Atom *value,
    const char **requirement_name) {
    if (requirement_name)
        *requirement_name = NULL;
    if (requirement == PETTA_TYPECHECK_BOUNDARY_NONE)
        return true;
    if (requirement == PETTA_TYPECHECK_BOUNDARY_NONVAR) {
        if (requirement_name)
            *requirement_name =
                "is unbound: a -[committed]-> function requires bound "
                "arguments";
        return value && value->kind != ATOM_VAR;
    }
    if (requirement == PETTA_TYPECHECK_BOUNDARY_PROPER_LIST) {
        CettaExprLen ignored = 0u;
        if (requirement_name)
            *requirement_name =
                "is not a proper list: its -[committed]-> proof "
                "requires a bound proper list";
        return petta_semantics_logical_list_length(value, &ignored);
    }
    if (requirement ==
        PETTA_TYPECHECK_BOUNDARY_NONEMPTY_EXPRESSION) {
        if (requirement_name)
            *requirement_name =
                "is the empty expression: car-atom expects a non-empty "
                "expression";
        /* Only the empty expression refutes this requirement.  A machine
         * placeholder or a non-expression atom is not evidence of emptiness;
         * ordinary car-atom semantics may still handle it or defer it. */
        return value &&
            (value->kind != ATOM_EXPR || value->expr.len > 0u);
    }
    return false;
}

static PettaMachineBoundaryResult
petta_eval_machine_validate_ready_call(
    void *opaque, Space *space, Atom *call,
    char *diagnostic, size_t diagnostic_size) {
    cetta_runtime_stats_inc(
        CETTA_RUNTIME_COUNTER_PETTA_TYPECHECK_BOUNDARY_ENTRY);
    PettaEvalMachineContext *context = opaque;
    if (diagnostic && diagnostic_size > 0u)
        diagnostic[0] = '\0';
    if (!context || !context->analysis_state || !space || !call ||
        call->kind != ATOM_EXPR || call->expr.len == 0u)
        return PETTA_MACHINE_BOUNDARY_ACCEPTED;
    SymbolId head = atom_head_symbol_id(call);
    if (head == SYMBOL_ID_NONE)
        return PETTA_MACHINE_BOUNDARY_ACCEPTED;
    CettaExprLen arity = call->expr.len - 1u;
    PettaProgram *program = context->library_context
        ? context->library_context->petta_program : NULL;
    if (!program) {
        if (diagnostic && diagnostic_size > 0u) {
            snprintf(
                diagnostic, diagnostic_size,
                "PeTTa typechecker fault: no live program for call boundary");
        }
        return PETTA_MACHINE_BOUNDARY_FAULT;
    }

    if (arity == 0u)
        return PETTA_MACHINE_BOUNDARY_ACCEPTED;

    SpaceReadToken read = space_read_token(space);
    uint64_t global_mutation_epoch = space_global_mutation_epoch();
    PettaTypecheckBoundaryRequirement stack_plan[
        PETTA_TYPECHECK_BOUNDARY_PACKED_ARITY];
    PettaTypecheckBoundaryRequirement *plan = stack_plan;
    bool heap_plan = false;
    uint64_t nonzero_mask = 0u;
    uint64_t packed = 0u;

    if (arity <= PETTA_TYPECHECK_BOUNDARY_PACKED_ARITY) {
        size_t slot =
            ((size_t)head * 31u + (size_t)arity * 7u +
             (size_t)read.revision +
             (size_t)global_mutation_epoch * 13u) &
            (PETTA_TYPECHECK_BOUNDARY_CACHE_SLOTS - 1u);
        PettaTypecheckBoundaryCacheEntry *cached =
            &context->analysis_state->boundary_cache[slot];
        if (cached->valid && cached->read.space == read.space &&
            cached->read.instance_id == read.instance_id &&
            cached->read.revision == read.revision &&
            cached->global_mutation_epoch == global_mutation_epoch &&
            cached->head == head && cached->arity == arity) {
            cetta_runtime_stats_inc(
                CETTA_RUNTIME_COUNTER_PETTA_TYPECHECK_BOUNDARY_PLAN_CACHE_HIT);
            packed = cached->packed_requirements;
            nonzero_mask = cached->nonzero_mask;
        } else {
            cetta_runtime_stats_inc(
                CETTA_RUNTIME_COUNTER_PETTA_TYPECHECK_BOUNDARY_PLAN_CACHE_MISS);
            if (!petta_typecheck_call_boundary_plan(
                    program, space, head, arity,
                    stack_plan, (size_t)arity)) {
                if (diagnostic && diagnostic_size > 0u) {
                    snprintf(
                        diagnostic, diagnostic_size,
                        "PeTTa typechecker fault: could not derive call boundary for %s/%u",
                        symbol_bytes(g_symbols, head), (unsigned)arity);
                }
                return PETTA_MACHINE_BOUNDARY_FAULT;
            }
            for (CettaExprIndex position = 0u;
                 position < arity; position++) {
                uint64_t requirement = (uint64_t)stack_plan[position];
                packed |= requirement << (2u * position);
                if (requirement != PETTA_TYPECHECK_BOUNDARY_NONE)
                    nonzero_mask |= UINT64_C(1) << position;
            }
            *cached = (PettaTypecheckBoundaryCacheEntry){
                .read = read,
                .global_mutation_epoch = global_mutation_epoch,
                .head = head,
                .arity = arity,
                .packed_requirements = packed,
                .nonzero_mask = nonzero_mask,
                .valid = true,
            };
        }
        if (nonzero_mask == 0u) {
            cetta_runtime_stats_inc(
                CETTA_RUNTIME_COUNTER_PETTA_TYPECHECK_BOUNDARY_PLAN_ALL_NONE);
            return PETTA_MACHINE_BOUNDARY_ACCEPTED;
        }
    } else {
        if (!cetta_expr_len_fits_size(arity) ||
            (size_t)arity > SIZE_MAX / sizeof(*plan)) {
            return PETTA_MACHINE_BOUNDARY_FAULT;
        }
        plan = cetta_malloc(sizeof(*plan) * (size_t)arity);
        heap_plan = true;
        cetta_runtime_stats_inc(
            CETTA_RUNTIME_COUNTER_PETTA_TYPECHECK_BOUNDARY_PLAN_CACHE_MISS);
        if (!petta_typecheck_call_boundary_plan(
                program, space, head, arity,
                plan, (size_t)arity)) {
            free(plan);
            if (diagnostic && diagnostic_size > 0u) {
                snprintf(
                    diagnostic, diagnostic_size,
                    "PeTTa typechecker fault: could not derive call boundary for %s/%u",
                    symbol_bytes(g_symbols, head), (unsigned)arity);
            }
            return PETTA_MACHINE_BOUNDARY_FAULT;
        }
    }

    for (CettaExprIndex position = 0u; position < arity; position++) {
        PettaTypecheckBoundaryRequirement requirement =
            arity <= PETTA_TYPECHECK_BOUNDARY_PACKED_ARITY
                ? (PettaTypecheckBoundaryRequirement)
                      ((packed >> (2u * position)) & UINT64_C(3))
                : plan[position];
        if (requirement == PETTA_TYPECHECK_BOUNDARY_NONE)
            continue;
        cetta_runtime_stats_inc(
            CETTA_RUNTIME_COUNTER_PETTA_TYPECHECK_BOUNDARY_POSITION_TESTED);
        Atom *value = call->expr.elems[position + 1u];
        const char *requirement_name = NULL;
        bool satisfied =
            petta_eval_machine_boundary_requirement_satisfied(
                requirement, value, &requirement_name);
        if (!satisfied) {
            if (heap_plan)
                free(plan);
            if (diagnostic && diagnostic_size > 0u) {
                snprintf(
                    diagnostic, diagnostic_size,
                    "PeTTa type error: argument %u of %s/%u %s",
                    (unsigned)position + 1u,
                    symbol_bytes(g_symbols, head), (unsigned)arity,
                    requirement_name ? requirement_name
                                     : "violates its committed boundary");
            }
            return PETTA_MACHINE_BOUNDARY_REFUTED;
        }
    }
    if (heap_plan)
        free(plan);
    return PETTA_MACHINE_BOUNDARY_ACCEPTED;
}
#endif

enum {
    PETTA_MATCH_POLICY_RELATIONAL_STRUCTURAL_V1 = 1u,
    PETTA_DEMAND_POLICY_STRICT_CALL_ARGUMENTS_V1 = 1u,
};

#define PETTA_SEMANTIC_PRESENTATION_ID_V1 UINT64_C(1)

typedef struct PettaEvalNamedMutex {
    Atom *key;
    uint32_t hash;
    pthread_mutex_t mutex;
    struct PettaEvalNamedMutex *next;
} PettaEvalNamedMutex;

#define PETTA_EVAL_MUTEX_BUCKETS 127u

static pthread_once_t g_petta_eval_mutex_once =
    PTHREAD_ONCE_INIT;
static pthread_mutex_t g_petta_eval_mutex_registry_lock;
static Arena g_petta_eval_mutex_name_arena;
static PettaEvalNamedMutex *
    g_petta_eval_mutex_buckets[PETTA_EVAL_MUTEX_BUCKETS];

static void petta_eval_mutex_registry_init(void) {
    int status = pthread_mutex_init(
        &g_petta_eval_mutex_registry_lock, NULL);
    if (status != 0) {
        fprintf(
            stderr,
            "fatal: failed to initialize PeTTa mutex registry\n");
        abort();
    }
    /* pthread_once may run in a Hyperpose worker.  A process-lifetime mutex
       key must therefore not inherit that worker's branch-local hash-cons
       table: the table is destroyed when the branch joins. */
    arena_init_detached(&g_petta_eval_mutex_name_arena);
    arena_set_runtime_kind(
        &g_petta_eval_mutex_name_arena,
        CETTA_ARENA_RUNTIME_KIND_PERSISTENT);
}

static bool petta_eval_machine_mutex_acquire(
    void *context, Arena *arena, Atom *name,
    void **handle) {
    (void)context;
    (void)arena;
    if (handle)
        *handle = NULL;
    if (!name || !handle || atom_has_vars(name))
        return false;
    if (pthread_once(
            &g_petta_eval_mutex_once,
            petta_eval_mutex_registry_init) != 0) {
        return false;
    }
    uint32_t hash = atom_hash(name);
    uint32_t bucket = hash % PETTA_EVAL_MUTEX_BUCKETS;
    if (pthread_mutex_lock(
            &g_petta_eval_mutex_registry_lock) != 0) {
        return false;
    }
    PettaEvalNamedMutex *entry =
        g_petta_eval_mutex_buckets[bucket];
    while (entry) {
        if (entry->hash == hash &&
            atom_eq(entry->key, name)) {
            break;
        }
        entry = entry->next;
    }
    if (!entry) {
        entry = cetta_malloc(sizeof(*entry));
        memset(entry, 0, sizeof(*entry));
        entry->key = atom_deep_copy(
            &g_petta_eval_mutex_name_arena, name);
        pthread_mutexattr_t attributes;
        bool initialized =
            entry->key &&
            pthread_mutexattr_init(&attributes) == 0;
        if (initialized) {
            initialized =
                pthread_mutexattr_settype(
                    &attributes,
                    PTHREAD_MUTEX_RECURSIVE) == 0 &&
                pthread_mutex_init(
                    &entry->mutex, &attributes) == 0;
            pthread_mutexattr_destroy(&attributes);
        }
        if (!initialized) {
            free(entry);
            pthread_mutex_unlock(
                &g_petta_eval_mutex_registry_lock);
            return false;
        }
        entry->hash = hash;
        entry->next =
            g_petta_eval_mutex_buckets[bucket];
        g_petta_eval_mutex_buckets[bucket] = entry;
    }
    pthread_mutex_unlock(
        &g_petta_eval_mutex_registry_lock);
    if (pthread_mutex_lock(&entry->mutex) != 0)
        return false;
    *handle = entry;
    return true;
}

static void petta_eval_machine_mutex_release(
    void *context, void *handle) {
    (void)context;
    PettaEvalNamedMutex *entry = handle;
    if (entry)
        (void)pthread_mutex_unlock(&entry->mutex);
}

static uint64_t petta_eval_machine_prime_begin_relation_call(
    void *context, SpaceReadToken read, Atom *query) {
    (void)context;
    (void)read;
    (void)query;
    return prime_need_fresh_source_occurrence();
}

static inline __attribute__((always_inline)) bool prime_need_relation_use_kernel(
    void *context, Arena *owner, uint64_t call_occurrence,
    const PettaEquationCandidate *candidate, Atom *result,
    const Bindings *environment, Bindings *evidence_delta,
    bool retain_rule_payload) {
    (void)context;
    if (!owner || call_occurrence == 0u || !candidate ||
        !candidate->equation || !result || !environment ||
        !evidence_delta ||
        candidate->occurrence.logical_index == UINT64_MAX) {
        return false;
    }
#if CETTA_BUILD_WITH_PRIME_CAUSAL_RECEIPTS
    if (retain_rule_payload) {
        PrimeNeedReceipt base = *bindings_receipt_view(environment);
        PrimeNeedReceipt used;
        if (!prime_need_receipt_merge(&base, &g_prime_need_receipt_active) ||
            !prime_need_receipt_use_equation_branch_local(
                owner, &base, call_occurrence,
                (uint64_t)candidate->occurrence.logical_index + 1u,
                candidate->equation, result, &used)) {
            return false;
        }
        bindings_prime_set(evidence_delta, NULL, NULL, 0u, &used, NULL);
    } else {
        bindings_prime_set(evidence_delta, NULL, NULL, 0u, NULL, NULL);
    }
#else
    (void)retain_rule_payload;
    bindings_prime_set(evidence_delta, NULL, NULL, 0u, NULL, NULL);
#endif
    return bindings_refresh_occurrence_token(evidence_delta);
}

/* Both workers establish a fresh result occurrence. Only the recorded worker
 * reads the receipt payload; scope entry selects it, including on resumption.
 * The bridge retains this dispatcher rather than a creator-thread TLS address. */
static bool prime_need_relation_use_plain(
    void *context, Arena *owner, uint64_t call_occurrence,
    const PettaEquationCandidate *candidate, Atom *result,
    const Bindings *environment, Bindings *evidence_delta) {
    return prime_need_relation_use_kernel(context, owner, call_occurrence,
        candidate, result, environment, evidence_delta, false);
}

#if CETTA_BUILD_WITH_PRIME_CAUSAL_RECEIPTS
static bool prime_need_relation_use_recorded(
    void *context, Arena *owner, uint64_t call_occurrence,
    const PettaEquationCandidate *candidate, Atom *result,
    const Bindings *environment, Bindings *evidence_delta) {
    return prime_need_relation_use_kernel(context, owner, call_occurrence,
        candidate, result, environment, evidence_delta, true);
}
#endif

