static bool petta_eval_machine_prime_atom_is_episode_value(
    Space *space, Atom *atom, uint32_t depth);

/* A Prime relation normally enters the eager relational machine only after
 * every argument is already a value.  A small closed scalar expression from
 * the declared type-pure capability is an equally safe boundary when direct
 * evaluation proves it total and fault-free: call-by-need and eagerness then
 * have the same value, fault, effect, and termination observation in an
 * unbounded episode.  The fixed node budget keeps admission from executing an
 * unbounded optimizer workload.  Once established, the same proof licenses
 * replacing that scalar occurrence with its value in the machine-private
 * prepared call; source syntax and source-occurrence evidence remain the
 * semantic authority. */
static bool petta_eval_machine_prime_replay_safe_scalar_op(
    SymbolId head) {
    return head == g_builtin_syms.op_plus ||
           head == g_builtin_syms.op_minus ||
           head == g_builtin_syms.op_mul ||
           head == g_builtin_syms.op_div ||
           head == g_builtin_syms.op_floor_div ||
           head == g_builtin_syms.op_mod ||
           head == g_builtin_syms.op_lt ||
           head == g_builtin_syms.op_gt ||
           head == g_builtin_syms.op_le ||
           head == g_builtin_syms.op_ge ||
           head == g_builtin_syms.numeric_eq;
}

static bool petta_eval_machine_prime_replay_safe_numeric_value(
    const Atom *atom) {
    return atom && atom->kind == ATOM_GROUNDED &&
        (atom->ground.gkind == GV_INT ||
         atom->ground.gkind == GV_FLOAT);
}

static bool petta_eval_machine_prime_fold_replay_safe_total(
    Space *space, Arena *scratch, Atom *atom, uint32_t depth,
    uint32_t *budget, Atom **value_out) {
    if (value_out)
        *value_out = NULL;
    if (!space || !scratch || !atom || !budget || *budget == 0u ||
        !value_out || depth > 64u ||
        atom_is_error(atom) || atom_is_empty(atom) ||
        prime_need_atom_has_observable_ref(atom)) {
        return false;
    }
    (*budget)--;
    if (petta_eval_machine_prime_atom_is_episode_value(
            space, atom, depth)) {
        *value_out = atom;
        return true;
    }
    if (atom->kind != ATOM_EXPR || atom->expr.len == 0u ||
        atom->expr.len - 1u > UINT32_MAX ||
        atom->expr.elems[0]->kind != ATOM_SYMBOL ||
        !petta_eval_machine_prime_replay_safe_scalar_op(
            atom_symbol_current_id(atom->expr.elems[0])) ||
        !grounded_op_is_type_pure(atom_symbol_current_id(atom->expr.elems[0]))) {
        return false;
    }

    CettaExprLen nargs = atom->expr.len - 1u;
    Atom **arguments = nargs
        ? arena_alloc(
              scratch, sizeof(*arguments) * (size_t)nargs)
        : NULL;
    if (nargs && !arguments)
        return false;
    for (CettaExprIndex index = 0u; index < nargs; index++) {
        if (!petta_eval_machine_prime_fold_replay_safe_total(
                space, scratch, atom->expr.elems[index + 1u],
                depth + 1u, budget, &arguments[index]) ||
            !petta_eval_machine_prime_replay_safe_numeric_value(
                arguments[index])) {
            return false;
        }
    }
    Atom *value = grounded_dispatch(
        scratch, atom->expr.elems[0], arguments, (uint32_t)nargs);
    if (!value || atom_is_error(value) || atom_is_empty(value) ||
        prime_need_atom_has_observable_ref(value) ||
        !petta_eval_machine_prime_atom_is_episode_value(
            space, value, depth + 1u)) {
        return false;
    }
    *value_out = value;
    return true;
}

static bool petta_eval_machine_prime_prepare_resolved_call(
    void *opaque, Space *space, Arena *arena,
    Atom *resolved_call, Atom **prepared_call) {
    if (prepared_call)
        *prepared_call = NULL;
    if (!arena || !resolved_call || !prepared_call ||
        resolved_call->kind != ATOM_EXPR ||
        resolved_call->expr.len == 0u) {
        return false;
    }
    PettaEvalMachineContext *context = opaque;
    PettaProgram *program = context && context->library_context
        ? context->library_context->petta_program : NULL;
    PettaResolvedCallClass call_class =
        petta_program_classify_resolved_call(
        program, space, resolved_call);
    bool safe = call_class != PETTA_RESOLVED_CALL_UNSAFE;
    Arena replay_guard_arena;
    bool replay_guard_arena_ready = false;
    Atom **guard_values = NULL;
    uint32_t guard_budget = 64u;
    uint32_t prepared_argument_count = 0u;
    if (call_class == PETTA_RESOLVED_CALL_RELATION) {
        for (CettaExprIndex index = 1u;
             safe && index < resolved_call->expr.len; index++) {
            Atom *argument = resolved_call->expr.elems[index];
            if (petta_eval_machine_prime_atom_is_episode_value(
                    space, argument, 0u)) {
                continue;
            }
            if (!guard_values) {
                if (!cetta_expr_len_mul_fits_size(
                        resolved_call->expr.len,
                        sizeof(*guard_values))) {
                    safe = false;
                    break;
                }
                guard_values = cetta_malloc(
                    sizeof(*guard_values) *
                    (size_t)resolved_call->expr.len);
                memcpy(
                    guard_values, resolved_call->expr.elems,
                    sizeof(*guard_values) *
                    (size_t)resolved_call->expr.len);
            }
            if (!replay_guard_arena_ready) {
                arena_init(&replay_guard_arena);
                arena_set_runtime_kind(
                    &replay_guard_arena,
                    CETTA_ARENA_RUNTIME_KIND_SCRATCH);
                arena_set_hashcons(&replay_guard_arena, NULL);
                replay_guard_arena_ready = true;
            }
            Atom *guard_value = NULL;
            safe = petta_eval_machine_prime_fold_replay_safe_total(
                space, &replay_guard_arena, argument, 0u,
                &guard_budget, &guard_value);
            if (safe) {
                guard_values[index] = guard_value;
                prepared_argument_count++;
            }
        }
    }
    if (safe && prepared_argument_count > 0u) {
        Atom **elements = arena_alloc(
            arena, sizeof(*elements) *
                (size_t)resolved_call->expr.len);
        safe = elements != NULL;
        for (CettaExprIndex index = 0u;
             safe && index < resolved_call->expr.len; index++) {
            bool prepared_argument = index > 0u &&
                guard_values[index] !=
                    resolved_call->expr.elems[index];
            elements[index] = prepared_argument
                ? atom_deep_copy(arena, guard_values[index])
                : resolved_call->expr.elems[index];
            safe = elements[index] != NULL;
        }
        if (safe) {
            *prepared_call = atom_expr(
                arena, elements, resolved_call->expr.len);
            safe = *prepared_call != NULL;
        }
    } else if (safe) {
        *prepared_call = resolved_call;
    }
    if (safe && prepared_argument_count > 0u) {
        cetta_runtime_stats_add(
            CETTA_RUNTIME_COUNTER_PRIME_RELATIONAL_PLAN_REPLAY_SAFE_ARGUMENT,
            prepared_argument_count);
    }
    free(guard_values);
    if (replay_guard_arena_ready)
        arena_free(&replay_guard_arena);
    if (!safe) {
        cetta_runtime_stats_inc(
            CETTA_RUNTIME_COUNTER_PRIME_RELATIONAL_PLAN_RESOLVED_CALL_DECLINE);
    }
    if (!safe && getenv("CETTA_PRIME_RELATIONAL_MACHINE_TRACE")) {
        fputs("[prime-relational-machine] resolved call decline ",
              stderr);
        atom_print(resolved_call, stderr);
        fputc('\n', stderr);
    }
    return safe;
}

static bool petta_eval_transaction_reserve(
    void **items, size_t *capacity, size_t needed,
    size_t item_size) {
    if (needed <= *capacity)
        return true;
    size_t next = *capacity ? *capacity * 2u : 8u;
    while (next < needed) {
        if (next > SIZE_MAX / 2u)
            return false;
        next *= 2u;
    }
    if (next > SIZE_MAX / item_size)
        return false;
    *items = *items
        ? cetta_realloc(*items, next * item_size)
        : cetta_malloc(next * item_size);
    *capacity = next;
    return true;
}

static PettaEvalTransactionSpace *
petta_eval_transaction_space_by_original(
    PettaEvalTransaction *transaction, Space *space) {
    if (!transaction || !space)
        return NULL;
    for (size_t index = 0u;
         index < transaction->space_len; index++) {
        if (transaction->spaces[index].original == space)
            return &transaction->spaces[index];
    }
    return NULL;
}

static PettaEvalTransactionSpace *
petta_eval_transaction_space_by_working(
    PettaEvalTransaction *transaction, Space *space) {
    if (!transaction || !space)
        return NULL;
    for (size_t index = 0u;
         index < transaction->space_len; index++) {
        if (transaction->spaces[index].working == space)
            return &transaction->spaces[index];
    }
    return NULL;
}

static Space *petta_eval_transaction_clone_space(
    PettaEvalTransaction *transaction, Space *space) {
    if (!transaction || !space)
        return NULL;
    CETTA_SCOPED_SHARED_TRANSITION(transaction_enrollment);
    if (petta_eval_transaction_space_by_working(transaction, space))
        return space;
    if (transaction->parent) {
        space = petta_eval_transaction_clone_space(transaction->parent, space);
        if (!space)
            return NULL;
    }
    PettaEvalTransactionSpace *existing =
        petta_eval_transaction_space_by_original(
            transaction, space);
    if (existing)
        return existing->working;

    __attribute__((cleanup(cetta_shared_transition_guard_leave)))
    CettaSharedTransitionGuard shared_snapshot = {0};
    cetta_shared_transition_guard_enter(&shared_snapshot);

    cetta_runtime_stats_inc(
        CETTA_RUNTIME_COUNTER_PETTA_TRANSACTION_SPACE_CLONE);
    cetta_runtime_stats_add(
        CETTA_RUNTIME_COUNTER_PETTA_TRANSACTION_SPACE_CLONE_ROW,
        space_length64(space));
    if (!petta_eval_transaction_reserve(
            (void **)&transaction->spaces,
            &transaction->space_cap,
            transaction->space_len + 1u,
            sizeof(*transaction->spaces))) {
        return NULL;
    }
    Space *working = space_heap_clone_shallow(space);
    if (!working)
        return NULL;
    /* A shallow image shares its source term universe, so inherited immutable
       plans retain their source representation. Catalog vectors are private;
       nested evaluator scopes find an enclosing image before the live program. */
    PettaProgram *program = eval_current_language_id() == CETTA_LANGUAGE_PETTA && g_library_context
        ? g_library_context->petta_program : NULL;
    PettaTransactionCatalog *catalog = program
        ? petta_program_transaction_catalog_new(program, space, working, true) : NULL;
    if (program && !catalog) {
        space_free(working);
        free(working);
        return NULL;
    }
    PettaEvalTransactionSpace entry = {
        .original = space,
        .working = working,
        .catalog = catalog,
        .original_read = space_read_token(space),
        .working_base_revision = space_revision(working),
    };
    transaction->spaces[transaction->space_len++] = entry;
    return working;
}

static PettaEvalTransactionState *
petta_eval_transaction_state_by_original(
    PettaEvalTransaction *transaction, StateCell *state) {
    if (!transaction || !state)
        return NULL;
    for (size_t index = 0u;
         index < transaction->state_len; index++) {
        if (transaction->states[index].original == state)
            return &transaction->states[index];
    }
    return NULL;
}

static PettaEvalTransactionState *
petta_eval_transaction_state_by_working(
    PettaEvalTransaction *transaction, StateCell *state) {
    if (!transaction || !state)
        return NULL;
    for (size_t index = 0u;
         index < transaction->state_len; index++) {
        if (transaction->states[index].working == state)
            return &transaction->states[index];
    }
    return NULL;
}

static StateCell *petta_eval_transaction_clone_state(
    PettaEvalTransaction *transaction, StateCell *state) {
    if (!transaction || !state)
        return NULL;
    CETTA_SCOPED_SHARED_TRANSITION(transaction_state_enrollment);
    if (petta_eval_transaction_state_by_working(transaction, state))
        return state;
    if (transaction->parent) {
        state = petta_eval_transaction_clone_state(transaction->parent, state);
        if (!state)
            return NULL;
    }
    PettaEvalTransactionState *existing =
        petta_eval_transaction_state_by_original(
            transaction, state);
    if (existing)
        return existing->working;
    if (!petta_eval_transaction_reserve(
            (void **)&transaction->states,
            &transaction->state_cap,
            transaction->state_len + 1u,
            sizeof(*transaction->states))) {
        return NULL;
    }
    StateCell *working = cetta_malloc(sizeof(*working));
    working->value = atom_deep_copy(
        transaction->machine_arena, state->value);
    working->content_type = atom_deep_copy(
        transaction->machine_arena, state->content_type);
    working->payload_owner_epoch = state->payload_owner_epoch;
    working->payload_export_owner_epoch =
        state->payload_export_owner_epoch;
    if (!working->value || !working->content_type) {
        free(working);
        return NULL;
    }
    PettaEvalTransactionState entry = {
        .original = state,
        .working = working,
        .initial_value = working->value,
        .initial_content_type = working->content_type,
    };
    transaction->states[transaction->state_len++] = entry;
    return working;
}

static Atom *petta_eval_transaction_rebind_atom(
    PettaEvalTransaction *transaction, Arena *arena,
    Atom *atom, bool to_working) {
    if (!transaction || !arena || !atom)
        return NULL;
    if (atom->kind == ATOM_GROUNDED) {
        if (atom->ground.gkind == GV_SPACE) {
            Space *space = (Space *)atom->ground.ptr;
            if (to_working) {
                PettaEvalTransactionSpace *mapped =
                    petta_eval_transaction_space_by_working(
                        transaction, space);
                if (mapped)
                    return atom_space(arena, mapped->working);
                Space *working =
                    petta_eval_transaction_clone_space(
                        transaction, space);
                return working ? atom_space(arena, working) : NULL;
            }
            PettaEvalTransactionSpace *mapped =
                petta_eval_transaction_space_by_working(
                    transaction, space);
            return atom_space(
                arena, mapped ? mapped->original : space);
        }
        if (atom->ground.gkind == GV_STATE) {
            StateCell *state = (StateCell *)atom->ground.ptr;
            if (to_working) {
                PettaEvalTransactionState *mapped =
                    petta_eval_transaction_state_by_working(
                        transaction, state);
                if (mapped)
                    return atom_state(arena, mapped->working);
                StateCell *working =
                    petta_eval_transaction_clone_state(
                        transaction, state);
                return working ? atom_state(arena, working) : NULL;
            }
            PettaEvalTransactionState *mapped =
                petta_eval_transaction_state_by_working(
                    transaction, state);
            return atom_state(
                arena, mapped ? mapped->original : state);
        }
        return atom_deep_copy(arena, atom);
    }
    if (atom->kind == ATOM_SYMBOL)
        return atom_symbol_copy(arena, atom);
    if (atom->kind == ATOM_VAR)
        return atom_var_like(arena, atom, atom->var_id);
    if (atom->kind != ATOM_EXPR)
        return atom_deep_copy(arena, atom);
    Atom **elements = arena_alloc(
        arena, sizeof(*elements) * (size_t)atom->expr.len);
    if (atom->expr.len > 0u && !elements)
        return NULL;
    for (CettaExprIndex index = 0u;
         index < atom->expr.len; index++) {
        elements[index] = petta_eval_transaction_rebind_atom(
            transaction, arena, atom->expr.elems[index],
            to_working);
        if (!elements[index])
            return NULL;
    }
    return atom_expr(arena, elements, atom->expr.len);
}

static Space *petta_eval_private_space_image(Space *space) {
    PettaEvalTransaction *transaction = petta_eval_active_transaction();
    /* Resolving an identity selects its transaction image. A newly tracked
     * original stays empty until publication and outlives a rollback. */
    return transaction && space
        ? petta_eval_transaction_clone_space(transaction, space) : space;
}

/* Shared evaluator callbacks can resolve resources without entering another
 * search machine. They still use the active transaction's private image;
 * PeTTa's named global state keeps its separate nontransactional registry. */
static StateCell *petta_eval_private_state_image(StateCell *cell) {
    PettaEvalTransaction *transaction = petta_eval_active_transaction();
    return transaction && cell
        ? petta_eval_transaction_clone_state(transaction, cell) : cell;
}

static Registry *petta_eval_named_state_registry(Registry *registry) {
    PettaEvalTransaction *transaction = petta_eval_active_transaction();
    return transaction ? transaction->side_effect_registry : registry;
}

static Atom *petta_eval_export_persistent_value(
        Arena *arena, Atom *value, const StateCell *destination) {
    for (PettaEvalTransaction *transaction = petta_eval_active_transaction();
         transaction && value; transaction = transaction->parent) {
        /* A private destination may retain references owned by its own
         * transaction. A named/nontransactional destination may retain none. */
        if (destination && petta_eval_transaction_state_by_working(
                transaction, (StateCell *)destination))
            break;
        value = petta_eval_transaction_rebind_atom(transaction, arena, value, false);
    }
    return value;
}

static bool petta_eval_export_outcomes(Arena *arena, OutcomeSet *outcomes, CettaCount first) {
    if (!petta_eval_active_transaction())
        return true;
    for (CettaCount i = first; outcomes && i < outcomes->len; i++) {
        Outcome *result = &outcomes->items[i];
        if (result->atom) {
            result->atom = petta_eval_export_persistent_value(arena, result->atom, NULL);
            if (!result->atom)
                return false;
        }
        if (result->materialized_atom) {
            result->materialized_atom = petta_eval_export_persistent_value(
                arena, result->materialized_atom, NULL);
            if (!result->materialized_atom)
                return false;
        }
    }
    return true;
}

static bool petta_eval_bind_space_name(Arena *arena, const Atom *name, Atom *value) {
    PettaEvalTransaction *transaction = petta_eval_active_transaction();
    Registry *registry = transaction ? &transaction->registry : g_registry;
    Atom *stored = transaction
        ? petta_eval_transaction_rebind_atom(transaction, arena, value, true)
        : atom_deep_copy(arena, value);
    return stored && registry_bind_symbol(registry, name, stored);
}

static void petta_eval_transaction_destroy(
    PettaEvalTransaction *transaction) {
    if (!transaction)
        return;
    registry_binding_publication_free(transaction->binding_publication);

    for (size_t index = 0u;
         index < transaction->space_len; index++) {
        petta_program_transaction_catalog_free(transaction->spaces[index].publication_catalog);
        Space *publication = transaction->spaces[index].publication;
        if (publication) {
            space_free(publication);
            free(publication);
        }
        Space *working = transaction->spaces[index].working;
        if (working) {
            petta_program_transaction_catalog_free(transaction->spaces[index].catalog);
            space_free(working);
            free(working);
        }
    }
    for (size_t index = 0u;
         index < transaction->state_len; index++) {
        free(transaction->states[index].working);
    }
    registry_free(&transaction->registry);
    free(transaction->initial_registry_values);
    free(transaction->spaces);
    free(transaction->states);
    CettaSharedTransitionGuard shared_lifetime =
        transaction->shared_lifetime;
    transaction->shared_lifetime.held = false;
    free(transaction);
    cetta_shared_transition_guard_leave(&shared_lifetime);
}

static bool petta_eval_transaction_bind_entry(
    Registry *registry, const Registry *source,
    uint32_t source_index, Atom *value) {
    if (!registry || !source || source_index >= source->len ||
        !value) {
        return false;
    }
    uint32_t length_before = registry->len;
    return registry_copy_entry(registry, source, source_index, value) &&
           registry->len == length_before + 1u;
}

static bool petta_eval_machine_switch_enabled(void) {
    /* PeTTa's foreign calls, delayed goals and occurrence roles are semantic
     * operations of the relational core. Disabling an execution tier must
     * not send them to the HE fallback, where they become symbolic data. */
    return eval_current_language_id() == CETTA_LANGUAGE_PETTA ||
        g_active_petta_search_machine;
}

static bool petta_eval_machine_stats_enabled(void) {
    return g_active_petta_machine_stats;
}

static bool petta_eval_search_controller_request(
        CettaSearchControllerPolicy *policy) {
    if (!policy || !g_active_search_controller_requested)
        return false;
    *policy = g_active_search_controller;
    return true;
}

static bool petta_eval_symbol_name_is(
    SymbolId id, const char *name) {
    const char *actual =
        id == SYMBOL_ID_NONE ? NULL
                             : symbol_bytes(g_symbols, id);
    return actual && name && strcmp(actual, name) == 0;
}

/* SWI-PeTTa's fun/1 for `head` beyond its builtins: a function of the
 * program's own space, the evaluation's root space. */
static bool petta_eval_function_registered(Space *space, SymbolId head) {
    PettaProgram *program = g_library_context
        ? g_library_context->petta_program : NULL;
    Space *self = g_eval_root_space ? g_eval_root_space : space;
    return program && self &&
        petta_program_function_registered(program, self, head);
}

static bool petta_eval_open_function_registered(void *opaque,
                                                SymbolId head) {
    (void)opaque;
    return petta_eval_function_registered(NULL, head);
}

static bool petta_eval_machine_builtin_allowed(
        void *opaque, SymbolId head) {
    PettaEvalMachineContext *context = opaque;
    PettaBuiltinAdmissionCacheEntry *entry = NULL;
    if (context && head != SYMBOL_ID_NONE) {
        uint32_t imports = g_library_context ? g_library_context->active_mask : 0u;
        uint32_t modules = g_library_context ? g_library_context->loaded_module_len : 0u;
        if (context->builtin_admission_imports != imports ||
            context->builtin_admission_modules != modules) {
            memset(context->builtin_admission_cache, 0, sizeof(context->builtin_admission_cache));
            context->builtin_admission_imports = imports;
            context->builtin_admission_modules = modules;
        }
        entry = &context->builtin_admission_cache[
            (size_t)head &
            (PETTA_BUILTIN_ADMISSION_CACHE_SLOTS - 1u)];
        if (entry->valid && entry->head == head)
            return entry->allowed;
    }
    const char *name = head == SYMBOL_ID_NONE
        ? NULL : symbol_bytes(g_symbols, head);
    bool allowed = !name || active_builtin_allowed(name);
    /* Knowing a PeTTa intrinsic does not grant it to another language.
     * Unknown policy names remain legal authored calls, but they cannot
     * select the shared backend's intrinsic invocation plan. */
    CettaLanguageId language = eval_current_language_id();
    if (language != CETTA_LANGUAGE_PETTA &&
        symbol_id_is_builtin_for(head, CETTA_LANGUAGE_PETTA) &&
        !symbol_id_is_builtin_for(head, language))
        allowed = false;
    if (entry) {
        *entry = (PettaBuiltinAdmissionCacheEntry){
            .head = head,
            .valid = true,
            .allowed = allowed,
        };
    }
    return allowed;
}

static void petta_eval_machine_advance_semantic_authority(
    PettaEvalMachineContext *context) {
    if (!context)
        return;
    context->semantic_authority_epoch =
        context->semantic_authority_epoch == UINT64_MAX
            ? 1u : context->semantic_authority_epoch + 1u;
}

static bool petta_eval_machine_semantic_authority_token(
    void *opaque, PettaMachineAuthorityToken *token) {
    PettaEvalMachineContext *context = opaque;
    if (!context || !token)
        return false;
    CettaLibPrologReadToken foreign = {0};
    if (context->library_context &&
        context->library_context->lib_prolog) {
        foreign = cetta_lib_prolog_read_token(
            context->library_context->lib_prolog);
    }
    uint64_t translator_revision = context->library_context
        ? cetta_library_petta_translator_rule_revision(
              context->library_context)
        : 0u;
    *token = (PettaMachineAuthorityToken){
        .words = {
            foreign.instance_id,
            foreign.revision,
            context->semantic_authority_epoch,
            context->transaction ? UINT64_C(1) : UINT64_C(0),
            translator_revision,
        },
        .length = 5u,
    };
    return true;
}

static CettaBranchAdmission petta_eval_machine_admit_branch_capture(
    void *opaque, Space *space) {
    PettaEvalMachineContext *context = opaque;
    if (!context || !space || !context->controller_admitted ||
        context->transaction) {
        return (CettaBranchAdmission){
            .status = CETTA_BRANCH_ADMISSION_DEFERRED,
        };
    }
    CettaLibPrologReadToken foreign = {0};
    if (context->library_context &&
        context->library_context->lib_prolog) {
        foreign = cetta_lib_prolog_read_token(
            context->library_context->lib_prolog);
    }
    uint64_t translator_revision = context->library_context
        ? cetta_library_petta_translator_rule_revision(
              context->library_context)
        : 0u;
    return (CettaBranchAdmission){
        .status = CETTA_BRANCH_ADMISSION_AVAILABLE,
        .capacity = CETTA_BRANCH_CAPTURE_MULTI_SHOT,
        .authority = {
            .words = {
                UINT64_C(0x43455454412d4d41),
                space_instance_id(space),
                space_revision(space),
                context->semantic_authority_epoch,
                foreign.instance_id,
                foreign.revision,
                space_global_mutation_epoch(),
                translator_revision,
            },
            .length = 8u,
        },
    };
}

